// Core value types for the PHP implementation
#pragma once
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <memory>
#include <vector>
#include <unordered_map>
#include <functional>
#include <stdexcept>

enum VK { VKNull = 0, VKBool, VKInt, VKFloat, VKStr, VKArr, VKObj, VKRes };
enum Vis { VIS_PUBLIC = 0, VIS_PROTECTED, VIS_PRIVATE };

struct Value;
struct ArrData;
struct ObjData;
struct ClassDef;
struct FuncDef;
struct Interp;

typedef std::shared_ptr<Value> Ref;

struct Value {
  VK k = VKNull;
  bool b = false;
  int64_t i = 0;
  double d = 0;
  std::string s;
  std::shared_ptr<ArrData> arr;
  std::shared_ptr<ObjData> obj;
  Value() {}
  explicit Value(int64_t v) : k(VKInt), i(v) {}
  explicit Value(int v) : k(VKInt), i(v) {}
  explicit Value(bool v) : k(VKBool), b(v) {}
  explicit Value(double v) : k(VKFloat), d(v) {}
  explicit Value(const char *v) : k(VKStr), s(v) {}
  explicit Value(std::string v) : k(VKStr), s(std::move(v)) {}
};

struct ArrData {
  struct Entry { Value key; Ref val; };
  std::vector<Entry> e;
  std::unordered_map<int64_t, size_t> iidx;
  std::unordered_map<std::string, size_t> sidx;
  int64_t next = 0;
  size_t size() const { return e.size(); }
  size_t find(const Value &k) const;
  void set(const Value &key, Ref v);
  void set(const Value &key, const Value &v);
  Ref get(const Value &key);      // returns cell or null if missing
  bool has(const Value &key) const { return find(key) != (size_t)-1; }
  void erase(const Value &key);
  void pushBack(Ref v) { set(Value(next), v); }
  int64_t maxIntKey() const;
};

struct ObjData {
  std::shared_ptr<ClassDef> cls;
  std::string clsName;              // display class name
  struct Prop { std::string name; Ref val; };
  std::vector<Prop> props;
  std::unordered_map<std::string, size_t> pidx;
  uint64_t handle = 0;
  // special closures
