  bool inited = false;
  Ref getProp(const std::string &name);
  void setProp(const std::string &name, Ref v, bool declared=false);
};

struct Resource {
  int type = 0;
  void *ptr = nullptr;
  long id = 0;
  std::string name;
};
EOF
