  if (k < n && s[k]=='.') { isf = true; k++; while (k < n && isdigit((unsigned char)s[k])) { gotDigit = true; k++; } }
  if (gotDigit && k < n && (s[k]=='e'||s[k]=='E')) {
    size_t k2 = k+1;
    if (k2 < n && (s[k2]=='+'||s[k2]=='-')) k2++;
    bool ed = false;
    while (k2 < n && isdigit((unsigned char)s[k2])) { ed = true; k2++; }
    if (ed) { isf = true; k = k2; }
  }
