size_t ArrData::find(const Value &k) const {
  if (k.k == VKInt) { auto it = iidx.find(k.i); return it == iidx.end() ? (size_t)-1 : it->second; }
  if (k.k == VKStr) { auto it = sidx.find(k.s); return it == sidx.end() ? (size_t)-1 : it->second; }
  return (size_t)-1;
}
void ArrData::set(const Value &key, Ref v) {
  size_t pos = find(key);
  if (pos != (size_t)-1) { e[pos].val = v; return; }
  Value kk = key;
  if (kk.k == VKInt) {
    if (kk.i > next - 1) next = kk.i + 1;
    e.push_back({kk, v});
    iidx[kk.i] = e.size() - 1;
  } else {
    e.push_back({kk, v});
    sidx[kk.s] = e.size() - 1;
  }
}
