  if (pos == (size_t)-1) return nullptr;
  return e[pos].val;
}
void ArrData::erase(const Value &key) {
  size_t pos = find(key);
  if (pos == (size_t)-1) return;
  if (key.k == VKInt) iidx.erase(key.i); else sidx.erase(key.s);
  e.erase(e.begin() + pos);
  // rebuild indices
  iidx.clear(); sidx.clear();
  for (size_t i = 0; i < e.size(); i++) {
    if (e[i].key.k == VKInt) iidx[e[i].key.i] = i; else sidx[e[i].key.s] = i;
  }
}
