bool toBool(const Value &v) {
  switch (v.k) {
    case VKNull: return false;
    case VKBool: return v.b;
    case VKInt: return v.i != 0;
    case VKFloat: return v.d != 0;
    case VKStr: return !(v.s.size() == 0 || (v.s.size() == 1 && v.s[0] == '0'));
    case VKArr: return v.arr->e.size() != 0;
    case VKObj: return true;
    case VKRes: return true;
  }
  return false;
}

int64_t toInt(const Value &v, int *warnType) {
  switch (v.k) {
    case VKNull: return 0;
    case VKBool: return v.b ? 1 : 0;
    case VKInt: return v.i;
    case VKFloat: {
      double d = v.d;
      if (std::isnan(d)) return 0;
      if (d >= 9223372036854775808.0) return INT64_MIN; // PHP wraps
      if (d <= -9223372036854775809.0) return INT64_MIN;
      return (int64_t)d;
    }
    case VKStr: {
      int64_t iv; double dv; bool isf;
      strToNum(v.s, &isf, &iv, &dv);
      return isf ? (int64_t)dv : iv;
    }
    case VKArr: return v.arr->e.size() != 0 ? 1 : 0;
    case VKObj: return 1;
    case VKRes: return 0;
  }
  return 0;
}

