  switch (v.k) {
    case VKNull: return 0;
    case VKBool: return v.b ? 1 : 0;
    case VKInt: return (double)v.i;
    case VKFloat: return v.d;
    case VKStr: { int64_t iv; double dv; bool isf; strToNum(v.s, &isf, &iv, &dv); return isf ? dv : (double)iv; }
    case VKArr: return v.arr->e.size() != 0 ? 1 : 0;
    case VKObj: return 1;
    case VKRes: return 0;
  }
  return 0;
}

std::string toStr(const Value &v, Interp *I, bool *isNan) {
  switch (v.k) {
    case VKNull: return "";
    case VKBool: return v.b ? "1" : "";
    case VKInt: return intToStr(v.i);
    case VKFloat: {
      if (isNan) *isNan = std::isnan(v.d);
      if (I && std::isnan(v.d)) I->logError(E_WARNING, "unexpected NAN value was coerced to string", -1);
      return fmtFloat(v.d, I ? I->precision : 14);
    }
    case VKStr: return v.s;
    case VKArr: if (I) I->logError(E_WARNING, "Array to string conversion", -1); return "Array";
    case VKObj: {
      if (I) return I->objectToString(v.obj);
