    bool na = isNumericStr(a.s, &ia, &da), nb = isNumericStr(b.s, &ib, &db);
    if (na && nb) {
      if (a.k == VKStr && b.k == VKStr) {
        bool fa = false, fb = false;
        bool f1, f2;
        strToNum(a.s, &f1, &ia, &da);
        strToNum(b.s, &f2, &ib, &db);
        if (f1 || f2) {
          double x = f1 ? da : (double)ia, y = f2 ? db : (double)ib;
          if (x == y) return 0;
          if (std::isnan(x) || std::isnan(y)) return 0;
          return x < y ? -1 : 1;
        }
        return ia == ib ? 0 : (ia < ib ? -1 : 1);
      }
    }
    int c = a.s.compare(b.s);
    return c < 0 ? -1 : c > 0 ? 1 : 0;
  }
  if (a.k == VKStr || b.k == VKStr) {
    int64_t ia, ib; double da, db;
    const Value &sv = a.k == VKStr ? a : b;
    const Value &nv = a.k == VKStr ? b : a;
    bool isNum = isNumericStr(sv.s, &ia, &db);
    if (isNum) {
      double x, y;
      bool sf = false;
      strToNum(sv.s, &sf, &ia, &da);
      if (nv.k == VKFloat) { x = sf ? da : (double)ia; y = nv.d; }
      else if (nv.k == VKInt) { x = sf ? da : (double)ia; y = (double)nv.i; }
      else { x = sf ? da : (double)ia; y = toFloat(nv); }
      if (x == y) return 0;
      if (std::isnan(x) || std::isnan(y)) return 0;
      return x < y ? -1 : 1;
    }
    // non-numeric string vs number: compare as strings
    std::string x = sv.s;
    std::string y = nv.k == VKFloat ? fmtFloat(nv.d, I ? I->precision : 14) :
                    nv.k == VKInt ? intToStr(nv.i) : toStr(nv, I);
    int c = x.compare(y);
    return c < 0 ? -1 : c > 0 ? 1 : 0;
  }
  if (a.k == VKInt && b.k == VKInt) return a.i == b.i ? 0 : (a.i < b.i ? -1 : 1);
  if (a.k == VKFloat || b.k == VKFloat) {
    double x = toFloat(a), y = toFloat(b);
    if (std::isnan(x) || std::isnan(y)) return 0;
    if (x == y) return 0;
    return x < y ? -1 : 1;
  }
  return 0;
}

bool eqValues(const Value &a, const Value &b, Interp *I) {
  if (a.k == VKObj && b.k == VKObj) {
    if (a.obj == b.obj) return true;
    if (a.obj->clsName != b.obj->clsName) return false;
    return cmpValues(a, b, I) == 0;
  }
  if ((a.k == VKObj || a.k == VKArr) != (b.k == VKObj || b.k == VKArr)) {
    // array/object vs scalar
    if (a.k == VKArr && b.k == VKArr) {}
    return false;
  }
  if (a.k == VKRes || b.k == VKRes) {
    if (a.k != VKRes || b.k != VKRes) return false;
    return a.res->id == b.res->id;
  }
  if (a.k == VKBool || b.k == VKBool) return toBool(a) == toBool(b);
  if (a.k == VKNull && b.k == VKNull) return true;
  if (a.k == VKNull || b.k == VKNull) {
    const Value &o = a.k == VKNull ? b : a;
    if (o.k == VKStr) return o.s == "";
    return toInt(o) == 0;
  }
  if (a.k == VKStr && b.k == VKStr) {
    int64_t ia, ib; double da, db;
    if (isNumericStr(a.s, &ia, &da) && isNumericStr(b.s, &ib, &db)) {
      bool f1, f2; strToNum(a.s, &f1, &ia, &da); strToNum(b.s, &f2, &ib, &db);
      if (f1 || f2) { double x = f1 ? da : (double)ia, y = f2 ? db : (double)ib;
        if (std::isnan(x) || std::isnan(y)) return false; return x == y; }
      return ia == ib;
    }
    return a.s == b.s;
  }
  if (a.k == VKStr || b.k == VKStr) {
    const Value &sv = a.k == VKStr ? a : b;
    const Value &nv = a.k == VKStr ? b : a;
    int64_t ia, ib; double da, db;
    if (!isNumericStr(sv.s, &ia, &db)) {
      // non-numeric string vs number: compare as strings
      std::string y = nv.k == VKFloat ? fmtFloat(nv.d, I ? I->precision : 14) : nv.k == VKInt ? intToStr(nv.i) : toStr(nv, I);
      return sv.s == y;
    }
    bool f1, f2; strToNum(sv.s, &f1, &ia, &da);
    double x = f1 ? da : (double)ia;
    double y = nv.k == VKFloat ? nv.d : (double)toInt(nv);
    if (std::isnan(x) || std::isnan(y)) return false;
    return x == y;
  }
  if (a.k == VKInt && b.k == VKInt) return a.i == b.i;
  if (a.k == VKFloat || b.k == VKFloat) {
    double x = toFloat(a), y = toFloat(b);
    if (std::isnan(x) || std::isnan(y)) return false;
    return x == y;
  }
  if (a.k == VKArr && b.k == VKArr) {
    if (a.arr->e.size() != b.arr->e.size()) return false;
    for (size_t i = 0; i < a.arr->e.size(); i++) {
      if (!eqValues(a.arr->e[i].key, b.arr->e[i].key, I)) return false;
      if (!eqValues(*a.arr->e[i].val, *b.arr->e[i].val, I)) return false;
    }
    return true;
  }
  return false;
}

// strict identity comparison
bool identValues(const Value &a, const Value &b) {
  if (a.k != b.k) {
    // int and float of same value are not identical
    return false;
  }
  switch (a.k) {
    case VKNull: return true;
    case VKBool: return a.b == b.b;
    case VKInt: return a.i == b.i;
    case VKFloat: return a.d == b.d;
    case VKStr: return a.s == b.s;
    case VKArr: return a.arr == b.arr;
    case VKObj: return a.obj == b.obj;
    case VKRes: return a.res == b.res;
  }
  return false;
}

bool strEquals(const std::string &a, const std::string &b, bool ci) {
  if (!ci) return a == b;
  return lc(a) == lc(b);
}

bool strStartsWith(const std::string &s, const std::string &p) {
  return s.size() >= p.size() && memcmp(s.data(), p.data(), p.size()) == 0;
}
bool strEndsWith(const std::string &s, const std::string &p) {
  return s.size() >= p.size() && memcmp(s.data() + s.size() - p.size(), p.data(), p.size()) == 0;
}
std::string replaceAll(std::string s, const std::string &a, const std::string &b) {
  if (a.empty()) return s;
  size_t pos = 0;
  while ((pos = s.find(a, pos)) != std::string::npos) { s.replace(pos, a.size(), b); pos += b.size(); }
  return s;
}
