#include "lex.h"
#include <cctype>
#include <cstdlib>
#include <cstring>
#include <cstdio>

Lexer::Lexer(const char *src, size_t len, const std::string &file) : p_(src), end_(src+len), file_(file) {}

std::string Lexer::processEscapes(const std::string &in, bool interp) {
  std::string out;
  out.reserve(in.size());
  for (size_t i = 0; i < in.size(); i++) {
    char c = in[i];
    if (c != '\\') { out += c; continue; }
    if (i + 1 >= in.size()) { out += '\\'; continue; }
    char n = in[i+1];
    i++;
    switch (n) {
      case 'n': out += '\n'; break;
      case 'r': out += '\r'; break;
      case 't': out += '\t'; break;
      case 'v': out += '\v'; break;
      case 'f': out += '\f'; break;
      case 'e': out += '\x1b'; break;
      case '0': case '1': case '2': case '3': case '4': case '5': case '6': case '7': {
        int v = 0, cnt = 0;
        while (i < in.size() && in[i] >= '0' && in[i] <= '7' && cnt < 3) { v = v*8 + (in[i]-'0'); i++; cnt++; }
        i--;
        out += (char)v;
        break;
      }
      case 'x': {
        int v = 0, cnt = 0;
        while (i+1 < in.size() && isxdigit((unsigned char)in[i+1]) && cnt < 2) { i++; v = v*16 + (isdigit((unsigned char)in[i]) ? in[i]-'0' : (tolower(in[i])-'a'+10)); cnt++; }
        out += (char)v;
        break;
      }
      case 'u': {
        if (i+1 < in.size() && in[i+1] == '{') {
          i += 2;
          unsigned long v = 0;
          while (i < in.size() && isxdigit((unsigned char)in[i])) { v = v*16 + (isdigit((unsigned char)in[i]) ? in[i]-'0' : (tolower(in[i])-'a'+10)); i++; }
          if (i < in.size() && in[i] == '}') i++;
          if (v < 0x80) out += (char)v;
          else if (v < 0x800) { out += (char)(0xC0|(v>>6)); out += (char)(0x80|(v&0x3F)); }
          else if (v < 0x10000) { out += (char)(0xE0|(v>>12)); out += (char)(0x80|((v>>6)&0x3F)); out += (char)(0x80|(v&0x3F)); }
          else if (v < 0x110000) { out += (char)(0xF0|(v>>18)); out += (char)(0x80|((v>>12)&0x3F)); out += (char)(0x80|((v>>6)&0x3F)); out += (char)(0x80|(v&0x3F)); }
          else { out += '?'; }
        } else out += 'u';
        break;
      }
      default: out += n; break;
    }
  }
  return out;
}

Token Lexer::scanHTML() {
  Token t; t.line = line;
  if (p_ >= end_) { t.type = TK_EOF; return t; }
  const char *start = p_;
  const char *q = p_;
  while (q < end_) {
    if (q[0] == '<' && q+1 < end_ && q[1] == '?') break;
    q++;
  }
  p_ = q;
  t.type = TK_STR;
  t.text.assign(start, q - start);
  t.parts.push_back({0, t.text});
  t.heredoc = true; // raw html
  return t;
}

Token Lexer::scanOne() {
  Token t; t.line = line;
  if (html_) {
    // look for opening tag
    const char *q = p_;
    if (q+1 >= end_ || q[0] != '<' || q[1] != '?') {
      Token h = scanHTML();
      if (h.type == TK_EOF) { html_ = true; return h; }
      // now at <?
    }
    // consume <?php or <?= or <?
    if (q+5 <= end_ && strncmp(q, "<?php", 5) == 0) {
      const char *r = q + 5;
      while (r < end_ && (*r==' '||*r=='\t'||*r=='\n'||*r=='\r')) r++;
      line += 1; // approximation; newlines counted elsewhere
      p_ = r;
      html_ = false;
    } else if (q+3 <= end_ && strncmp(q, "<?=", 3) == 0) {
      p_ = q + 3; html_ = false;
      Token e; e.type = TK_NAME; e.text = "echo"; e.line = line;
      buf.push_back(e);
    } else if (q+2 <= end_ && q[1] == '?') {
      p_ = q + 2; html_ = false;
    } else {
      // no tag: html output to end
      Token h = scanHTML();
      if (h.type == TK_EOF) return h;
    }
  }
  // skip whitespace and comments
  for (;;) {
    while (p_ < end_ && (*p_==' '||*p_=='\t'||*p_=='\r'||*p_=='\n'||*p_=='\v'||*p_=='\f')) {
      if (*p_ == '\n') line++;
      p_++;
    }
    if (p_ < end_ && (p_[0]=='/' && p_+1 < end_ && (p_[1]=='/' || p_[1]=='*'))) {
      if (p_[1] == '/') {
        while (p_ < end_ && *p_ != '\n') p_++;
      } else {
        p_ += 2;
        int depth = 1;
        while (p_ < end_) {
          if (p_[0]=='/' && p_+1 < end_ && p_[1]=='*') { p_ += 2; depth++; continue; }
          if (p_[0]=='*' && p_+1 < end_ && p_[1]=='/') { p_ += 2; depth--; if (!depth) break; continue; }
          if (*p_ == '\n') line++;
          p_++;
        }
      }
      continue;
    }
    if (p_ < end_ && p_[0]=='#' && !(p_+1 < end_ && p_[1]=='[')) {
      while (p_ < end_ && *p_ != '\n') p_++;
      continue;
    }
    break;
  }
  t.line = line;
  if (p_ >= end_) { t.type = TK_EOF; return t; }
  if (p_[0] == '?' && p_+1 < end_ && p_[1] == '>') {
    // end of php
    p_ += 2;
    html_ = true;
    Token h = scanHTML();
    return h;
  }
  char c = p_[0];
  if (isalpha((unsigned char)c) || c == '_' || (unsigned char)c >= 0x80) {
    std::string name = readName();
    t.type = TK_NAME; t.text = name; return t;
  }
  if (c == '$') {
    p_++;
    if (p_ < end_ && (isalpha((unsigned char)*p_) || *p_=='_' || (unsigned char)*p_ >= 0x80)) {
      std::string name = readName();
      t.type = TK_VAR; t.text = name; return t;
    } else if (p_ < end_ && *p_ == '{') {
      // ${...} variable variable in code
      t.type = TK_VAR; t.text = ""; // special
      return t;
    } else {
      t.type = TK_VAR; t.text = ""; return t;
    }
  }
  if (isdigit((unsigned char)c) || (c=='.' && p_+1 < end_ && isdigit((unsigned char)p_[1]))) return readNumber();
  if (c == '\'') return readSingle();
  if (c == '"') return readDouble(false);
  if (c == '`') return readBacktick();
  if (c == '<' && p_+4 <= end_ && p_[1]=='<' && p_[2]=='<' && !isspace((unsigned char)p_[3]) && p_[3] != '=' ) {
    // heredoc
    p_ += 3;
    bool nowdoc = false;
    std::string name;
    if (*p_ == '\'') { nowdoc = true; p_++; name = readName(); if (*p_ == '\'') p_++; }
    else name = readName();
    // skip to newline
    while (p_ < end_ && *p_ != '\n') p_++;
    if (p_ < end_) { p_++; line++; }
    std::string body;
    const char *start = p_;
    // find closing line
    for (;;) {
      const char *ln = p_;
      while (ln < end_ && *ln != '\n') ln++;
      std::string content(p_, ln - p_);
      std::string trimmed = content;
      // strip leading whitespace for comparison
      size_t k = 0;
      while (k < trimmed.size() && (trimmed[k]==' '||trimmed[k]=='\t')) k++;
      if (trimmed.compare(k, name.size(), name) == 0 && (k + name.size() >= trimmed.size() || trimmed[k+name.size()]==';' || trimmed[k+name.size()]==',' || trimmed[k+name.size()]==')' || trimmed[k+name.size()]=='}' || trimmed[k+name.size()]==':' || trimmed[k+name.size()]=='.') ) {
        size_t indent = k;
        // strip indent from each line
        std::string result;
        {
          // process original body with indent removal
          std::string raw(start, ln - start);
          // remove `indent` leading whitespace from each line (only up to first \n of each line)
          std::string out2;
          size_t pos = 0;
          bool first = true;
          while (pos <= raw.size()) {
            size_t e = raw.find('\n', pos);
