          t.parts.push_back({6, key});
        }
        if (p_ < end_ && *p_ == ']') p_++;
      } else if (p_ < end_ && p_[0]=='-' && p_+1 < end_ && p_[1]=='>') {
        p_ += 2;
        t.parts.push_back({8, readName()});
      }
      continue;
    }
    if (c == '$' && p_+1 < end_ && p_[1] == '{') {
      if (!body.empty()) { t.parts.push_back({0, body}); body.clear(); }
      p_ += 2;
      std::string name;
      while (p_ < end_ && *p_ != '}') name += *p_++;
      if (p_ < end_) p_++;
      t.parts.push_back({3, name});
      continue;
    }
    if (c == '{' && p_+1 < end_ && p_[1] == '$') {
      if (!body.empty()) { t.parts.push_back({0, body}); body.clear(); }
      // find matching }
      p_++;
      int depth = 1;
      const char *start = p_;
      while (p_ < end_) {
        if (*p_ == '{') depth++;
        else if (*p_ == '}') { depth--; if (!depth) break; }
        else if (*p_ == '"' || *p_ == '\'') {
