std::string Lexer::readName() {
  std::string r;
  while (p_ < end_) {
    unsigned char c = (unsigned char)*p_;
    if (isalnum(c) || c == '_' || c >= 0x80) { r += (char)c; p_++; }
    else break;
  }
  return r;
}

Token Lexer::readNumber() {
  Token t; t.line = line;
  const char *start = p_;
