}

Token Lexer::readSingle() {
  Token t; t.line = line;
  p_++;
  std::string body;
  while (p_ < end_) {
    if (*p_ == '\\' && p_+1 < end_ && (p_[1]=='\'' || p_[1]=='\\')) { body += p_[1]; p_ += 2; continue; }
    if (*p_ == '\\') { body += '\\'; p_++; continue; }
    if (*p_ == '\'') { p_++; break; }
    if (*p_ == '\n') line++;
    body += *p_++;
  }
  t.type = TK_STR; t.text = body;
  return t;
}

Token Lexer::readDouble(bool heredoc) {
  Token t; t.line = line;
  p_++; // opening quote
  std::string body;
  t.type = TK_ENCAP;
  while (p_ < end_) {
