        p_++;
      }
      std::string src(start, p_ - start);
      if (p_ < end_) p_++;
      t.parts.push_back({2, src});
      continue;
    }
    if (c == '\n') line++;
    body += c; p_++;
  }
  if (!body.empty()) t.parts.push_back({0, body});
  return t;
}

Token Lexer::readBacktick() {
  Token t; t.line = line;
  t.type = TK_ENCAP;
  t.text = "`";
  p_++;
  std::string body;
  while (p_ < end_) {
    char c = *p_;
    if (c == '`') { p_++; break; }
    if (c == '\\') { body += '\\'; p_++; if (p_ < end_) { body += *p_; p_++; } continue; }
    if (c == '$' && p_+1 < end_ && (isalpha((unsigned char)p_[1]) || p_[1]=='_' || (unsigned char)p_[1] >= 0x80)) {
      if (!body.empty()) { t.parts.push_back({0, body}); body.clear(); }
      p_++;
      std::string name = readName();
      t.parts.push_back({1, name});
      if (p_ < end_ && *p_ == '[') {
        p_++;
        std::string key;
        while (p_ < end_ && isalnum((unsigned char)*p_)) key += *p_++;
        if (p_ < end_ && *p_ == ']') p_++;
        t.parts.push_back({6, key});
      }
      continue;
    }
    if (c == '{' && p_+1 < end_ && p_[1] == '$') {
      if (!body.empty()) { t.parts.push_back({0, body}); body.clear(); }
      p_++;
      int depth = 1;
      const char *start = p_;
      while (p_ < end_) {
        if (*p_ == '{') depth++;
        else if (*p_ == '}') { depth--; if (!depth) break; }
        p_++;
      }
      std::string src(start, p_ - start);
      if (p_ < end_) p_++;
      t.parts.push_back({2, src});
      continue;
    }
    if (c == '\n') line++;
    body += c; p_++;
  }
  if (!body.empty()) t.parts.push_back({0, body});
  return t;
}

std::string Lexer::readVarName() {
  std::string r;
  while (p_ < end_ && (isalnum((unsigned char)*p_) || *p_=='_' || (unsigned char)*p_ >= 0x80)) { r += *p_; p_++; }
  return r;
}

Token Lexer::peek(int ahead) {
  while ((int)buf.size() <= ahead) buf.push_back(scanOne());
  return buf[ahead];
}

Token Lexer::next() {
  if (!buf.empty()) { Token t = buf[0]; buf.erase(buf.begin()); return t; }
  return scanOne();
}
