            size_t e = raw.find('\n', pos);
            std::string ln2 = raw.substr(pos, e == std::string::npos ? std::string::npos : e - pos);
            size_t rem = 0;
            while (rem < ln2.size() && rem < indent && (ln2[rem]==' '||ln2[rem]=='\t')) rem++;
            if (!first) out2 += '\n';
            out2 += ln2.substr(rem);
            first = false;
            if (e == std::string::npos) break;
            pos = e + 1;
          }
          result = out2;
        }
        p_ = ln + 1 < end_ ? ln + 1 : ln;
        if (p_ < end_ && *p_ == '\n') { p_++; line++; }
        line++;
        if (nowdoc) {
          t.type = TK_STR; t.text = result;
          t.heredoc = true;
          return t;
        }
        t.type = TK_ENCAP;
        t.heredoc = true;
        t.text = result;
        return t;
      }
      if (ln >= end_) {
        setError("Unterminated string starting at line " + std::to_string(t.line));
        t.type = TK_EOF; return t;
      }
      p_ = ln + 1;
      line++;
    }
  }
  // operators
#define OP1(ch, ty) if (c == ch) { p_++; t.type = ty; t.text = std::string(1, ch); return t; }
  if (p_+1 < end_) {
    char c2 = p_[1];
    if (c=='+' && c2=='+') { p_+=2; t.type=TK_PLUSPLUS; t.text="++"; return t; }
    if (c=='-' && c2=='-') { p_+=2; t.type=TK_MINUSMINUS; t.text="--"; return t; }
    if (c=='<' && c2=='<') { if (p_+2<end_ && p_[2]=='=') { p_+=3; t.type=TK_SHLEQ; t.text="<<="; return t; } p_+=2; t.type=TK_SHL; t.text="<<"; return t; }
    if (c=='>' && c2=='>') { if (p_+2<end_ && p_[2]=='=') { p_+=3; t.type=TK_SHREQ; t.text=">>="; return t; } p_+=2; t.type=TK_SHR; t.text=">>"; return t; }
    if (c=='*' && c2=='*') { if (p_+2<end_ && p_[2]=='=') { p_+=3; t.type=TK_POWEQ; t.text="**="; return t; } p_+=2; t.type=TK_POW; t.text="**"; return t; }
    if (c=='=' && c2=='=') { if (p_+2<end_ && p_[2]=='=') { p_+=3; t.type=TK_SEQ; t.text="==="; return t; } p_+=2; t.type=TK_EQ; t.text="=="; return t; }
    if (c=='!' && c2=='=') { if (p_+2<end_ && p_[2]=='=') { p_+=3; t.type=TK_SNE; t.text="!=="; return t; } p_+=2; t.type=TK_NE; t.text="!="; return t; }
    if (c=='<' && c2=='=') { if (p_+2<end_ && p_[2]=='>') { p_+=3; t.type=TK_SSP; t.text="<=>"; return t; } p_+=2; t.type=TK_LE; t.text="<="; return t; }
    if (c=='>' && c2=='=') { p_+=2; t.type=TK_GE; t.text=">="; return t; }
    if (c=='&' && c2=='&') { p_+=2; t.type=TK_ANDAND; t.text="&&"; return t; }
    if (c=='|' && c2=='|') { p_+=2; t.type=TK_OROR; t.text="||"; return t; }
    if (c=='?' && c2=='?') { if (p_+2<end_ && p_[2]=='=') { p_+=3; t.type=TK_QUESTQUESTEQ; t.text="??="; return t; } p_+=2; t.type=TK_QUESTQUEST; t.text="??"; return t; }
    if (c=='?' && c2==':') { p_+=2; t.type=TK_QUESTCOLON; t.text="?:"; return t; }
    if (c=='+' && c2=='=') { p_+=2; t.type=TK_PLUSEQ; t.text="+="; return t; }
    if (c=='-' && c2=='=') { p_+=2; t.type=TK_MINUSEQ; t.text="-="; return t; }
    if (c=='*' && c2=='=') { p_+=2; t.type=TK_STAREQ; t.text="*="; return t; }
    if (c=='/' && c2=='=') { p_+=2; t.type=TK_SLASHEQ; t.text="/="; return t; }
    if (c=='%' && c2=='=') { p_+=2; t.type=TK_MODEQ; t.text="%="; return t; }
    if (c=='&' && c2=='=') { p_+=2; t.type=TK_ANDEQ; t.text="&="; return t; }
    if (c=='|' && c2=='=') { p_+=2; t.type=TK_OREQ; t.text="|="; return t; }
    if (c=='^' && c2=='=') { p_+=2; t.type=TK_XOREQ; t.text="^="; return t; }
    if (c=='.' && c2=='=') { p_+=2; t.type=TK_DOTEQ; t.text=".="; return t; }
    if (c=='-' && c2=='>') { p_+=2; t.type=TK_ARROW; t.text="->"; return t; }
    if (c==':' && c2==':') { p_+=2; t.type=TK_DCOLON; t.text="::"; return t; }
    if (c=='.' && c2=='.' && p_+2 < end_ && p_[2]=='.') { p_+=3; t.type=TK_SPREAD; t.text="..."; return t; }
    if (c=='#' && c2=='[') { p_+=2; t.type=TK_ATTR; t.text="#["; return t; }
    if (c=='\\') { p_++; t.type=TK_BACKSLASH; t.text="\\"; return t; }
  }
  p_++;
  t.type = (unsigned char)c;
  t.text = std::string(1, c);
  return t;
}

std::string Lexer::readName() {
  std::string r;
  while (p_ < end_) {
    unsigned char c = (unsigned char)*p_;
    if (isalnum(c) || c == '_' || c >= 0x80) { r += (char)c; p_++; }
    else break;
  }
  return r;
}

Token Lexer::readNumber() {
  Token t; t.line = line;
  const char *start = p_;
  bool isFloat = false;
  if (p_[0]=='0' && p_+1 < end_ && (p_[1]=='x'||p_[1]=='X')) {
    p_ += 2;
    std::string hex;
    while (p_ < end_ && (isxdigit((unsigned char)*p_) || *p_=='_')) { if (*p_ != '_') hex += *p_; p_++; }
    t.type = TK_INT; t.i = strtoll(hex.c_str(), nullptr, 16); t.text.assign(start, p_-start);
    return t;
  }
  if (p_[0]=='0' && p_+1 < end_ && (p_[1]=='b'||p_[1]=='B')) {
    p_ += 2;
    std::string bin;
    while (p_ < end_ && (*p_=='0'||*p_=='1'||*p_=='_')) { if (*p_ != '_') bin += *p_; p_++; }
    t.type = TK_INT; t.i = strtoll(bin.c_str(), nullptr, 2); t.text.assign(start, p_-start);
    return t;
  }
  if (p_[0]=='0' && p_+1 < end_ && (p_[1]=='o'||p_[1]=='O')) {
    p_ += 2;
    std::string oct;
    while (p_ < end_ && (*p_ >= '0' && *p_ <= '7' || *p_=='_')) { if (*p_ != '_') oct += *p_; p_++; }
    t.type = TK_INT; t.i = strtoll(oct.c_str(), nullptr, 8); t.text.assign(start, p_-start);
    return t;
  }
  // decimal
  if (p_[0]=='0' && p_+1 < end_ && isdigit((unsigned char)p_[1])) {
    // octal or invalid
    p_++;
    bool invalid = false;
    while (p_ < end_ && isdigit((unsigned char)*p_)) { if (*p_ >= '8') invalid = true; p_++; }
    if (invalid) { setError("Invalid numeric literal"); t.type = TK_EOF; return t; }
    std::string digits(start+1, p_ - start - 1);
    t.type = TK_INT; t.i = strtoll(digits.c_str(), nullptr, 8);
    t.text.assign(start, p_ - start);
    return t;
  }
  while (p_ < end_ && (isdigit((unsigned char)*p_) || *p_=='_')) p_++;
  if (p_ < end_ && *p_=='.' && p_+1 < end_ && isdigit((unsigned char)p_[1])) {
    isFloat = true; p_++;
    while (p_ < end_ && (isdigit((unsigned char)*p_) || *p_=='_')) p_++;
  } else if (p_ < end_ && *p_=='.' && (p_+1 >= end_ || !isalpha((unsigned char)p_[1]))) {
    // "1." is float
    isFloat = true; p_++;
  }
  if (p_ < end_ && (*p_=='e'||*p_=='E')) {
    const char *save = p_;
    p_++;
    if (p_ < end_ && (*p_=='+'||*p_=='-')) p_++;
    if (p_ < end_ && isdigit((unsigned char)*p_)) {
      isFloat = true;
      while (p_ < end_ && isdigit((unsigned char)*p_)) p_++;
    } else p_ = save;
  }
  std::string s(start, p_ - start);
  std::string clean;
  for (char ch : s) if (ch != '_') clean += ch;
  if (isFloat) { t.type = TK_FLOAT; t.d = strtod(clean.c_str(), nullptr); }
  else {
    t.type = TK_INT;
    t.i = strtoll(clean.c_str(), nullptr, 10);
  }
  t.text = clean;
  return t;
}

Token Lexer::readSingle() {
  Token t; t.line = line;
  p_++;
  std::string body;
  while (p_ < end_) {
    if (*p_ == '\\' && p_+1 < end_ && (p_[1]=='\'' || p_[1]=='\\')) { body += p_[1]; p_ += 2; continue; }
    if (*p_ == '\\') { body += '\\'; p_++; continue; }
    if (*p_ == '\'') { p_++; break; }
    if (*p_ == '\n') line++;
    body += *p_++;
  }
  t.type = TK_STR; t.text = body;
  return t;
}

Token Lexer::readDouble(bool heredoc) {
  Token t; t.line = line;
  p_++; // opening quote
  std::string body;
  t.type = TK_ENCAP;
  while (p_ < end_) {
    char c = *p_;
    if (c == '"') { p_++; break; }
    if (c == '\\') {
      // take escape sequences one at a time, but keep $ and { handling
      body += '\\';
      p_++;
      if (p_ < end_) { body += *p_; p_++; }
      continue;
    }
    if (c == '$' && p_+1 < end_ && (isalpha((unsigned char)p_[1]) || p_[1]=='_' || (unsigned char)p_[1] >= 0x80)) {
      if (!body.empty()) { t.parts.push_back({0, body}); body.clear(); }
      p_++;
      std::string name = readName();
      t.parts.push_back({1, name});
      // simple access: [key] or ->prop
      if (p_ < end_ && *p_ == '[') {
        p_++;
        std::string key;
        if (p_ < end_ && (*p_=='\'' || *p_=='"')) {
          char q = *p_++; 
          while (p_ < end_ && *p_ != q) { if (*p_=='\\' && p_+1<end_ && p_[1]==q) { key += q; p_+=2; } else key += *p_++; }
          if (p_ < end_) p_++;
          key = std::string(1,q) + key + std::string(1,q);
          t.parts.push_back({5, key});
        } else if (p_ < end_ && *p_ == '$') {
          p_++;
          t.parts.push_back({7, readVarName()});
        } else {
          while (p_ < end_ && isalnum((unsigned char)*p_)) key += *p_++;
          t.parts.push_back({6, key});
        }
        if (p_ < end_ && *p_ == ']') p_++;
      } else if (p_ < end_ && p_[0]=='-' && p_+1 < end_ && p_[1]=='>') {
        p_ += 2;
        t.parts.push_back({8, readName()});
      }
      continue;
    }
    if (c == '$' && p_+1 < end_ && p_[1] == '{') {
      if (!body.empty()) { t.parts.push_back({0, body}); body.clear(); }
      p_ += 2;
      std::string name;
      while (p_ < end_ && *p_ != '}') name += *p_++;
      if (p_ < end_) p_++;
      t.parts.push_back({3, name});
      continue;
    }
    if (c == '{' && p_+1 < end_ && p_[1] == '$') {
      if (!body.empty()) { t.parts.push_back({0, body}); body.clear(); }
      // find matching }
      p_++;
      int depth = 1;
      const char *start = p_;
      while (p_ < end_) {
        if (*p_ == '{') depth++;
        else if (*p_ == '}') { depth--; if (!depth) break; }
        else if (*p_ == '"' || *p_ == '\'') {
          char q = *p_++;
          while (p_ < end_ && *p_ != q) { if (*p_=='\\' && p_+1<end_) p_++; p_++; }
        }
        p_++;
      }
      std::string src(start, p_ - start);
      if (p_ < end_) p_++;
      t.parts.push_back({2, src});
      continue;
    }
    if (c == '\n') line++;
    body += c; p_++;
  }
  if (!body.empty()) t.parts.push_back({0, body});
  return t;
}

Token Lexer::readBacktick() {
  Token t; t.line = line;
  t.type = TK_ENCAP;
  t.text = "`";
  p_++;
  std::string body;
  while (p_ < end_) {
    char c = *p_;
    if (c == '`') { p_++; break; }
    if (c == '\\') { body += '\\'; p_++; if (p_ < end_) { body += *p_; p_++; } continue; }
    if (c == '$' && p_+1 < end_ && (isalpha((unsigned char)p_[1]) || p_[1]=='_' || (unsigned char)p_[1] >= 0x80)) {
      if (!body.empty()) { t.parts.push_back({0, body}); body.clear(); }
      p_++;
      std::string name = readName();
      t.parts.push_back({1, name});
      if (p_ < end_ && *p_ == '[') {
        p_++;
        std::string key;
        while (p_ < end_ && isalnum((unsigned char)*p_)) key += *p_++;
        if (p_ < end_ && *p_ == ']') p_++;
        t.parts.push_back({6, key});
      }
      continue;
    }
    if (c == '{' && p_+1 < end_ && p_[1] == '$') {
      if (!body.empty()) { t.parts.push_back({0, body}); body.clear(); }
      p_++;
      int depth = 1;
      const char *start = p_;
      while (p_ < end_) {
        if (*p_ == '{') depth++;
        else if (*p_ == '}') { depth--; if (!depth) break; }
        p_++;
      }
      std::string src(start, p_ - start);
      if (p_ < end_) p_++;
      t.parts.push_back({2, src});
      continue;
    }
    if (c == '\n') line++;
    body += c; p_++;
  }
  if (!body.empty()) t.parts.push_back({0, body});
  return t;
}

std::string Lexer::readVarName() {
  std::string r;
  while (p_ < end_ && (isalnum((unsigned char)*p_) || *p_=='_' || (unsigned char)*p_ >= 0x80)) { r += *p_; p_++; }
  return r;
}

Token Lexer::peek(int ahead) {
  while ((int)buf.size() <= ahead) buf.push_back(scanOne());
  return buf[ahead];
}

Token Lexer::next() {
  if (!buf.empty()) { Token t = buf[0]; buf.erase(buf.begin()); return t; }
  return scanOne();
}
