#include "parse.h"
#include <cctype>
#include <cstdlib>
#include <cstring>
#include <cstdio>

Program *g_prog = nullptr;
Program::~Program() {}

void Parser::advance() {
  if (!pending.empty()) { tk = pending.back(); pending.pop_back(); return; }
  tk = lex.next();
  if (lex.fail) setError(lex.error);
}
void Parser::setError(const std::string &m) {
