std::string Parser::tokDesc() {
  switch (tk.type) {
    case TK_EOF: return "end of file";
    case TK_NAME: return "identifier \"" + tk.text + "\"";
    case TK_VAR: return "variable";
    case TK_INT: return "integer";
    case TK_FLOAT: return "floating-point";
    case TK_STR: return "string";
    case TK_ENCAP: return tk.heredoc ? "heredoc" : "string";
    default:
      if (tk.type < 256) return std::string("\"") + (char)tk.type + "\"";
      return "\"" + tk.text + "\"";
  }
}

Node *Parser::parseProgram() {
  Node *prog = parseStmts(false);
  if (!fail && tk.type != TK_EOF) setError(std::string("syntax error, unexpected ") + tokDesc());
  return prog;
}

Node *Parser::parseStmts(bool untilBrace) {
  std::vector<Node*> v;
  while (!fail && tk.type != TK_EOF) {
    if (untilBrace && tk.type == '}') break;
    if (isName("case") || isName("default")) break;
    Node *s = parseStmt();
    if (s) v.push_back(s);
  }
  Node *b = newNode(N_STMTLIST);
  b->kids = std::move(v);
  return b;
}

Node *Parser::parseBlock() {
  if (tk.type == '{') {
    advance();
    Node *b = parseStmts(true);
    if (tk.type == '}') advance();
    else setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting \"}\"");
    return b;
  }
  return parseStmt();
}

// ---------------- statements ----------------
Node *Parser::parseStmt() {
  int line = tk.line;
  if (tk.type == ';') { advance(); Node *n = newNode(N_NOP); return n; }
  if (tk.type == '{') return parseBlock();
  if (tk.type == TK_NAME) {
    const std::string &k = lc(tk.text);
    if (k == "if") return parseIf();
    if (k == "while") { advance(); expect("("); Node *c = parseExpr(); expect(")"); Node *b = parseBlock();
      Node *n = newNode(N_WHILE); n->kids.push_back(c); n->kids.push_back(b); n->line = line; return n; }
    if (k == "do") {
      advance(); Node *b = parseBlock(); expectName("while"); expect("("); Node *c = parseExpr(); expect(")"); accept(";");
      Node *n = newNode(N_DOWHILE); n->kids.push_back(b); n->kids.push_back(c); n->line = line; return n;
    }
    if (k == "for") return parseFor();
    if (k == "foreach") return parseForeach();
    if (k == "switch") return parseSwitch();
    if (k == "try") return parseTry();
    if (k == "break" || k == "continue") {
      advance();
      int lvl = 1;
      if (tk.type == TK_INT) { lvl = (int)tk.i; advance(); }
      else if (tk.type == '(') {
        // break (n)
      }
      if (!accept(";")) setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting \";\"");
      Node *n = newNode(k == "break" ? N_BREAK : N_CONTINUE); n->i = lvl; n->line = line; return n;
    }
    if (k == "return") {
      advance();
      Node *e = nullptr;
      if (tk.type != ';' && tk.type != '}') e = parseExpr();
      if (!accept(";") && tk.type != '}' && tk.type != TK_EOF) setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting \";\"");
      Node *n = newNode(N_RETURN); if (e) n->kids.push_back(e); n->line = line; return n;
    }
    if (k == "throw") {
      advance(); Node *e = parseExpr();
      if (!accept(";")) setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting \";\"");
      Node *n = newNode(N_THROW); n->kids.push_back(e); n->line = line; return n;
    }
    if (k == "echo") return parseEcho();
    if (k == "global") return parseGlobal();
    if (k == "static") {
      // static closure or static var decl
      if (lex.peek(0).type == TK_VAR) return parseStaticDecl();
      // static:: or static function closure: fall through to expression
    }
    if (k == "const") return parseConstDecl();
    if (k == "function") { return parseFuncDecl(false); }
    if (k == "class" || k == "interface" || k == "trait" || k == "enum") {
      // might be anonymous class expression: not valid as statement
      return parseClassDecl(k);
    }
    if (k == "goto") {
      advance();
      std::string lbl = tk.text; advance();
      accept(";");
      Node *n = newNode(N_GOTO); n->name = lbl; n->line = line; return n;
    }
    if (k == "unset") {
      advance(); expect("(");
      Node *n = newNode(N_UNSET); n->line = line;
      for (;;) {
        Node *t = parseExpr();
        n->kids.push_back(t);
        if (accept(",")) continue;
        break;
      }
      expect(")"); accept(";");
      return n;
    }
    if (k == "declare") return parseDeclare();
    if (k == "namespace") return parseNamespace();
    if (k == "use") return parseUse();
    if (k == "print") {
      advance();
      Node *e = parseExpr();
      if (!accept(";")) setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting \";\"");
      Node *n = newNode(N_PRINT); n->kids.push_back(e); n->line = line; return n;
    }
    if (k == "include" || k == "include_once" || k == "require" || k == "require_once") {
      int op = k == "include" ? N_INCLUDE : k == "include_once" ? N_INCLUDE_ONCE : k == "require" ? N_REQUIRE : N_REQUIRE_ONCE;
      advance();
      Node *e = parseExpr();
      if (!accept(";")) setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting \";\"");
      Node *n = newNode(op); n->kids.push_back(e); n->line = line; return n;
    }
    if (k == "abstract" || k == "final" || k == "public" || k == "private" || k == "protected" || k == "readonly") {
      setError("syntax error, unexpected '" + tk.text + "'");
    }
  }
  // attribute(s) then declaration
  // expression statement
  Node *e = parseExpr();
  if (!accept(";") && tk.type != '}' && tk.type != TK_EOF) setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting \";\"");
  Node *n = newNode(N_EXPR_STMT); n->kids.push_back(e); n->line = line; return n;
}

Node *Parser::parseEcho() {
  Node *n = newNode(N_ECHO);
  n->line = tk.line;
  advance();
  for (;;) {
    Node *e = parseExpr();
    n->kids.push_back(e);
    if (accept(",")) continue;
    break;
  }
  if (!accept(";") && tk.type != '}' && tk.type != TK_EOF) setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting \";\"");
  return n;
}

Node *Parser::parseGlobal() {
  advance();
  Node *n = newNode(N_GLOBAL); n->line = tk.line;
  for (;;) {
    if (tk.type != TK_VAR) setError("syntax error, unexpected " + tokDesc());
    Node *v = newNode(N_VAR); v->name = tk.text; v->line = tk.line; advance();
    n->kids.push_back(v);
    if (accept(",")) continue;
    break;
  }
  if (!accept(";")) setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting \";\"");
  return n;
}

Node *Parser::parseStaticDecl() {
  advance();
  Node *n = newNode(N_STATICVARS); n->line = tk.line;
  for (;;) {
    if (tk.type != TK_VAR) setError("syntax error, unexpected " + tokDesc());
    Node *v = newNode(N_VAR); v->name = tk.text; v->line = tk.line; advance();
    Node *item = newNode(N_KEYVAL);
    item->kids.push_back(v);
    if (accept("=")) item->kids.push_back(parseExpr());
    else item->kids.push_back(nullptr);
    n->kids.push_back(item);
    if (accept(",")) continue;
    break;
  }
  if (!accept(";")) setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting \";\"");
  return n;
}

Node *Parser::parseConstDecl() {
  advance();
  Node *n = newNode(N_CONSTDEF); n->line = tk.line;
  for (;;) {
    if (tk.type != TK_NAME) setError("syntax error, unexpected " + tokDesc());
    std::string cname = tk.text; advance();
    expect("=");
    Node *e = parseExpr();
    Node *item = newNode(N_KEYVAL);
    Node *nm = newNode(N_NAME); nm->name = cname; nm->line = line();
    item->kids.push_back(nm);
    item->kids.push_back(e);
    n->kids.push_back(item);
    if (accept(",")) continue;
    break;
  }
  if (!accept(";")) setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting \";\"");
  return n;
}

Node *Parser::parseDeclare() {
  advance(); expect("(");
  Node *n = newNode(N_DECLARE);
  for (;;) {
    std::string k = tk.text; advance();
    expect("=");
    Node *v = parseExpr();
    n->name += k;
    n->kids.push_back(v);
    if (accept(",")) continue;
    break;
  }
  expect(")"); accept(";");
  return n;
}

Node *Parser::parseNamespace() {
  advance();
  Node *n = newNode(N_NOP);
  if (tk.type == TK_NAME || tk.type == TK_BACKSLASH) {
    // qualified name
    while (tk.type == TK_NAME || tk.type == TK_BACKSLASH) advance();
  }
  if (tk.type == '{') { advance(); Node *b = parseStmts(true); expect("}"); n->kids.push_back(b); }
  else accept(";");
  return n;
}

Node *Parser::parseUse() {
  advance();
  bool sawFunction = false, sawConst = false;
  if (isName("function")) { sawFunction = true; advance(); }
  else if (isName("const")) { sawConst = true; advance(); }
  // consume the whole use statement
  while (tk.type != ';' && tk.type != '{' && tk.type != TK_EOF) advance();
  if (tk.type == '{') { advance(); while (tk.type != '}' && tk.type != TK_EOF) advance(); }
  accept(";");
  return newNode(N_NOP);
}
EOF
