Node *Parser::parseIf() {
  int line = tk.line;
  advance(); expect("(");
  Node *c = parseExpr(); expect(")");
  Node *b = parseBlock();
  Node *n = newNode(N_IF); n->line = line;
  n->kids.push_back(c); n->kids.push_back(b);
