  Node *b = parseBlock();
  Node *n = newNode(N_IF); n->line = line;
  n->kids.push_back(c); n->kids.push_back(b);
  // else if / else
  while (isName("elseif") || isName("else")) {
    if (isName("elseif")) {
      advance(); expect("(");
      Node *c2 = parseExpr(); expect(")");
      Node *b2 = parseBlock();
      Node *e = newNode(N_IF); e->line = tk.line;
      e->kids.push_back(c2); e->kids.push_back(b2);
      n->kids.push_back(e);
      // continue loop only for further elseifs handled by recursion; break
      if (isName("else")) {
        advance();
        if (isName("if")) { Node *ei = parseIf(); n->kids.push_back(ei); }
        else n->kids.push_back(parseBlock());
      }
      break;
    } else {
      advance();
      if (isName("if")) { Node *ei = parseIf(); n->kids.push_back(ei); }
      else n->kids.push_back(parseBlock());
      break;
    }
  }
  return n;
}

Node *Parser::parseFor() {
  int line = tk.line;
  advance(); expect("(");
  std::vector<Node*> init, cond, incr;
  for (;;) {
    if (tk.type == ';' || tk.type == ')') break;
    init.push_back(parseExpr());
    if (!accept(",")) break;
  }
  expect(";");
  for (;;) {
    if (tk.type == ';') break;
    cond.push_back(parseExpr());
    if (!accept(",")) break;
  }
  expect(";");
  for (;;) {
    if (tk.type == ')') break;
    incr.push_back(parseExpr());
    if (!accept(",")) break;
  }
  expect(")");
  Node *b = parseBlock();
  Node *n = newNode(N_FOR); n->line = line;
  Node *in = newNode(N_STMTLIST); in->kids = std::move(init);
  Node *co = newNode(N_STMTLIST); co->kids = std::move(cond);
  Node *up = newNode(N_STMTLIST); up->kids = std::move(incr);
  n->kids.push_back(in); n->kids.push_back(co); n->kids.push_back(up); n->kids.push_back(b);
  return n;
}

Node *Parser::parseForeach() {
  int line = tk.line;
  advance(); expect("(");
  Node *arr = parseExpr();
  bool isRefArr = false, isRefVal = false, isRefKey = false;
  bool byValKey = false;
  if (acceptName("as")) {
    // parse target: $k => $v | $v | & $k => $v | & $v | $k => & $v
    if (tk.type == '&' && lex.peek(0).type == TK_VAR) { isRefVal = true; advance(); }
    else if (tk.type == '&' && lex.peek(0).type == '(') { isRefVal = true; advance(); }
    Node *first = parseForeachTarget();
    if (acceptName("as")) { /* nested list */ }
    if (acceptName("=>")) {
      isRefKey = false;
      // first is key
      if (tk.type == '&') { isRefVal = true; advance(); }
      Node *second = parseForeachTarget();
      Node *kv = newNode(N_KEYVAL);
      kv->kids.push_back(first);
      kv->kids.push_back(second);
      n = nullptr;
      Node *n2 = newNode(N_FOREACH); n2->line = line;
      n2->kids.push_back(arr);
      n2->kids.push_back(kv);
      n2->flags |= (isRefArr?1:0) | (isRefVal?2:0) | (isRefKey?4:0);
      expect(")");
      Node *b = parseBlock();
      n2->kids.push_back(b);
      return n2;
    }
    Node *n2 = newNode(N_FOREACH); n2->line = line;
    n2->kids.push_back(arr);
    n2->kids.push_back(first);
    n2->flags |= (isRefArr?1:0) | (isRefVal?2:0) | (isRefKey?4:0);
    expect(")");
    Node *b = parseBlock();
    n2->kids.push_back(b);
    return n2;
  }
  setError("syntax error, unexpected " + tokDesc() + ", expecting \"as\"");
  return newNode(N_NOP);
}

Node *Parser::parseForeachTarget() {
  // $var | & $var | list(...) | [ ... ]
  if (tk.type == '&') { advance(); }
  if (tk.type == TK_VAR) {
    Node *v = newNode(N_VAR); v->name = tk.text; v->line = tk.line; advance();
    return v;
  }
  if (tk.type == '(' || (tk.type == TK_NAME && lc(tk.text) == "list")) {
    return parseListDestructure();
  }
  if (tk.type == '[') return parseListDestructure();
  setError("syntax error, unexpected " + tokDesc());
  return newNode(N_NOP);
}

Node *Parser::parseListDestructure() {
  bool paren = false;
  if (tk.type == '(') { paren = true; advance(); }
  else if (isName("list")) { advance(); expect("("); paren = true; }
  else if (tk.type == '[') { advance(); }
  Node *n = newNode(N_LIST_EXPR);
  for (;;) {
    if (tk.type == ')' || tk.type == ']') break;
    if (tk.type == ',') { Node *x = newNode(N_NOP); n->kids.push_back(x); advance(); continue; }
    if (tk.type == TK_SPREAD) { advance(); }
    Node *t;
    if (tk.type == TK_NAME && lex.peek(0).type == TK_DCOLON) {
      // class constant destructure
      t = parseNameRef();
    } else if (tk.type == TK_VAR) {
      t = newNode(N_VAR); t->name = tk.text; t->line = tk.line; advance();
      if (accept(TK_ARROW_TEXT)) {
        Node *idx = newNode(N_KEYVAL);
        Node *k = parseExpr();
        idx->kids.push_back(k);
        idx->kids.push_back(parseForeachTarget());
        t = idx;
      }
    } else {
      t = parseExpr();
    }
    n->kids.push_back(t);
    if (accept(",")) continue;
    break;
  }
  if (paren) expect(")"); else expect("]");
  return n;
}
