// ---------------- class declarations ----------------
Node *Parser::parseClassDecl(const std::string &kind) {
  int line = tk.line;
  std::string k = kind;
  bool isAbstract = false, isFinal = false;
  // collect preceding modifiers already consumed by caller? caller passes kind
  if (k == "class") {
    // check for preceding modifiers
  }
  Node *n = newNode(N_CLASSDECL);
  n->line = line;
  n->name = k;
  advance();
  if (k == "enum") {
    expect("(") ;
  }
  if (tk.type != TK_NAME) { setError("syntax error, unexpected " + tokDesc() + ", expecting identifier"); return n; }
  std::string cname = tk.text;
  n->text = cname;
  advance();
  // extends / implements / : type
  Node *ext = nullptr;
  std::vector<Node*> impls;
  if (k == "enum") {
    if (accept(":")) {
      std::string ty;
      bool nl;
      parseType(ty, nl);
      n->i = ty == "string" ? 2 : ty == "int" ? 1 : 0;
    }
    if (acceptName("implements")) {
      for (;;) {
        impls.push_back(parseNameRef());
        if (accept(",")) continue;
        break;
      }
    }
  } else {
    if (acceptName("extends")) ext = parseNameRef();
    if (acceptName("implements")) {
      for (;;) {
        impls.push_back(parseNameRef());
        if (accept(",")) continue;
        break;
      }
    }
  }
  expect("{");
  std::vector<Node*> body;
  while (tk.type != '}' && !fail) {
    if (tk.type == TK_ATTR) {
      // attributes
      while (tk.type == TK_ATTR) {
        advance();
        // skip attribute contents
        int depth = 1;
        while (depth > 0 && tk.type != TK_EOF) {
          if (tk.type == '[') depth++;
          else if (tk.type == ']') depth--;
          advance();
        }
      }
      continue;
    }
    if (isName("use")) {
      advance();
      Node *u = newNode(N_USE_TRAITS);
      for (;;) {
        u->kids.push_back(parseNameRef());
        if (accept(",")) continue;
        break;
      }
      if (tk.type == '{') {
        advance();
        while (tk.type != '}' && !fail) {
          // trait adaptations: A::m as alias; A::m insteadof B; A::m insteadof B;
          if (tk.type == TK_NAME) {
            Node *ad = newNode(N_TRAITALIAS);
            ad->name = tk.text;
            advance();
            if (accept(TK_DCOLON)) {
              ad->kids.push_back(newNode(N_NAME)); ad->kids[0]->name = tk.text; advance();
            }
            if (acceptName("as")) {
              // visibility modifiers / alias
              while (tk.type == TK_NAME || tk.type == ';') {
                if (tk.type == ';') break;
                if (isName("public") || isName("protected") || isName("private")) { ad->text += (ad->text.empty()?"":" ") + tk.text; advance(); continue; }
                ad->text += (ad->text.empty()?"":" ") + tk.text; advance();
              }
              ad->flags = 1;
            } else if (acceptName("insteadof")) {
              ad->flags = 2;
              for (;;) {
                ad->kids.push_back(parseNameRef());
                if (accept(",")) continue;
                break;
              }
            }
            accept(";");
            body.push_back(ad);
          } else advance();
        }
        expect("}");
      } else accept(";");
      body.push_back(u);
      continue;
    }
    if (isName("case")) {
      // enum case
      advance();
      if (tk.type != TK_NAME) { setError("syntax error, unexpected " + tokDesc()); break; }
      Node *c = newNode(N_ENUMCASE);
      c->name = tk.text; c->line = tk.line; advance();
      if (accept("=")) {
        Node *e = newNode(N_ENUMCASE_VAL);
        e->kids.push_back(parseExpr());
        c->kids.push_back(e);
      }
      accept(";");
      body.push_back(c);
      continue;
    }
    if (isName("const")) {
      advance();
      Vis vis = VIS_PUBLIC;
      if (isName("public")) { advance(); }
      else if (isName("protected")) { vis = VIS_PROTECTED; advance(); }
      else if (isName("private")) { vis = VIS_PRIVATE; advance(); }
      Node *cn = newNode(N_CONSTDEF);
      cn->flags = 2; // class const
      for (;;) {
        if (tk.type != TK_NAME) { setError("syntax error, unexpected " + tokDesc()); break; }
        std::string cname2 = tk.text; advance();
        expect("=");
        Node *e = parseExpr();
        Node *item = newNode(N_KEYVAL);
        Node *nm = newNode(N_NAME); nm->name = cname2; nm->line = tk.line; nm->i = (int)vis;
        item->kids.push_back(nm);
        item->kids.push_back(e);
        cn->kids.push_back(item);
        if (accept(",")) continue;
        break;
      }
      accept(";");
      body.push_back(cn);
      continue;
    }
    if (isName("abstract") || isName("final") || isName("public") || isName("private") ||
        isName("protected") || isName("static") || isName("function") || isName("readonly") ||
        isName("var") || isName("fn")) {
      body.push_back(parseMethodDecl(line));
      continue;
    }
    setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting function");
    break;
  }
  expect("}");
  Node *b = newNode(N_CLASSBODY);
  b->kids = std::move(body);
  n->kids.push_back(ext);
  Node *il = newNode(N_STMTLIST); il->kids = std::move(impls);
  n->kids.push_back(il);
  n->kids.push_back(b);
  return n;
}

Node *Parser::parseMethodDecl(int line) {
  Vis vis = VIS_PUBLIC;
  bool isStatic = false, isAbstract = false, isFinal = false, readonly = false;
  // modifiers
  for (;;) {
    if (isName("public")) { vis = VIS_PUBLIC; advance(); continue; }
    if (isName("private")) { vis = VIS_PRIVATE; advance(); continue; }
    if (isName("protected")) { vis = VIS_PROTECTED; advance(); continue; }
    if (isName("static")) { isStatic = true; advance(); continue; }
    if (isName("abstract")) { isAbstract = true; advance(); continue; }
    if (isName("final")) { isFinal = true; advance(); continue; }
    if (isName("readonly")) { readonly = true; advance(); continue; }
    if (isName("var")) { advance(); continue; }
    if (tk.type == TK_ATTR) {
      advance();
      int depth = 1;
      while (depth > 0 && tk.type != TK_EOF) {
        if (tk.type == '[') depth++;
        else if (tk.type == ']') depth--;
        advance();
      }
      continue;
    }
    break;
  }
  if (isName("function")) {
    Node *m = parseFuncDecl(false);
    m->i = (int)vis | (isStatic ? 4 : 0) | (isAbstract ? 8 : 0) | (isFinal ? 16 : 0) | (readonly ? 32 : 0);
    return m;
  }
  if (isName("fn")) {
    Node *m = parseFuncDecl(false);
    m->i = (int)vis | (isStatic ? 4 : 0) | (isAbstract ? 8 : 0) | (isFinal ? 16 : 0) | (readonly ? 32 : 0);
    return m;
  }
  // property declaration
  Node *n = newNode(N_PROPDEF);
  n->line = line;
  n->i = (int)vis | (isStatic ? 4 : 0) | (readonly ? 32 : 0);
  if (isName("readonly")) { /* handled */ }
  // optional type
  std::string ty; bool nullable = false;
  if (tk.type == '?' ) { nullable = true; advance(); }
  parseType(ty, nullable);
  n->text = ty;
  n->flags2 = nullable ? 1 : 0;
  for (;;) {
    if (tk.type != TK_VAR) { setError("syntax error, unexpected " + tokDesc()); break; }
    Node *item = newNode(N_KEYVAL);
    Node *v = newNode(N_VAR); v->name = tk.text; v->line = tk.line; advance();
    item->kids.push_back(v);
    if (accept("=")) item->kids.push_back(parseExpr());
    item->kids.push_back(nullptr);
    n->kids.push_back(item);
    if (accept(",")) continue;
    break;
  }
  accept(";");
  return n;
}

Node *Parser::parseType(std::string &out, bool &nullable) {
  std::string r;
  if (tk.type == '\\') { advance(); }
  if (tk.type != TK_NAME && tk.type != TK_VAR) { return nullptr; }
  r = tk.text;
  advance();
  // qualified names
  while (tk.type == TK_BACKSLASH) {
    advance();
    r += "\\" + tk.text;
    advance();
  }
  // intersection/union types
  while (tk.type == '|' || (tk.type == '&' && lex.peek(0).type == TK_NAME)) {
    char sep = tk.type == '|' ? '|' : '&';
    advance();
    if (tk.type == '?') { nullable = true; advance(); }
    if (tk.type == '(') {
      advance();
      std::string sub; bool nl2 = false;
      parseType(sub, nl2);
      expect(")");
      r += std::string(1, sep) + "(" + sub + ")";
      continue;
    }
    if (tk.type != TK_NAME) break;
    r += std::string(1, sep) + tk.text;
    advance();
    while (tk.type == TK_BACKSLASH) { advance(); r += "\\" + tk.text; advance(); }
  }
  out = r;
  return nullptr;
}

Node *Parser::parseParams(std::vector<Param> &out, bool allowAttr) {
  bool first = true;
  for (;;) {
    Param p;
    if (tk.type == TK_ATTR) {
      advance();
      int depth = 1;
