Node *Parser::parseMethodDecl(int line) {
  Vis vis = VIS_PUBLIC;
  bool isStatic = false, isAbstract = false, isFinal = false, readonly = false;
  // modifiers
  for (;;) {
    if (isName("public")) { vis = VIS_PUBLIC; advance(); continue; }
    if (isName("private")) { vis = VIS_PRIVATE; advance(); continue; }
    if (isName("protected")) { vis = VIS_PROTECTED; advance(); continue; }
    if (isName("static")) { isStatic = true; advance(); continue; }
    if (isName("abstract")) { isAbstract = true; advance(); continue; }
    if (isName("final")) { isFinal = true; advance(); continue; }
    if (isName("readonly")) { readonly = true; advance(); continue; }
    if (isName("var")) { advance(); continue; }
    if (tk.type == TK_ATTR) {
      advance();
      int depth = 1;
      while (depth > 0 && tk.type != TK_EOF) {
        if (tk.type == '[') depth++;
        else if (tk.type == ']') depth--;
        advance();
      }
      continue;
    }
    break;
  }
  if (isName("function")) {
    Node *m = parseFuncDecl(false);
    m->i = (int)vis | (isStatic ? 4 : 0) | (isAbstract ? 8 : 0) | (isFinal ? 16 : 0) | (readonly ? 32 : 0);
    return m;
  }
  if (isName("fn")) {
    Node *m = parseFuncDecl(false);
    m->i = (int)vis | (isStatic ? 4 : 0) | (isAbstract ? 8 : 0) | (isFinal ? 16 : 0) | (readonly ? 32 : 0);
    return m;
  }
  // property declaration
  Node *n = newNode(N_PROPDEF);
  n->line = line;
  n->i = (int)vis | (isStatic ? 4 : 0) | (readonly ? 32 : 0);
  if (isName("readonly")) { /* handled */ }
  // optional type
  std::string ty; bool nullable = false;
  if (tk.type == '?' ) { nullable = true; advance(); }
  parseType(ty, nullable);
  n->text = ty;
  n->flags2 = nullable ? 1 : 0;
  for (;;) {
    if (tk.type != TK_VAR) { setError("syntax error, unexpected " + tokDesc()); break; }
    Node *item = newNode(N_KEYVAL);
    Node *v = newNode(N_VAR); v->name = tk.text; v->line = tk.line; advance();
    item->kids.push_back(v);
    if (accept("=")) item->kids.push_back(parseExpr());
    item->kids.push_back(nullptr);
    n->kids.push_back(item);
    if (accept(",")) continue;
    break;
  }
  accept(";");
  return n;
}

Node *Parser::parseType(std::string &out, bool &nullable) {
  std::string r;
  if (tk.type == '\\') { advance(); }
  if (tk.type != TK_NAME && tk.type != TK_VAR) { return nullptr; }
  r = tk.text;
  advance();
  // qualified names
  while (tk.type == TK_BACKSLASH) {
    advance();
    r += "\\" + tk.text;
    advance();
  }
  // intersection/union types
  while (tk.type == '|' || (tk.type == '&' && lex.peek(0).type == TK_NAME)) {
    char sep = tk.type == '|' ? '|' : '&';
    advance();
    if (tk.type == '?') { nullable = true; advance(); }
    if (tk.type == '(') {
      advance();
      std::string sub; bool nl2 = false;
      parseType(sub, nl2);
      expect(")");
      r += std::string(1, sep) + "(" + sub + ")";
      continue;
    }
    if (tk.type != TK_NAME) break;
    r += std::string(1, sep) + tk.text;
    advance();
    while (tk.type == TK_BACKSLASH) { advance(); r += "\\" + tk.text; advance(); }
  }
  out = r;
  return nullptr;
}

Node *Parser::parseParams(std::vector<Param> &out, bool allowAttr) {
  bool first = true;
  for (;;) {
    Param p;
    if (tk.type == TK_ATTR) {
      advance();
      int depth = 1;
      while (depth > 0 && tk.type != TK_EOF) {
        if (tk.type == '[') depth++;
        else if (tk.type == ']') depth--;
        advance();
      }
    }
    if (tk.type == TK_SPREAD) { p.variadic = true; advance(); }
    if (tk.type == '&') { p.byRef = true; advance(); }
    if (tk.type == TK_NAME && (lc(tk.text)=="readonly")) { p.readonly = true; advance(); }
    // optional type
    std::string ty; bool nl = false;
    Node *save = nullptr;
    if (tk.type != TK_VAR) {
      if (tk.type == '?' ) { nl = true; advance(); }
      parseType(ty, nl);
    }
    p.typeName = ty;
    p.typeNullable = nl;
    if (tk.type != TK_VAR) {
      if (first && tk.type == ')') break;
      setError("syntax error, unexpected " + tokDesc() + ", expecting variable");
      return nullptr;
    }
    p.name = tk.text;
    advance();
    if (accept("=")) p.def = parseExpr();
    out.push_back(p);
    first = false;
    if (accept(",")) continue;
    break;
  }
  return nullptr;
}

// function declaration: function name(args) [use (...)] [: type] { body }
Node *Parser::parseFuncDecl(bool isClosure) {
  int line = tk.line;
  bool byRef = false;
  bool isStaticFn = false;
  bool isArrow = false;
  if (isName("static")) { isStaticFn = true; advance(); }
  if (isName("function")) advance();
  else if (isName("fn")) { isArrow = true; advance(); }
  if (tk.type == '&') { byRef = true; advance(); }
  std::string fname;
  if (tk.type == TK_NAME) { fname = tk.text; advance(); }
  else if (!isClosure && !isArrow) { setError("syntax error, unexpected " + tokDesc() + ", expecting \"(\""); }
  Node *n = newNode(isArrow ? N_ARROW : N_FUNC);
  n->line = line;
  n->name = fname;
  n->flags |= byRef ? 1 : 0;
  n->flags |= isStaticFn ? 2 : 0;
  expect("(");
  std::vector<Param> params;
  parseParams(params, true);
  expect(")");
  if (acceptName("use")) {
    expect("(");
    std::vector<std::pair<Ref,bool>> dummy;
    Node *use = newNode(N_STMTLIST);
    for (;;) {
      bool br = false;
      if (tk.type == '&') { br = true; advance(); }
      if (tk.type != TK_VAR) { setError("syntax error, unexpected " + tokDesc()); break; }
      Node *v = newNode(N_VAR); v->name = tk.text; v->line = tk.line; v->i = br ? 1 : 0; advance();
      use->kids.push_back(v);
      if (accept(",")) continue;
      break;
    }
    expect(")");
    n->kids.push_back(use);
  } else {
    Node *use = newNode(N_STMTLIST);
    n->kids.push_back(use);
  }
  // return type
  if (accept(":")) {
    bool nl = false;
    if (tk.type == '&') { n->flags |= 4; advance(); }
    std::string ty;
    parseType(ty, nl);
    n->text2 = ty;
    n->flags2 = nl ? 1 : 0;
  }
  if (isArrow) {
    if (accept("{")) {
      Node *b = parseStmts(true);
      expect("}");
      n->kids.push_back(b);
      n->flags |= 8;
    } else {
      Node *e = parseExpr();
      Node *b = newNode(N_STMTLIST);
      Node *r = newNode(N_RETURN); r->kids.push_back(e);
      b->kids.push_back(r);
      n->kids.push_back(b);
    }
  } else {
    if (tk.type == '{') {
      Node *b = parseBlock();
      n->kids.push_back(b);
    } else {
      // abstract method: no body
      accept(";");
      Node *b = newNode(N_STMTLIST);
      n->kids.push_back(b);
      n->flags |= 8; // no body / abstract
    }
  }
  return n;
}
