    int op = -1;
    if (tk.type == TK_SHL) op = N_SHL;
    else if (tk.type == TK_SHR) op = N_SHR;
    if (op < 0) break;
    int ln = tk.line; advance();
    Node *r = parseAdd();
    Node *n = newNode(op); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n;
  }
  return l;
}
Node *Parser::parseAdd() {
  Node *l = parseMul();
  for (;;) {
    if (fail) break;
    int op = -1;
    if (tk.type == '+') op = N_ADD;
    else if (tk.type == '-') op = N_SUB;
    else if (tk.type == '.') op = N_CONCAT;
    if (op < 0) break;
    int ln = tk.line; advance();
    Node *r = parseMul();
    Node *n = newNode(op); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n;
