  for (;;) {
    if (fail) break;
    int op = -1;
    if (tk.type == '*') op = N_MUL;
    else if (tk.type == '/') op = N_DIV;
    else if (tk.type == '%') op = N_MOD;
    if (op < 0) break;
    int ln = tk.line; advance();
    Node *r = parseUnary();
    Node *n = newNode(op); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n;
  }
  return l;
}

Node *Parser::parseUnary() {
  int line = tk.line;
  switch (tk.type) {
    case '!': advance(); { Node *e = parseUnary(); Node *n = newNode(N_NOT); n->line = line; n->kids.push_back(e); return n; }
    case '~': advance(); { Node *e = parseUnary(); Node *n = newNode(N_BNOT); n->line = line; n->kids.push_back(e); return n; }
    case '-': advance(); { Node *e = parseUnary(); Node *n = newNode(N_NEG); n->line = line; n->kids.push_back(e); return n; }
    case '+': advance(); { Node *e = parseUnary(); Node *n = newNode(N_POS); n->line = line; n->kids.push_back(e); return n; }
    case TK_PLUSPLUS: advance(); { Node *e = parseUnary(); Node *n = newNode(N_PREINC); n->line = line; n->kids.push_back(e); return n; }
    case TK_MINUSMINUS: advance(); { Node *e = parseUnary(); Node *n = newNode(N_PREDEC); n->line = line; n->kids.push_back(e); return n; }
    case '(': {
      // possible cast
      Token save = tk;
      std::string ty;
      bool ok = false;
      if (lex.peek(0).type == TK_NAME) {
        std::string t2 = lc(lex.peek(0).text);
        if (t2=="int"||t2=="integer"||t2=="long"||t2=="float"||t2=="double"||t2=="real"||t2=="string"||t2=="bool"||t2=="boolean"||t2=="array"||t2=="object"||t2=="unset"||t2=="binary") {
          ok = true; ty = t2;
        }
      }
      if (ok) {
        advance(); advance(); expect(")");
        Node *e = parseUnary();
        Node *n = newNode(N_CAST); n->line = line; n->text = ty; n->kids.push_back(e);
        return n;
      }
      advance();
      Node *e = parseExpr();
      expect(")");
      return parsePostfix2(e);
    }
    case TK_ATTR: {
      advance();
      int depth = 1;
      while (depth > 0 && tk.type != TK_EOF) { if (tk.type=='[') depth++; else if (tk.type==']') depth--; advance(); }
      return parseUnary();
    }
    case TK_SPREAD: {
      advance();
      Node *e = parseUnary();
      Node *n = newNode(N_REF); n->line = line; n->flags = 1; n->kids.push_back(e);
      return n;
    }
    case '&': {
      advance();
      Node *e = parseUnary();
      Node *n = newNode(N_REF); n->line = line; n->kids.push_back(e);
      return n;
    }
    case '@': {
      advance();
      Node *e = parseUnary();
      e->flags2 |= 2; // suppress errors
      return e;
    }
  }
  if (isName("new")) return parseNew();
  return parsePostfix();
}

Node *Parser::parsePostfix2(Node *e) { return parsePostfixLoop(e); }
Node *Parser::parsePostfix() {
  Node *e = parsePrimary();
  return parsePostfixLoop(e);
}

Node *Parser::parsePostfixLoop(Node *e) {
  for (;;) {
    if (fail) return e;
    if (tk.type == TK_ARROW || (tk.type == '?' && lex.peek(0).type == TK_ARROW)) {
      bool nullsafe = tk.type == '?';
      if (nullsafe) advance();
      int ln = tk.line;
      advance();
      Node *n = newNode(N_MCALL);
      n->line = ln;
      n->flags = nullsafe ? 1 : 0;
      n->kids.push_back(e);
      if (tk.type == TK_VAR) {
