      if (tk.type == '{') {
        advance();
        Node *ex = parseExpr();
        expect("}");
        Node *dn = newNode(N_DYNAMICPROP);
        dn->line = ln; dn->kids.push_back(ex);
        n->kids.push_back(dn);
        e = n;
        continue;
      }
      std::string mname;
      if (tk.type == TK_NAME) mname = tk.text;
      else if (isName("class")) mname = tk.text;
      else setError("syntax error, unexpected " + tokDesc());
      Node *m = newNode(N_NAME);
      m->line = ln; m->name = mname;
      advance();
      n->kids.push_back(m);
      if (tk.type == '(') {
        // method call
        Node *c = newNode(N_CALL);
        c->line = ln; c->flags = 1;
        c->kids.push_back(n);
        parseCallArgs(c, true, ln);
        e = c;
        continue;
      }
      e = n;
      continue;
    }
    if (tk.type == TK_DCOLON) {
      int ln = tk.line;
      advance();
      Node *n = newNode(N_SCALL);
      n->line = ln;
      n->kids.push_back(e);
