    Node *n = newNode(N_XOR); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n; }
  return l;
}
Node *Parser::parseAndLvl() {
  Node *l = parseAssignLvl();
  while (isName("and") && !fail) { int ln = tk.line; advance(); Node *r = parseAssignLvl();
    Node *n = newNode(N_AND); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n; }
  return l;
}

static int assignOp(int t) {
  switch (t) {
    case '=': return N_ASSIGN;
    case TK_PLUSEQ: return N_ASSIGN_ADD;
    case TK_MINUSEQ: return N_ASSIGN_SUB;
    case TK_STAREQ: return N_ASSIGN_MUL;
    case TK_SLASHEQ: return N_ASSIGN_DIV;
    case TK_MODEQ: return N_ASSIGN_MOD;
    case TK_POWEQ: return N_ASSIGN_POW;
    case TK_DOTEQ: return N_ASSIGN_CONCAT;
    case TK_SHLEQ: return N_ASSIGN_SHL;
    case TK_SHREQ: return N_ASSIGN_SHR;
    case TK_ANDEQ: return N_ASSIGN_BAND;
    case TK_OREQ: return N_ASSIGN_BOR;
    case TK_XOREQ: return N_ASSIGN_BXOR;
    case TK_QUESTQUESTEQ: return N_ASSIGN_CO;
  }
  return -1;
}

Node *Parser::parseAssignLvl() {
  Node *l = parseTernary();
  if (fail) return l;
  int aop = assignOp(tk.type);
  if (aop < 0) return l;
  if (!isLValue(l)) { setError(std::string("syntax error, unexpected ") + tokDesc() + ", expecting \"(\""); return l; }
  int ln = tk.line;
  advance();
  Node *r = parseAssignLvl();
  Node *n = newNode(aop);
  n->line = ln;
  n->kids.push_back(l);
  n->kids.push_back(r);
  return n;
}

Node *Parser::parseTernary() {
  Node *cond = parseCoalesce();
  while (tk.type == '?' && !fail) {
    int ln = tk.line;
    advance();
    Node *thenP;
    if (tk.type == ':') { thenP = nullptr; }
    else thenP = parseAssignLvl();
    expect(":");
    Node *elseP = parseCoalesce();
    Node *n = newNode(N_COND);
    n->line = ln;
    n->kids.push_back(cond);
    n->kids.push_back(thenP ? thenP : cond);
    n->flags = thenP ? 0 : 1;
    n->kids.push_back(elseP);
    cond = n;
  }
  return cond;
}

Node *Parser::parseCoalesce() {
  Node *l = parseNullOr();
  if (tk.type == TK_QUESTQUEST) {
    int ln = tk.line; advance();
    Node *r = parseCoalesce();
    Node *n = newNode(N_NULLCO);
    n->line = ln; n->kids.push_back(l); n->kids.push_back(r);
    return n;
  }
  return l;
}
Node *Parser::parseNullOr() { return parseOrOr(); }
Node *Parser::parseOrOr() {
  Node *l = parseAndAnd();
