Node *Parser::parseBand() {
  Node *l = parseCmp();
  while (tk.type == '&' && !fail) { int ln = tk.line; advance(); Node *r = parseCmp();
    Node *n = newNode(N_BAND); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n; }
