}
Node *Parser::parseMul() {
  Node *l = parseUnary();
  for (;;) {
    if (fail) break;
    int op = -1;
    if (tk.type == '*') op = N_MUL;
    else if (tk.type == '/') op = N_DIV;
    else if (tk.type == '%') op = N_MOD;
    if (op < 0) break;
    int ln = tk.line; advance();
    Node *r = parseUnary();
    Node *n = newNode(op); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n;
  }
