  while (tk.type == '|' && !fail) { int ln = tk.line; advance(); Node *r = parseBxor();
    Node *n = newNode(N_BOR); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n; }
  return l;
}
Node *Parser::parseBxor() {
  Node *l = parseBand();
  while (tk.type == '^' && !fail) { int ln = tk.line; advance(); Node *r = parseBand();
    Node *n = newNode(N_BXOR); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n; }
  return l;
}
Node *Parser::parseBand() {
  Node *l = parseCmp();
  while (tk.type == '&' && !fail) { int ln = tk.line; advance(); Node *r = parseCmp();
    Node *n = newNode(N_BAND); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n; }
  return l;
}
static int cmpOp(int t) {
  switch (t) {
    case TK_EQ: return N_EQ;
    case TK_NE: return N_NE;
    case TK_SEQ: return N_SEQ;
    case TK_SNE: return N_SNE;
    case TK_SSP: return N_SPACESHIP;
    case '<': return N_LT;
    case '>': return N_GT;
    case TK_LE: return N_LE;
    case TK_GE: return N_GE;
    case TK_INSTANCEOF: return N_INSTANCEOF;
  }
  return -1;
}
Node *Parser::parseCmp() {
  Node *l = parseShift();
  for (;;) {
    if (fail) break;
    int op = cmpOp(tk.type);
    if (isName("instanceof")) op = N_INSTANCEOF;
    if (op < 0) break;
    int ln = tk.line;
    advance();
    Node *r;
    if (op == N_INSTANCEOF) {
      r = parseUnary();
      Node *n = newNode(N_INSTANCEOF); n->line = ln; n->kids.push_back(l); n->kids.push_back(r);
      l = n; continue;
    }
    r = parseShift();
    Node *n = newNode(op); n->line = ln; n->kids.push_back(l); n->kids.push_back(r);
    l = n;
  }
  return l;
}
Node *Parser::parseShift() {
  Node *l = parseAdd();
  for (;;) {
    if (fail) break;
    int op = -1;
    if (tk.type == TK_SHL) op = N_SHL;
    else if (tk.type == TK_SHR) op = N_SHR;
    if (op < 0) break;
    int ln = tk.line; advance();
    Node *r = parseAdd();
    Node *n = newNode(op); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n;
  }
  return l;
}
Node *Parser::parseAdd() {
  Node *l = parseMul();
  for (;;) {
    if (fail) break;
    int op = -1;
    if (tk.type == '+') op = N_ADD;
    else if (tk.type == '-') op = N_SUB;
    else if (tk.type == '.') op = N_CONCAT;
    if (op < 0) break;
    int ln = tk.line; advance();
    Node *r = parseMul();
    Node *n = newNode(op); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n;
  }
  return l;
}
Node *Parser::parseMul() {
  Node *l = parseUnary();
  for (;;) {
    if (fail) break;
    int op = -1;
    if (tk.type == '*') op = N_MUL;
    else if (tk.type == '/') op = N_DIV;
    else if (tk.type == '%') op = N_MOD;
    if (op < 0) break;
    int ln = tk.line; advance();
    Node *r = parseUnary();
    Node *n = newNode(op); n->line = ln; n->kids.push_back(l); n->kids.push_back(r); l = n;
  }
  return l;
}

Node *Parser::parseUnary() {
  int line = tk.line;
  switch (tk.type) {
    case '!': advance(); { Node *e = parseUnary(); Node *n = newNode(N_NOT); n->line = line; n->kids.push_back(e); return n; }
    case '~': advance(); { Node *e = parseUnary(); Node *n = newNode(N_BNOT); n->line = line; n->kids.push_back(e); return n; }
    case '-': advance(); { Node *e = parseUnary(); Node *n = newNode(N_NEG); n->line = line; n->kids.push_back(e); return n; }
    case '+': advance(); { Node *e = parseUnary(); Node *n = newNode(N_POS); n->line = line; n->kids.push_back(e); return n; }
    case TK_PLUSPLUS: advance(); { Node *e = parseUnary(); Node *n = newNode(N_PREINC); n->line = line; n->kids.push_back(e); return n; }
    case TK_MINUSMINUS: advance(); { Node *e = parseUnary(); Node *n = newNode(N_PREDEC); n->line = line; n->kids.push_back(e); return n; }
    case '(': {
      // possible cast
      Token save = tk;
      std::string ty;
      bool ok = false;
      if (lex.peek(0).type == TK_NAME) {
        std::string t2 = lc(lex.peek(0).text);
        if (t2=="int"||t2=="integer"||t2=="long"||t2=="float"||t2=="double"||t2=="real"||t2=="string"||t2=="bool"||t2=="boolean"||t2=="array"||t2=="object"||t2=="unset"||t2=="binary") {
          ok = true; ty = t2;
        }
      }
      if (ok) {
        advance(); advance(); expect(")");
        Node *e = parseUnary();
        Node *n = newNode(N_CAST); n->line = line; n->text = ty; n->kids.push_back(e);
        return n;
      }
      advance();
      Node *e = parseExpr();
      expect(")");
      return parsePostfix2(e);
    }
    case TK_ATTR: {
      advance();
      int depth = 1;
      while (depth > 0 && tk.type != TK_EOF) { if (tk.type=='[') depth++; else if (tk.type==']') depth--; advance(); }
      return parseUnary();
    }
    case TK_SPREAD: {
      advance();
      Node *e = parseUnary();
      Node *n = newNode(N_REF); n->line = line; n->flags = 1; n->kids.push_back(e);
      return n;
    }
    case '&': {
      advance();
      Node *e = parseUnary();
      Node *n = newNode(N_REF); n->line = line; n->kids.push_back(e);
      return n;
    }
    case '@': {
      advance();
      Node *e = parseUnary();
      e->flags2 |= 2; // suppress errors
      return e;
    }
  }
  if (isName("new")) return parseNew();
  return parsePostfix();
}

Node *Parser::parsePostfix2(Node *e) { return parsePostfixLoop(e); }
Node *Parser::parsePostfix() {
  Node *e = parsePrimary();
  return parsePostfixLoop(e);
}

Node *Parser::parsePostfixLoop(Node *e) {
  for (;;) {
    if (fail) return e;
    if (tk.type == TK_ARROW || (tk.type == '?' && lex.peek(0).type == TK_ARROW)) {
      bool nullsafe = tk.type == '?';
      if (nullsafe) advance();
      int ln = tk.line;
      advance();
      Node *n = newNode(N_MCALL);
      n->line = ln;
      n->flags = nullsafe ? 1 : 0;
      n->kids.push_back(e);
      if (tk.type == TK_VAR) {
        // dynamic property
        Node *dn = newNode(N_DYNAMICPROP);
        dn->line = ln;
        Node *v = newNode(N_VAR); v->name = tk.text; v->line = tk.line; advance();
        dn->kids.push_back(v);
        n->kids.push_back(dn);
        if (tk.type == '(') {
          Node *c = newNode(N_CALL);
          c->line = ln; c->flags = 1; // method call
          c->kids.push_back(n);
          parseCallArgs(c, true, ln);
          n = c;
          e = n;
          continue;
        }
        e = n;
        continue;
      }
      if (tk.type == '{') {
        advance();
        Node *ex = parseExpr();
        expect("}");
        Node *dn = newNode(N_DYNAMICPROP);
        dn->line = ln; dn->kids.push_back(ex);
        n->kids.push_back(dn);
        e = n;
        continue;
      }
      std::string mname;
      if (tk.type == TK_NAME) mname = tk.text;
      else if (isName("class")) mname = tk.text;
      else setError("syntax error, unexpected " + tokDesc());
      Node *m = newNode(N_NAME);
      m->line = ln; m->name = mname;
      advance();
      n->kids.push_back(m);
      if (tk.type == '(') {
        // method call
        Node *c = newNode(N_CALL);
        c->line = ln; c->flags = 1;
        c->kids.push_back(n);
        parseCallArgs(c, true, ln);
        e = c;
        continue;
      }
      e = n;
      continue;
    }
    if (tk.type == TK_DCOLON) {
      int ln = tk.line;
      advance();
      Node *n = newNode(N_SCALL);
      n->line = ln;
      n->kids.push_back(e);
      if (tk.type == TK_VAR) {
        Node *v = newNode(N_VAR); v->name = tk.text; v->line = tk.line; advance();
        n->kids.push_back(v);
        if (tk.type == '(') {
          Node *c = newNode(N_CALL);
          c->line = ln; c->flags = 2;
          c->kids.push_back(n);
          parseCallArgs(c, true, ln);
          e = c; continue;
        }
        e = n; continue;
      }
      if (tk.type == '{') {
        advance(); Node *ex = parseExpr(); expect("}");
        Node *dn = newNode(N_DYNAMICPROP); dn->line = ln; dn->kids.push_back(ex);
        n->kids.push_back(dn);
        e = n; continue;
      }
      std::string mname;
      if (tk.type == TK_NAME) mname = tk.text;
      else setError("syntax error, unexpected " + tokDesc());
      Node *m = newNode(N_NAME); m->line = ln; m->name = mname; advance();
      n->kids.push_back(m);
      if (tk.type == '(') {
        Node *c = newNode(N_CALL);
        c->line = ln; c->flags = 2;
        c->kids.push_back(n);
        parseCallArgs(c, true, ln);
        e = c; continue;
      }
      e = n; continue;
    }
    if (tk.type == '[') {
      int ln = tk.line;
      advance();
      Node *n = newNode(N_INDEX);
      n->line = ln;
      n->kids.push_back(e);
      if (tk.type != ']') n->kids.push_back(parseExpr());
      else n->kids.push_back(nullptr);
      expect("]");
      e = n;
      continue;
    }
    if (tk.type == '{') {
      // string offset (deprecated)
      int ln = tk.line;
      advance();
      Node *n = newNode(N_INDEX);
      n->line = ln;
      n->flags = 4;
      n->kids.push_back(e);
      n->kids.push_back(parseExpr());
      expect("}");
      e = n;
      continue;
    }
    if (tk.type == '(') {
      int ln = tk.line;
      Node *c = newNode(N_CALL);
      c->line = ln;
      c->flags = 0;
      c->kids.push_back(e);
      parseCallArgs(c, true, ln);
      e = c;
      continue;
    }
    if (tk.type == TK_PLUSPLUS) { int ln = tk.line; advance(); Node *n = newNode(N_INC); n->line = ln; n->kids.push_back(e); e = n; continue; }
    if (tk.type == TK_MINUSMINUS) { int ln = tk.line; advance(); Node *n = newNode(N_DEC); n->line = ln; n->kids.push_back(e); e = n; continue; }
    if (tk.type == TK_SPREAD && lex.peek(0).type == ')') {
      // first-class callable method: $obj->m(...)
      int ln = tk.line;
      advance();
      if (e->op == N_MCALL || e->op == N_SCALL || e->op == N_CALL) {
        e->flags |= 8; // mark as callable creation
      }
      Node *n = newNode(N_CALLABLE_PAREN);
      n->line = ln;
      n->kids.push_back(e);
      e = n;
      continue;
    }
    break;
  }
  return e;
}
