bool Parser::isLValue(Node *n) {
  if (!n) return false;
  switch (n->op) {
    case N_VAR: case N_INDEX: case N_PROP: case N_SPROP: case N_DYNAMICPROP:
    case N_MCALL: case N_SCALL: case N_CALL: case N_LIST_EXPR: case N_ARRAY: return true;
  }
