Node *Parser::parseNew() {
  int line = tk.line;
  advance();
  bool anon = false;
  Node *cls = nullptr;
  if (isName("class")) { anon = true; advance(); }
  Node *n = newNode(N_NEW);
  n->line = line;
  // class name
  if (tk.type == TK_VAR) {
    Node *dn = newNode(N_DYNAMICNAME);
    dn->line = line;
    Node *v = newNode(N_VAR); v->name = tk.text; v->line = tk.line; advance();
    // optional ::class
    if (accept(TK_DCOLON)) {
      if (isName("class")) { advance(); dn->flags = 1; }
      else setError("syntax error, unexpected " + tokDesc());
    }
    dn->kids.push_back(v);
    cls = dn;
  } else if (tk.type == '(') {
    advance();
    cls = parseExpr();
    expect(")");
  } else if (tk.type == TK_NAME) {
    if (isName("self") || isName("static") || isName("parent")) {
      Node *sn = newNode(isName("self") ? N_SELF : isName("static") ? N_STATIC : N_PARENT);
      sn->line = line;
      advance();
      cls = sn;
    } else {
      cls = parseNameRef();
    }
  } else setError("syntax error, unexpected " + tokDesc() + ", expecting identifier");
  if (anon) {
    // optional args, extends, implements, body
    if (tk.type == '(') {
      Node *c = newNode(N_CALL);
      c->line = line; c->flags = 4;
      parseCallArgs(c, true, line);
      n->kids.push_back(c); // args holder
    } else {
      Node *c = newNode(N_CALL);
      c->line = line; c->flags = 4;
      c->kids.push_back(nullptr);
      n->kids.push_back(c);
    }
    Node *ext = nullptr;
    std::vector<Node*> impls;
    if (acceptName("extends")) ext = parseNameRef();
    if (acceptName("implements")) { for (;;) { impls.push_back(parseNameRef()); if (accept(",")) continue; break; } }
    expect("{");
    std::vector<Node*> body;
    while (tk.type != '}' && !fail) {
      body.push_back(parseMethodDecl(line));
    }
    expect("}");
    Node *b = newNode(N_CLASSBODY);
    b->kids = std::move(body);
    n->kids.push_back(ext);
    Node *il = newNode(N_STMTLIST); il->kids = std::move(impls);
    n->kids.push_back(il);
    n->kids.push_back(b);
    n->flags |= 16; // anonymous
    return n;
  }
  if (tk.type == '(') {
    Node *c = newNode(N_CALL);
    c->line = line; c->flags = 4;
    parseCallArgs(c, true, line);
    n->kids.push_back(c);
  } else {
    Node *c = newNode(N_CALL);
    c->line = line; c->flags = 4;
    c->kids.push_back(nullptr);
    n->kids.push_back(c);
  }
  n->kids.push_back(cls);
  return n;
}

// parse a (possibly qualified) class name
Node *Parser::parseNameRef() {
  int line = tk.line;
  std::string name;
  if (tk.type == TK_BACKSLASH) { advance(); name = "\\"; }
  if (tk.type != TK_NAME) { setError("syntax error, unexpected " + tokDesc() + ", expecting identifier"); return newNode(N_NOP); }
  name += tk.text;
  advance();
  while (tk.type == TK_BACKSLASH) {
    advance();
    if (tk.type != TK_NAME) break;
    name += "\\" + tk.text;
    advance();
  }
  Node *n = newNode(N_NAME);
  n->line = line;
  n->name = name;
  return n;
}

Node *Parser::parseCallArgs(Node *call, bool allowNamed, int line) {
  expect("(");
  bool sawNamed = false;
  bool firstClass = false;
  if (tk.type == TK_SPREAD && lex.peek(0).type == ')') {
    // first-class callable syntax
    advance();
    expect(")");
    call->flags |= 8;
    return call;
  }
  while (tk.type != ')' && tk.type != TK_EOF) {
    if (tk.type == TK_SPREAD) {
      advance();
      Node *e = parseExpr();
      Node *sp = newNode(N_SPREAD);
      sp->line = tk.line;
      sp->kids.push_back(e);
      call->kids.push_back(sp);
    } else if (tk.type == TK_NAME && lex.peek(0).type == ':' && lex.peek(1).type != ':') {
      std::string nm = tk.text;
      advance(); advance();
      Node *e = parseExpr();
      Node *na = newNode(N_NAMEDARG);
      na->line = tk.line;
      na->name = nm;
      na->kids.push_back(e);
      call->kids.push_back(na);
      sawNamed = true;
    } else {
      bool isRef = false;
      if (tk.type == '&') { isRef = true; advance(); }
      Node *e = parseExpr();
      if (isRef) {
        Node *r = newNode(N_REF); r->kids.push_back(e);
        call->kids.push_back(r);
      } else call->kids.push_back(e);
    }
    if (accept(",")) continue;
    break;
  }
  expect(")");
  return call;
}

Node *Parser::parseArrayLit() {
  int line = tk.line;
  advance(); // '['
  Node *n = newNode(N_ARRAY);
  n->line = line;
  for (;;) {
    if (tk.type == ']') break;
    if (tk.type == ',') { Node *x = newNode(N_NOP); n->kids.push_back(x); advance(); continue; }
    bool spread = false;
    if (tk.type == TK_SPREAD) { spread = true; advance(); }
    Node *e = parseExpr();
    if (acceptArrow()) {
      Node *kv = newNode(N_KEYVAL);
      kv->line = line;
      kv->kids.push_back(e);
      kv->kids.push_back(parseExpr());
      n->kids.push_back(kv);
    } else if (spread) {
      Node *sp = newNode(N_SPREAD);
      sp->kids.push_back(e);
      n->kids.push_back(sp);
    } else {
      n->kids.push_back(e);
    }
    if (accept(",")) continue;
    break;
  }
  expect("]");
  return n;
}

Node *Parser::parseMatch() {
  int line = tk.line;
  advance();
  expect("(");
  Node *subj = parseExpr();
  expect(")");
  expect("{");
  Node *n = newNode(N_MATCH);
  n->line = line;
  n->kids.push_back(subj);
  while (tk.type != '}' && !fail) {
    Node *arm = newNode(N_MATCHARM);
    arm->line = tk.line;
    if (isName("default")) {
      advance();
      arm->flags = 1;
    } else {
      for (;;) {
        Node *c = parseExpr();
        arm->kids.push_back(c);
        if (accept(",")) continue;
        break;
      }
    }
    expectName("=>");
    arm->kids.push_back(parseExpr());
    n->kids.push_back(arm);
    if (accept(",")) continue;
    break;
  }
  expect("}");
  return n;
}

Node *Parser::parseEncapsed(Token &t, int line, bool backtick) {
  Node *n = newNode(backtick ? N_BACKTICK : N_ENCAP);
  n->line = line;
  for (auto &p : t.parts) {
    if (p.first == 0) {
      Node *s = newNode(N_STR);
      s->lit = Value(processStringEscapes(p.second));
      n->kids.push_back(s);
    } else if (p.first == 1) {
      Node *v = newNode(N_VAR);
      v->name = p.second;
      v->line = line;
      n->kids.push_back(v);
    } else if (p.first == 2) {
      Node *e = parseSubExpr(p.second);
      if (!e) e = newNode(N_STR);
      n->kids.push_back(e);
    } else if (p.first == 3) {
      // ${name} deprecated
      Node *v = newNode(N_VAR);
      v->name = p.second;
      v->flags = 1;
      n->kids.push_back(v);
    } else if (p.first == 5) {
      // quoted key on $a['k']
      Node *idx = newNode(N_INDEX);
      idx->line = line;
      idx->kids.push_back(n->kids.back());
      idx->kids.push_back(nullptr);
      std::string key = p.second;
      if (key.size() >= 2) key = key.substr(1, key.size() - 2);
      processStringEscapesInPlace(key);
      Node *kv = newNode(N_STR);
      kv->lit = Value(key);
      idx->kids[1] = kv;
      n->kids.back() = idx;
    } else if (p.first == 6) {
      Node *idx = newNode(N_INDEX);
      idx->line = line;
      idx->kids.push_back(n->kids.back());
      if (p.second.empty()) idx->kids.push_back(nullptr);
      else {
        Node *kv = newNode(N_STR);
        kv->lit = Value(p.second);
        idx->kids.push_back(kv);
      }
      n->kids.back() = idx;
    } else if (p.first == 7) {
      Node *idx = newNode(N_INDEX);
      idx->line = line;
      idx->kids.push_back(n->kids.back());
      Node *v = newNode(N_VAR); v->name = p.second;
      idx->kids.push_back(v);
      n->kids.back() = idx;
    } else if (p.first == 8) {
      Node *pr = newNode(N_PROP);
      pr->line = line;
      pr->kids.push_back(n->kids.back());
      Node *nm = newNode(N_NAME); nm->name = p.second;
      pr->kids.push_back(nm);
      n->kids.back() = pr;
    }
  }
  return n;
}
