std::string processStringEscapes(const std::string &in) {
  Lexer tmp(in.c_str(), in.size(), "");
  return tmp.processEscapes(in, true);
}
void processStringEscapesInPlace(std::string &in) { in = processStringEscapes(in); }
Node *Parser::parseSubExpr(const std::string &src) {
  Parser p(src.c_str(), src.size(), file, prog);
  Node *e = p.parseExpr();
  if (p.fail || p.tk.type != TK_EOF) {
    // tolerate errors
  }
  return e;
}

Node *Parser::parsePrimary() {
  int line = tk.line;
  switch (tk.type) {
    case TK_INT: { Node *n = newNode(N_INT); n->lit = Value(tk.i); n->line = line; advance(); return n; }
    case TK_FLOAT: { Node *n = newNode(N_FLOAT); n->lit = Value(tk.d); n->line = line; advance(); return n; }
    case TK_STR: { Node *n = newNode(N_STR); n->lit = Value(tk.text); n->line = line; advance(); return n; }
    case TK_ENCAP: {
      Token t = tk;
      if (t.parts.empty()) {
        Node *n = newNode(N_STR);
        n->lit = Value(t.heredoc ? processStringEscapes(t.text) : processStringEscapes(t.text));
        n->line = line;
        advance();
        return n;
      }
      advance();
      return parseEncapsed(t, line, false);
    }
    case TK_VAR: {
      return parseVarExpr(true);
    }
    case TK_BACKSLASH: {
      return parseNameRef();
    }
    case TK_NAME: {
      const std::string k = lc(tk.text);
      if (k == "true") { advance(); Node *n = newNode(N_STR); n->lit = Value(true); n->line = line; return n; }
      if (k == "false") { advance(); Node *n = newNode(N_STR); n->lit = Value(false); n->line = line; return n; }
      if (k == "null") { advance(); Node *n = newNode(N_STR); n->lit = Value(); n->line = line; return n; }
      if (k == "new") return parseNew();
      if (k == "function" || k == "fn") return parseFuncDecl(true);
      if (k == "array") {
        advance();
        expect("(");
        Node *n = newNode(N_ARRAY);
        n->line = line;
        for (;;) {
          if (tk.type == ')') break;
          if (tk.type == ',') { Node *x = newNode(N_NOP); n->kids.push_back(x); advance(); continue; }
          bool spread = false;
          if (tk.type == TK_SPREAD) { spread = true; advance(); }
          Node *e = parseExpr();
          if (acceptArrow()) {
            Node *kv = newNode(N_KEYVAL); kv->line = line; kv->kids.push_back(e); kv->kids.push_back(parseExpr());
            n->kids.push_back(kv);
          } else if (spread) {
            Node *sp = newNode(N_SPREAD); sp->kids.push_back(e); n->kids.push_back(sp);
          } else n->kids.push_back(e);
          if (accept(",")) continue;
          break;
        }
        expect(")");
        return n;
      }
      if (k == "list") { Node *n = parseListDestructure(); return n; }
      if (k == "match") return parseMatch();
      if (k == "isset" || k == "empty") {
        advance(); expect("(");
        Node *n = newNode(k == "isset" ? N_ISSET : N_EMPTY);
        n->line = line;
        for (;;) {
          Node *e = parseExpr();
          n->kids.push_back(e);
          if (accept(",")) continue;
          break;
        }
        expect(")");
        return n;
      }
      if (k == "unset") {
        advance(); expect("(");
        Node *n = newNode(N_UNSET);
        n->line = line;
        for (;;) { Node *e = parseExpr(); n->kids.push_back(e); if (accept(",")) continue; break; }
        expect(")");
        return n;
      }
      if (k == "exit" || k == "die") {
        advance();
        Node *n = newNode(N_EXIT);
        n->line = line;
        if (tk.type == '(') {
          advance();
          if (tk.type != ')') n->kids.push_back(parseExpr());
          expect(")");
        }
        return n;
      }
      if (k == "include" || k == "include_once" || k == "require" || k == "require_once") {
        int op = k == "include" ? N_INCLUDE : k == "include_once" ? N_INCLUDE_ONCE : k == "require" ? N_REQUIRE : N_REQUIRE_ONCE;
        advance();
        Node *e = parseExpr();
        Node *n = newNode(op);
        n->line = line; n->kids.push_back(e);
        return n;
      }
      if (k == "print") {
        advance();
        Node *e = parseExpr();
        Node *n = newNode(N_PRINT);
        n->line = line; n->kids.push_back(e);
        return n;
      }
      if (k == "clone") {
        advance();
        Node *e = parseUnary();
        Node *n = newNode(N_CLONE);
        n->line = line; n->kids.push_back(e);
        return n;
      }
      if (k == "yield") {
        advance();
        Node *n = newNode(N_YIELD);
        n->line = line;
        if (tk.type != ';' && tk.type != ')' && tk.type != ']' && tk.type != ',' && tk.type != '}') {
          n->kids.push_back(parseExpr());
          if (acceptArrow()) {
            n->op = N_YIELD_KV;
            n->kids.push_back(parseExpr());
          }
        }
        return n;
      }
      if (k == "static") {
        if (lex.peek(0).type == TK_NAME && (lc(lex.peek(0).text)=="function" || lc(lex.peek(0).text)=="fn")) {
          return parseFuncDecl(true);
        }
        if (lex.peek(0).type == TK_DCOLON) {
          advance();
          Node *n = newNode(N_STATIC);
          n->line = line;
          return n;
        }
      }
      if (k == "self" || k == "parent") {
        Node *n = newNode(k == "self" ? N_SELF : N_PARENT);
        n->line = line;
        advance();
        return n;
      }
      // generic name: could be constant, function call, class ref
      {
        Node *nm = parseNameRef();
        if (tk.type == TK_DCOLON) {
          // handled by postfix
          return nm;
        }
        if (tk.type == '(') {
          Node *c = newNode(N_CALL);
          c->line = line;
          c->flags = 0;
          c->name = nm->name;
          parseCallArgs(c, true, line);
          return c;
        }
        return nm;
      }
    }
    case '(': {
      advance();
      Node *e = parseExpr();
      expect(")");
      return parsePostfix2(e);
    }
    case '[': {
      Node *n = parseArrayLit();
      return parsePostfix2(n);
    }
    case '-': case '+': case '!': case '~': case TK_PLUSPLUS: case TK_MINUSMINUS: case '&': case '@': {
      return parseUnary();
    }
    case ';': {
      setError(std::string("syntax error, unexpected ") + tokDesc());
      advance();
      return newNode(N_NOP);
    }
    default: {
      setError(std::string("syntax error, unexpected ") + tokDesc());
      advance();
      return newNode(N_NOP);
    }
  }
}

Node *Parser::parseVarExpr(bool allowRefs) {
  int line = tk.line;
  if (tk.type != TK_VAR) { setError("syntax error, unexpected " + tokDesc()); return newNode(N_NOP); }
  if (tk.text.empty()) {
    // $ followed by variable or {expr} : variable variable
    advance();
    Node *inner;
    if (tk.type == '{') {
      advance();
      inner = parseExpr();
      expect("}");
    } else {
      inner = parseVarExpr(false);
    }
    Node *n = newNode(N_DYNAMICNAME);
    n->line = line;
    n->kids.push_back(inner);
    return n;
  }
  Node *n = newNode(N_VAR);
  n->name = tk.text;
  n->line = line;
  advance();
  return n;
}
