      if (tk.type == TK_BACKSLASH) { advance(); }
      if (tk.type != TK_NAME) break;
      Node *t = newNode(N_NAME);
      t->name = tk.text;
      t->line = tk.line;
      advance();
      while (tk.type == TK_BACKSLASH) { advance(); if (tk.type == TK_NAME) { t->name += "\\" + tk.text; advance(); } }
      types->kids.push_back(t);
      if (accept(",")) continue;
      break;
    }
    if (tk.type != TK_VAR) setError("syntax error, unexpected " + tokDesc() + ", expecting variable");
    Node *var = newNode(N_VAR);
    var->name = tk.text; var->line = tk.line; advance();
    expect(")");
    Node *cbody = parseBlock();
    Node *c = newNode(N_STMTLIST);
    c->kids.push_back(types);
    c->kids.push_back(var);
    c->kids.push_back(cbody);
    n->kids.push_back(c);
  }
  if (isName("finally")) {
    advance();
    Node *f = parseBlock();
    n->kids.push_back(f);
  }
  return n;
}

