// ---------- program / arena ----------
Program::~Program() {}

std::string classNameOfObj(const Ref &o) { return o ? o->clsName : std::string(""); }

// ---------- helpers ----------
Ref Interp::newVar(const std::string &name) {
  if (stack.size() <= 1) { auto &r = globals[name]; if (!r) r = std::make_shared<Value>(); return r; }
  auto &f = stack.back();
  auto &r = f.vars[name];
  if (!r) r = std::make_shared<Value>();
  return r;
}
Ref Interp::findVar(const std::string &name) {
  if (stack.size() <= 1) { auto it = globals.find(name); return it == globals.end() ? nullptr : it->second; }
  auto &f = stack.back();
  auto it = f.vars.find(name);
  return it == f.vars.end() ? nullptr : it->second;
}
Ref Interp::declareGlobal(const std::string &name) {
  auto &r = globals[name];
  if (!r) r = std::make_shared<Value>();
  return r;
}

Ref Interp::constGet(const std::string &name, bool *found) {
  auto it = constants.find(name);
  if (it != constants.end()) { if (found) *found = true; return it->second; }
  if (found) *found = false;
  return nullptr;
}
void Interp::constSet(const std::string &name, Value v, bool caseInsensitive) {
  constants[name] = std::make_shared<Value>(std::move(v));
}

// ---------- output ----------
void Interp::writeOut(const std::string &s) {
  if (obLevel > 0) { obBuffers.back() += s; return; }
  fwrite(s.data(), 1, s.size(), stdout);
  fflush(stdout);
}
void Interp::out(const std::string &s) { writeOut(s); }

void Interp::echoOut(const Value &v) {
  bool isnan = false;
  std::string s = toStr(v, this, &isnan);
  if (isnan) {
    logError(E_WARNING, "unexpected NAN value was coerced to string", -1);
  }
  writeOut(s);
}
void Interp::echoOut(const std::string &s) { writeOut(s); }

// ---------- error reporting ----------
static const char *errPrefix(int type) {
  switch (type) {
    case E_ERROR: return "Fatal error";
    case E_WARNING: return "Warning";
    case E_NOTICE: return "Notice";
    case E_DEPRECATED: return "Deprecated";
    case E_USER_ERROR: return "Fatal error";
    case E_USER_WARNING: return "Warning";
    case E_USER_NOTICE: return "Notice";
    case E_USER_DEPRECATED: return "Deprecated";
    case E_STRICT: return "Deprecated";
    case E_PARSE: return "Parse error";
    case E_COMPILE_ERROR: return "Fatal error";
    case E_COMPILE_WARNING: return "Warning";
    default: return "Warning";
  }
}

void Interp::logError(int type, const std::string &msg, int line) {
  if (!(errorReporting & type)) return;
  if (suppress > 0) return;
  Frame *f = stack.empty() ? nullptr : &stack.back();
  std::string file = f ? f->file : curFile;
  if (line < 0) line = f ? f->curLine : 0;
  if (errorHandler) {
    // call user error handler
    std::vector<Arg> args;
    Arg a1; a1.cell = std::make_shared<Value>((int64_t)type);
    Arg a2; a2.cell = std::make_shared<Value>(msg);
    Arg a3; a3.cell = std::make_shared<Value>(file);
    Arg a4; a4.cell = std::make_shared<Value>((int64_t)line);
    args.push_back(a1); args.push_back(a2); args.push_back(a3); args.push_back(a4);
    std::vector<Frame> savedStack = stack;
    try {
      callFunc(errorHandler, args, line, "");
    } catch (PHPThrow &t) {
      // uncaught exception from error handler -> fatal
      stack = savedStack;
      printUncaught(t);
      fflush(stdout);
      exit(255);
    } catch (...) {
      stack = savedStack;
    }
    return;
  }
  std::string buf;
  buf += "\n";
  buf += errPrefix(type);
  buf += ": ";
  buf += msg;
  buf += " in ";
  buf += file;
  if (line > 0) { buf += " on line "; buf += std::to_string(line); }
  buf += "\n";
  writeOut(buf);
}

void Interp::raise(int type, const std::string &msg, int line) {
  logError(type, msg, line);
  if (type == E_ERROR || type == E_USER_ERROR || type == E_COMPILE_ERROR || type == E_PARSE) {
    // fatal: terminate
    std::string buf = "\nFatal error: " + msg + " in ";
    Frame *f = stack.empty() ? nullptr : &stack.back();
    std::string file = f ? f->file : curFile;
    if (line < 0) line = f ? f->curLine : 0;
    buf += file;
    if (line > 0) { buf += ":"; buf += std::to_string(line); }
    buf += "\nStack trace:\n#0 {main}\n";
    writeOut(buf);
    exit(255);
  }
}

void Interp::fatal(const char *cls, const std::string &msg, int line, const std::vector<Value> *args) {
  Value exc = makeException(cls, msg, line, args, &stack);
  std::string c = cls;
  throwException(std::move(exc), c.c_str(), msg, line, &stack);
}

// ---------- exception construction ----------
Value Interp::makeException(const char *clsName, const std::string &msg, int line, const std::vector<Value> *args, const std::vector<Frame> *st, int prevLine) {
  auto it = classes.find(lc(clsName));
  std::shared_ptr<ClassDef> cls;
  if (it != classes.end()) cls = it->second;
  else cls = ensureBuiltinClass(clsName);
  auto o = std::make_shared<ObjData>();
  o->cls = cls;
  o->clsName = cls ? cls->name : clsName;
  o->handle = ++objCount;
  o->kind = 3; // exception-ish
  Ref mp = std::make_shared<Value>(msg);
  o->setProp("message", mp);
  Ref cp = std::make_shared<Value>((int64_t)0);
  o->setProp("code", cp);
  Frame *f = stack.empty() ? nullptr : &stack.back();
  std::string file = f ? f->file : curFile;
  int ln = line > 0 ? line : (f ? f->curLine : 0);
  Ref fp = std::make_shared<Value>(file);
  o->setProp("file", fp);
  Ref lp = std::make_shared<Value>((int64_t)ln);
  o->setProp("line", lp);
  Ref tp = std::make_shared<Value>(formatTrace(st ? *st : stack));
  o->setProp("trace", tp);
  Value v; v.k = VKObj; v.obj = o;
  // call constructor if user-defined
  if (cls && cls->name.size() && !cls->isInterface) {
    auto m = findMethod(cls, "__construct");
    if (m) {
      std::vector<Arg> cargs;
      if (args) {
        for (auto &a : *args) { Arg x; x.cell = std::make_shared<Value>(a); cargs.push_back(x); }
      }
      stack.push_back(Frame());
      Frame &fr = stack.back();
      fr.callName = o->clsName + "::__construct";
      fr.file = file; fr.line = ln; fr.curLine = ln; fr.thisObj = std::make_shared<Value>(v);
      fr.args = args ? *args : std::vector<Value>();
      runFuncDef(m, fr.thisObj, cargs, ln, fr.callName, false);
      stack.pop_back();
    }
  }
  return v;
}

void Interp::throwException(Value exc, const char *cls, const std::string &msg, int line, const std::vector<Frame> *st) {
  PHPThrow t;
  t.exc = exc;
  t.cls = cls;
  t.msg = msg;
  Frame *f = stack.empty() ? nullptr : &stack.back();
  t.file = f ? f->file : curFile;
  t.line = line > 0 ? line : (f ? f->curLine : 0);
  t.trace = formatTrace(st ? *st : stack);
  throw t;
}

std::string Interp::formatTrace(const std::vector<Frame> &st) {
  std::string out;
  for (size_t i = 0; i < st.size(); i++) {
    out += "#";
    out += std::to_string(i);
    out += " ";
    if (st[i].callName == "{main}") { out += "{main}"; }
    else {
      out += st[i].file;
      out += "(";
      out += std::to_string(st[i].line);
      out += "): ";
      out += st[i].callName;
      out += "(";
      for (size_t j = 0; j < st[i].args.size(); j++) {
        if (j) out += ", ";
        out += traceArgStr(st[i].args[j], this);
      }
      out += ")";
    }
    out += "\n";
  }
  return out;
}
