#include "interp.h"
#include "builtin.h"
#include <cmath>
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <algorithm>

// ---------- deep copy / separation ----------
Value deepCopyVal(const Value &v) {
  if (v.k == VKArr) {
    auto a = std::make_shared<ArrData>();
    a->next = v.arr->next;
    for (auto &en : v.arr->e) {
      Value nv = deepCopyVal(*en.val);
      a->set(en.key, std::make_shared<Value>(std::move(nv)));
    }
    Value r; r.k = VKArr; r.arr = a;
    return r;
  }
  if (v.k == VKObj) return v; // objects are references
  return v;
}

// Separate an array value: if shared, deep copy
Value sepVal(const Value &v) {
  if (v.k != VKArr) return v;
  if (v.arr.use_count() > 1) return deepCopyVal(v);
  return v;
}

void storeVal(Ref &cell, Value &&v) {
  if (v.k == VKArr) {
    if (v.arr.use_count() > 1) {
      Value nv = deepCopyVal(v);
      v = std::move(nv);
    }
  }
  if (!cell) cell = std::make_shared<Value>();
  *cell = std::move(v);
}

Value valueOfArg(const Arg &a) { return a.cell ? *a.cell : Value(); }
Ref cellOfArg(Arg &a) { return a.cell; }

// ---------- key normalization ----------
Value normalizeKey(const Value &k, Interp *I, int line, bool *deprecated) {
  switch (k.k) {
    case VKInt: return k;
    case VKBool: return Value(k.b ? (int64_t)1 : (int64_t)0);
    case VKFloat: {
      double d = k.d;
      if (d == (double)(int64_t)d) return Value((int64_t)d);
      if (I && deprecated) *deprecated = true;
      if (I) {
        char buf[128];
        snprintf(buf, sizeof buf, "Implicit conversion from float %s to int loses precision", fmtFloat(d, I->precision).c_str());
        I->logError(E_DEPRECATED, buf, line);
      }
      return Value((int64_t)d);
    }
    case VKStr: {
      // canonical integer string?
      const std::string &s = k.s;
      size_t i = 0, n = s.size();
      if (i < n && (s[i] == '-' || s[i] == '+')) i++;
      if (i >= n) return k;
      bool digitsOnly = true;
      for (size_t j = i; j < n; j++) if (!isdigit((unsigned char)s[j])) { digitsOnly = false; break; }
      if (!digitsOnly) return k;
      if (n - i > 1 && s[i] == '0') return k;
      errno = 0;
      char *end = nullptr;
      long long v = strtoll(s.c_str(), &end, 10);
      if (end && *end == 0) {
        if (s[0] == '+') return Value((int64_t)v);
        return Value((int64_t)v);
      }
      return k;
    }
    case VKNull:
      if (I) I->logError(E_DEPRECATED, "Using null as an array offset is deprecated, use an empty string instead", line);
      return Value(std::string(""));
    case VKArr:
      if (I) I->fatal("TypeError", "Illegal offset type", line);
      return Value();
    case VKObj:
      if (I) I->fatal("TypeError", "Illegal offset type", line);
      return Value();
    case VKRes:
      if (I) I->fatal("TypeError", "Illegal offset type", line);
      return Value();
  }
  return k;
}

// ---------- trace arg strings ----------
std::string traceArgStr(const Value &v, Interp *I) {
  switch (v.k) {
    case VKNull: return "NULL";
    case VKBool: return v.b ? "true" : "false";
    case VKInt: return intToStr(v.i);
    case VKFloat: return varDumpFloat(v.d);
    case VKStr: {
      std::string s = "'";
      for (char c : v.s) {
        if (c == '\'') s += "\\'";
        else if (c == '\\') s += "\\\\";
        else s += c;
      }
      s += "'";
      return s;
    }
    case VKArr: return "Array";
    case VKObj: return v.obj ? v.obj->clsName : std::string("object");
    case VKRes: return "Resource id #" + std::to_string(v.res ? (long)v.res->id : 0);
  }
  return "";
}

// ---------- var_dump ----------
static void varDumpIndent(std::string &o, int indent) { for (int i = 0; i < indent; i++) o += ' '; }

std::string varDumpStr(const Value &v, int indent, Interp *I, std::vector<const Value*> *seen) {
  std::string o;
  bool isRec = false;
  if (seen) for (auto s : *seen) if (s == &v) { isRec = true; break; }
  switch (v.k) {
    case VKNull: o += "NULL"; break;
    case VKBool: o += v.b ? "bool(true)" : "bool(false)"; break;
    case VKInt: o += "int(" + intToStr(v.i) + ")"; break;
    case VKFloat: o += "float(" + varDumpFloat(v.d) + ")"; break;
    case VKStr: o += "string(" + std::to_string(v.s.size()) + ") \"" + v.s + "\""; break;
    case VKRes: o += "resource(" + std::to_string(v.res ? (long)v.res->id : 0) + ")"; break;
    case VKObj: {
      if (!v.obj) { o += "object(null)#0 (0) {\n}"; break; }
      o += "object(" + v.obj->clsName + ")#" + std::to_string(v.obj->handle) + " (" + std::to_string(v.obj->props.size()) + ") {\n";
      if (seen) seen->push_back(&v);
      for (auto &p : v.obj->props) {
        varDumpIndent(o, indent + 2);
        o += "[\"" + p.name + "\"]";
        // visibility info
        if (I) {
          std::shared_ptr<ClassDef> c = I->findClass(v.obj->clsName);
          std::string visStr;
          if (c) {
            std::shared_ptr<ClassDef> owner;
            if (I->classHasProp(c, p.name, &owner, &visStr)) {
              if (visStr == "protected") o += ":protected";
              else if (visStr == "private") { o += ":\"" + owner->name + "\":private"; }
            }
          }
        }
        o += "=>\n";
        varDumpIndent(o, indent + 2);
        o += varDumpStr(*p.val, indent + 2, I, seen);
        o += "\n";
      }
      varDumpIndent(o, indent);
      o += "}";
      if (seen && !seen->empty()) seen->pop_back();
      break;
    }
    case VKArr: {
      o += "array(" + std::to_string(v.arr->e.size()) + ") {\n";
      if (seen) seen->push_back(&v);
      for (auto &en : v.arr->e) {
        varDumpIndent(o, indent + 2);
        if (en.key.k == VKInt) o += "[" + intToStr(en.key.i) + "]=>\n";
        else o += "[\"" + en.key.s + "\"]=>\n";
        varDumpIndent(o, indent + 2);
        if (isRec) { o += "*RECURSION*"; }
        else o += varDumpStr(*en.val, indent + 2, I, seen);
        o += "\n";
      }
      varDumpIndent(o, indent);
      o += "}";
      if (seen && !seen->empty()) seen->pop_back();
      break;
    }
  }
  return o;
}
