// ---------- print_r ----------
std::string printRStr(const Value &v, int level, Interp *I, std::vector<const void*> *seen) {
  std::string o;
  bool rec = false;
  if (seen) for (auto s : *seen) if (s == (v.k==VKArr ? (const void*)v.arr.get() : (v.k==VKObj ? (const void*)v.obj.get() : nullptr))) rec = true;
  if (v.k == VKArr) {
