    if (seen) seen->push_back(v.obj.get());
    o += std::string(level*8, ' ') + "(\n";
    for (auto &p : v.obj->props) {
      o += std::string(level*8 + 4, ' ') + "[" + p.name + "] => ";
      o += printRStr(*p.val, level + 1, I, seen);
      o += "\n";
    }
    o += std::string(level*8, ' ') + ")\n";
    if (seen && !seen->empty()) seen->pop_back();
    return o;
