// ---------- var_export ----------
static std::string exportStr(const std::string &s) {
  std::string o = "'";
  for (char c : s) {
    if (c == '\'' || c == '\\') o += '\\';
    o += c;
  }
  o += "'";
  return o;
}

static const void *identOf(const Value &v) {
  if (v.k == VKArr) return v.arr.get();
  if (v.k == VKObj) return v.obj.get();
  return nullptr;
}

std::string varExportStr(const Value &v, int level, Interp *I, std::vector<const void*> *seen, bool *failed) {
  std::string o;
  switch (v.k) {
    case VKNull: return "NULL";
    case VKBool: return v.b ? "true" : "false";
    case VKInt: return intToStr(v.i);
    case VKFloat: return varDumpFloat(v.d);
    case VKStr: return exportStr(v.s);
    case VKRes: return "NULL";
    case VKArr: {
      if (seen && std::find(seen->begin(), seen->end(), identOf(v)) != seen->end()) {
        if (I) I->logError(E_WARNING, "var_export does not handle circular references", -1);
        if (failed) *failed = true;
        return "NULL";
      }
      std::vector<const void*> local;
      if (seen) local = *seen;
      local.push_back(identOf(v));
      o += std::string(level*2, ' ') + "array (\n";
      for (auto &en : v.arr->e) {
        o += std::string(level*2 + 2, ' ');
        if (en.key.k == VKInt) o += intToStr(en.key.i);
        else o += exportStr(en.key.s);
        o += " => ";
        Value cv = *en.val;
        if (cv.k == VKArr || cv.k == VKObj) o += varExportStr(cv, level + 1, I, &local, failed);
        else o += varExportStr(cv, level, I, &local, failed);
        o += ",\n";
      }
      o += std::string(level*2, ' ') + ")";
      return o;
    }
    case VKObj: {
      if (seen && std::find(seen->begin(), seen->end(), identOf(v)) != seen->end()) {
        if (I) I->logError(E_WARNING, "var_export does not handle circular references", -1);
        if (failed) *failed = true;
        return "NULL";
      }
      std::vector<const void*> local;
      if (seen) local = *seen;
      local.push_back(identOf(v));
      std::string cls = v.obj ? v.obj->clsName : std::string("stdClass");
      bool isStd = lc(cls) == "stdclass";
      o += std::string(level*2, ' ') + (isStd ? "(object) array(\n" : "\\" + cls + "::__set_state(array(\n");
      for (auto &p : v.obj->props) {
        o += std::string(level*2 + 3, ' ') + exportStr(p.name) + " => ";
        Value cv = *p.val;
        if (cv.k == VKArr || cv.k == VKObj) o += varExportStr(cv, level + 1, I, &local, failed);
        else o += varExportStr(cv, level, I, &local, failed);
        o += ",\n";
      }
      o += std::string(level*2, ' ') + (isStd ? ")" : "))");
      return o;
    }
  }
  return "NULL";
}

// ---------- serialize ----------
struct SerCtx {
  std::unordered_map<const void*, int> reg;   // value identity -> index
  std::unordered_map<const void*, int> regCell; // cell identity -> index
  int idx = 0;
};

static void serValue(std::string &o, const Value &v, Interp *I, SerCtx &ctx, bool viaRef, const void *refTarget, int level);

static void serScalar(std::string &o, const Value &v, Interp *I, SerCtx &ctx) {
  switch (v.k) {
    case VKNull: o += "N;"; break;
    case VKBool: o += v.b ? "b:1;" : "b:0;"; break;
    case VKInt: o += "i:" + intToStr(v.i) + ";"; break;
    case VKFloat: o += "d:" + varDumpFloat(v.d) + ";"; break;
    case VKStr: o += "s:" + std::to_string(v.s.size()) + ":\"" + v.s + "\";"; break;
    default: o += "N;"; break;
  }
}

static void serValue(std::string &o, const Value &v, Interp *I, SerCtx &ctx, bool viaRef, const void *refTarget, int level) {
  if (viaRef && refTarget) {
    auto it = ctx.regCell.find(refTarget);
    if (it != ctx.regCell.end()) {
      o += (v.k == VKObj ? "r:" : "R:") + std::to_string(it->second) + ";";
      return;
    }
  } else {
    const void *id = identOf(v);
    if (id && ctx.reg.find(id) != ctx.reg.end()) {
      o += (v.k == VKObj ? "r:" : "R:") + std::to_string(ctx.reg[id]) + ";";
      return;
    }
  }
  ctx.idx++;
  if (viaRef && refTarget) ctx.regCell[refTarget] = ctx.idx;
  const void *id = identOf(v);
  if (id) ctx.reg[id] = ctx.idx;
  if (v.k == VKArr) {
    o += "a:" + std::to_string(v.arr->e.size()) + ":{";
    for (auto &en : v.arr->e) {
      // key
      Value k = en.key;
      if (k.k == VKInt) o += "i:" + intToStr(k.i) + ";";
      else o += "s:" + std::to_string(k.s.size()) + ":\"" + k.s + "\";";
      serValue(o, *en.val, I, ctx, en.val.use_count() > 1, en.val.get(), level + 1);
    }
    o += "}";
    return;
  }
  if (v.k == VKObj) {
    std::string cls = v.obj ? v.obj->clsName : std::string("stdClass");
    o += "O:" + std::to_string(cls.size()) + ":\"" + cls + "\":" + std::to_string(v.obj->props.size()) + ":{";
    for (auto &p : v.obj->props) {
      o += "s:" + std::to_string(p.name.size()) + ":\"" + p.name + "\";";
      serValue(o, *p.val, I, ctx, p.val.use_count() > 1, p.val.get(), level + 1);
    }
    o += "}";
    return;
  }
  serScalar(o, v, I, ctx);
}

std::string serializeStr(const Value &v, Interp *I) {
  SerCtx ctx;
  std::string o;
  serValue(o, v, I, ctx, false, nullptr, 0);
  return o;
}
