std::string Interp::classNameOf(const Ref &obj) {
  if (!obj || obj->k != VKObj) return "";
  return obj->obj ? obj->obj->clsName : std::string("");
}

std::shared_ptr<ClassDef> Interp::findClass(const std::string &name) {
  auto it = classes.find(lc(name));
  if (it != classes.end()) return it->second;
  return ensureBuiltinClass(name);
}

bool Interp::classIsA(const std::shared_ptr<ClassDef> &c, const std::shared_ptr<ClassDef> &base) {
  std::shared_ptr<ClassDef> p = c;
  while (p) {
    if (p == base) return true;
    for (auto &i : p->interfaces) if (i == base) return true;
    for (auto &t : p->traits) if (t == base) return true;
    p = p->parent;
  }
  return false;
}

bool Interp::objInstanceOf(const Ref &obj, const std::shared_ptr<ClassDef> &c) {
  if (!obj || obj->k != VKObj) return false;
  auto oc = obj->obj->cls;
  if (oc && classIsA(oc, c)) return true;
  if (lc(obj->obj->clsName) == lc(c->name)) return true;
  return false;
}

bool Interp::objInstanceOfName(const Ref &obj, const std::string &name) {
  if (!obj || obj->k != VKObj) return false;
  if (lc(obj->obj->clsName) == lc(name)) return true;
  auto c = findClass(name);
  if (c && obj->obj->cls && classIsA(obj->obj->cls, c)) return true;
  if (c) return objInstanceOf(obj, c);
  return false;
}

