  while (p) {
    auto it = p->pidx.find(name);
    if (it != p->pidx.end()) {
      if (owner) *owner = p;
      if (vis) *vis = p->props[it->second].vis == VIS_PRIVATE ? "private" : p->props[it->second].vis == VIS_PROTECTED ? "protected" : "public";
      return true;
    }
    p = p->parent;
  }
  return false;
}

