    if (it != o->pidx.end()) return o->props[it->second].val;
  }
  if (o->kind == 1) {
    // closure internal props
  }
  // __get
  std::shared_ptr<ClassDef> owner;
  auto m = c ? findMethod(c, "__get", &owner) : nullptr;
  if (m) {
    Ref objv2 = std::make_shared<Value>();
    objv2->k = VKObj; objv2->obj = o;
    std::vector<Arg> args;
    Arg a; a.cell = std::make_shared<Value>(name);
    args.push_back(a);
    Value r = runFuncDef(m, objv2, args, line, c->name + "::__get", false);
    return std::make_shared<Value>(std::move(r));
  }
  // dynamic property
  if (forWrite) {
    if (c) {
      logError(E_DEPRECATED, "Creation of dynamic property " + c->name + "::$" + name + " is deprecated", line);
    }
    Ref nv = std::make_shared<Value>();
    o->setProp(name, nv);
    return nv;
  }
  std::string msg = "Undefined property: " + c->name + "::$" + name;
  logError(E_WARNING, msg, line);
  Ref nv = std::make_shared<Value>();
  o->setProp(name, nv);
  return nv;
}

Value Interp::getPropVal(const Ref &objv, const std::string &name, int line, bool forRead) {
  Ref c = getPropCell(objv, name, line, false);
  if (!c) return Value();
  return *c;
}

Value Interp::staticPropGet(const std::shared_ptr<ClassDef> &c, const std::string &name, int line) {
  auto &m = classStaticProps[lc(c->name)];
  auto it = m.find(name);
  if (it != m.end()) return *it->second;
  std::string msg = "Undefined class constant or static variable " + c->name + "::$" + name;
  fatal("Error", msg, line);
  return Value();
}

void Interp::staticPropSet(const std::shared_ptr<ClassDef> &c, const std::string &name, const Value &v, int line) {
  auto &m = classStaticProps[lc(c->name)];
  auto it = m.find(name);
  if (it != m.end()) { storeVal(it->second, sepVal(v)); return; }
  m[name] = std::make_shared<Value>(sepVal(v));
}

// ---------- array access ----------
static Ref getArrCellAt(Interp *I, Ref *baseCell, const Value &keyIn, int line, bool forWrite) {
  if (!baseCell || !*baseCell) {
    if (!forWrite) {
      if (I) I->logError(E_WARNING, "Trying to access array offset on value of type null", line);
      return nullptr;
    }
    return nullptr;
  }
  if ((*baseCell)->k != VKArr) {
    std::string t = debugTypeStr(**baseCell);
    if (!forWrite) {
      if (I) I->logError(E_WARNING, "Trying to access array offset on value of type " + t, line);
      return nullptr;
    }
    I->fatal("TypeError", "Cannot use a scalar value as an array", line);
    return nullptr;
  }
  bool depr = false;
  Value key = normalizeKey(keyIn, I, line, &depr);
  auto &arr = (*baseCell)->arr;
  Ref c = arr->get(key);
  if (c) return c;
  if (!forWrite) {
    if (I) {
      if (key.k == VKInt) {
        char b[64];
        snprintf(b, sizeof b, "Undefined array key %lld", (long long)key.i);
