      } else {
        I->logError(E_WARNING, "Undefined array key \"" + key.s + "\"", line);
      }
    }
    return nullptr;
  }
  // create
  Ref nv = std::make_shared<Value>();
  arr->set(key, nv);
  return nv;
}
