std::shared_ptr<ClassDef> Interp::resolveClassRef(Node *n) {
  if (!n) return nullptr;
  switch (n->op) {
    case N_NAME: {
      std::string nm = n->name;
      if (lc(nm) == "self" && !stack.empty() && stack.back().clsCtx) return stack.back().clsCtx;
      if (lc(nm) == "static" && !stack.empty() && stack.back().clsCtx) return stack.back().clsCtx;
      if (lc(nm) == "parent") {
        if (stack.back().clsCtx && stack.back().clsCtx->parent) return stack.back().clsCtx->parent;
      }
      return findClass(nm);
    }
    case N_SELF: return stack.empty() ? nullptr : stack.back().clsCtx;
    case N_PARENT: return (!stack.empty() && stack.back().clsCtx) ? stack.back().clsCtx->parent : nullptr;
    case N_STATIC: return stack.empty() ? nullptr : stack.back().clsCtx;
    case N_DYNAMICNAME: {
      Value nm = evalExpr(n->kids[0]);
      return findClass(toStr(nm, this));
    }
    case N_NSNAME: return findClass(n->name);
  }
  return nullptr;
}

// ---------- array element read ----------
Value Interp::indexRead(const Ref &baseV, const Value &keyIn, int line, bool isStrOffset) {
  if (!baseV) return Value();
  if (baseV->k == VKStr) {
    bool depr = false;
    Value key = normalizeKey(keyIn, this, line, &depr);
    int64_t i = toInt(key);
    size_t len = baseV->s.size();
    if (i < 0) i += (int64_t)len;
    if (i < 0 || (size_t)i >= len) {
      logError(E_WARNING, "Uninitialized string offset " + intToStr(toInt(key)), line);
      return Value(std::string(""));
    }
    return Value(std::string(1, baseV->s[(size_t)i]));
  }
  if (baseV->k != VKArr) {
    logError(E_WARNING, "Trying to access array offset on value of type " + debugTypeStr(*baseV), line);
    return Value();
  }
  bool depr = false;
  Value key = normalizeKey(keyIn, this, line, &depr);
  Ref c = baseV->arr->get(key);
  if (!c) {
    if (key.k == VKInt) logError(E_WARNING, "Undefined array key " + intToStr(key.i), line);
    else logError(E_WARNING, "Undefined array key \"" + key.s + "\"", line);
    return Value();
  }
  return sepVal(*c);
}
