// ---------- numeric operations ----------
Value numOperand(const Value &v, Interp *I, int line, const char *op, const char *other) {
  switch (v.k) {
    case VKInt: case VKFloat: return v;
    case VKBool: return Value((int64_t)(v.b ? 1 : 0));
    case VKNull: return Value((int64_t)0);
    case VKStr: {
      int64_t iv; double dv; bool isf;
      strToNum(v.s, &isf, &iv, &dv);
      int64_t iv2; double dv2;
      bool num = isNumericStr(v.s, &iv2, &dv2);
      bool leading = false;
      if (!num && !v.s.empty()) {
        size_t i = 0;
        while (i < v.s.size() && isspace((unsigned char)v.s[i])) i++;
        if (i < v.s.size() && (v.s[i]=='+'||v.s[i]=='-')) i++;
        if (i < v.s.size() && isdigit((unsigned char)v.s[i])) leading = true;
      }
      if (!num && !leading) {
        if (I) I->logError(E_WARNING, "A non-numeric value encountered", line);
        if (I) I->fatal("TypeError", std::string("Unsupported operand types: string ") + op + " " + other, line);
        return Value((int64_t)0);
      }
      return isf ? Value(dv) : Value(iv);
    }
    case VKArr:
      if (I) I->fatal("TypeError", std::string("Unsupported operand types: array ") + op + " " + other, line);
      return Value();
    case VKObj:
      if (I) I->fatal("TypeError", std::string("Unsupported operand types: object ") + op + " " + other, line);
      return Value();
    case VKRes: return Value((int64_t)(v.res ? v.res->id : 0));
  }
  return Value((int64_t)0);
}

static std::string opSym(int op) {
  switch (op) {
    case N_ADD: return "+";
    case N_SUB: return "-";
    case N_MUL: return "*";
    case N_DIV: return "/";
    case N_MOD: return "%";
    case N_POW: return "**";
    case N_CONCAT: return ".";
  }
  return "+";
}

static bool isAddLike(int op) { return op == N_ADD || op == N_SUB || op == N_MUL || op == N_DIV || op == N_MOD || op == N_POW; }

// array union for +
static Value arrayUnion(const Value &a, const Value &b, Interp *I, int line) {
  Value r = I->arrayValue();
  for (auto &en : a.arr->e) r.arr->set(en.key, en.val);
  for (auto &en : b.arr->e) {
    if (!r.arr->has(en.key)) r.arr->set(en.key, en.val);
  }
  r.arr->next = a.arr->next > b.arr->next ? a.arr->next : b.arr->next;
  return sepVal(r);
}

Value Interp::arith(int op, const Value &lv, const Value &rv, int line) {
  // array + array
  if (op == N_ADD && lv.k == VKArr && rv.k == VKArr) return arrayUnion(lv, rv, this, line);
  if (isAddLike(op) && (lv.k == VKArr || rv.k == VKArr) && !(lv.k == VKArr && rv.k == VKArr)) {
    const Value &other = lv.k == VKArr ? rv : lv;
    if (other.k == VKStr) {
      logError(E_WARNING, "A non-numeric value encountered", line);
      fatal("TypeError", "Unsupported operand types: array " + opSym(op) + " string", line);
    }
    fatal("TypeError", "Unsupported operand types: " + std::string(lv.k == VKArr ? "array" : debugTypeStr(lv)) + " " + opSym(op) + " " + (rv.k == VKArr ? "array" : debugTypeStr(rv)), line);
  }
  Value a = numOperand(lv, this, line, opSym(op).c_str(), debugTypeStr(rv).c_str());
  Value b = numOperand(rv, this, line, opSym(op).c_str(), debugTypeStr(lv).c_str());
  bool anyFloat = (a.k == VKFloat || b.k == VKFloat);
  switch (op) {
    case N_ADD: case N_SUB: case N_MUL: {
      if (anyFloat) {
        double x = toFloat(a), y = toFloat(b);
        return Value(op == N_ADD ? x + y : op == N_SUB ? x - y : x * y);
      }
      int64_t x = toInt(a), y = toInt(b);
      int64_t r;
      bool overflow = false;
      if (__builtin_add_overflow(x, y, &r)) overflow = true;
      if (op == N_SUB && __builtin_sub_overflow(x, y, &r)) overflow = true;
      if (op == N_MUL && __builtin_mul_overflow(x, y, &r)) overflow = true;
      if (overflow) return Value((double)x + (op == N_ADD ? 1 : op == N_SUB ? -1 : 0) * 0 + ((double)x) * (op == N_MUL ? 1 : 1));
      return Value(r);
    }
    case N_DIV: {
      if (anyFloat) {
        double x = toFloat(a), y = toFloat(b);
        if (y == 0) fatal("DivisionByZeroError", "Division by zero", line);
        return Value(x / y);
      }
      int64_t x = toInt(a), y = toInt(b);
      if (y == 0) fatal("DivisionByZeroError", "Division by zero", line);
      if (y == -1 && x == INT64_MIN) return Value((double)x / (double)y);
      if (x % y == 0) return Value(x / y);
      return Value((double)x / (double)y);
    }
    case N_MOD: {
      if (anyFloat) {
        if (a.k == VKFloat) logError(E_DEPRECATED, "Implicit conversion from float " + fmtFloat(toFloat(a), precision) + " to int loses precision", line);
        if (b.k == VKFloat) logError(E_DEPRECATED, "Implicit conversion from float " + fmtFloat(toFloat(b), precision) + " to int loses precision", line);
      }
      int64_t x = toInt(a), y = toInt(b);
      if (y == 0) fatal("DivisionByZeroError", "Modulo by zero", line);
      if (y == -1) return Value((int64_t)0);
      return Value(x % y);
    }
    case N_POW: {
      if (anyFloat) {
        double x = toFloat(a), y = toFloat(b);
        if (x == 0 && y < 0) { fatal("DivisionByZeroError", "Zero raised to a negative value", line); }
        return Value(std::pow(x, y));
      }
      int64_t x = toInt(a), y = toInt(b);
      if (y < 0) {
        double r = std::pow((double)x, (double)y);
        return Value(r);
      }
