      int64_t r = 1;
      bool overflow = false;
      int64_t base = x;
      int64_t e = y;
      while (e > 0) {
        if (e & 1) { if (__builtin_mul_overflow(r, base, &r)) { overflow = true; break; } }
        e >>= 1;
        if (e) { if (__builtin_mul_overflow(base, base, &base)) { overflow = true; break; } }
      }
      if (overflow) return Value(std::pow((double)x, (double)y));
      return Value(r);
    }
  }
  return Value();
}

