  bool na = false, nb = false;
  std::string sa = toStr(a, this, &na);
  if (na) logError(E_WARNING, "unexpected NAN value was coerced to string", line);
  std::string sb = toStr(b, this, &nb);
  if (nb) logError(E_WARNING, "unexpected NAN value was coerced to string", line);
  return Value(sa + sb);
}
