// ---------- increment / decrement ----------
Value Interp::incdec(Node *n, bool inc, bool post) {
  Ref cell = evalRef(n->kids[0], true);
  if (!cell) return Value();
  Value old = *cell;
  Value nv;
  switch (old.k) {
    case VKNull:
      if (inc) nv = Value((int64_t)1); else nv = Value((int64_t)0);
      break;
    case VKInt: nv = Value(old.i + (inc ? 1 : -1)); break;
    case VKFloat: nv = Value(old.d + (inc ? 1 : -1)); break;
    case VKStr: {
      if (!inc) { nv = old; break; }
      // perl-style increment
      const std::string &s = old.s;
      int64_t iv; double dv;
      if (isNumericStr(s, &iv, &dv)) {
        if (s.find('.') != std::string::npos || s.find('e') != std::string::npos || s.find('E') != std::string::npos) {
          nv = Value(dv + 1);
        } else {
          // overflow to float
          if (iv == INT64_MAX) nv = Value((double)iv + 1);
          else nv = Value(iv + 1);
        }
        break;
      }
      std::string r = s;
      bool done = false;
      for (long i = (long)r.size() - 1; i >= 0 && !done; i--) {
        char c = r[i];
        if (c == 'z') r[i] = 'a';
        else if (c == 'Z') r[i] = 'A';
        else if (c == '9') r[i] = '0';
        else if ((c >= 'a' && c < 'z') || (c >= 'A' && c < 'Z') || (c >= '0' && c < '9')) { r[i] = c + 1; done = true; }
        else break;
      }
      if (!done) {
        // prepend
        char first = 'a';
        for (char c : s) { if (c >= 'A' && c <= 'Z') { first = 'A'; break; } if (c >= '0' && c <= '9') { first = '1'; break; } }
        r = std::string(1, first) + r;
      }
      nv = Value(r);
      break;
    }
    case VKBool: nv = old; break;
    case VKArr:
      fatal("TypeError", "Cannot increment/decrement an array", n->line);
      break;
    case VKObj:
      fatal("TypeError", "Cannot increment/decrement an object", n->line);
      break;
    case VKRes: nv = old; break;
  }
  if (nv.k == VKArr || nv.k == VKObj) nv = old;
  storeVal(cell, std::move(nv));
  return post ? old : *cell;
}

// ---------- assignment ----------
Value Interp::doAssign(Node *target, const Value &val, int line) {
  if (target->op == N_LIST_EXPR || target->op == N_ARRAY) {
    return destructure(target, val);
  }
  if (target->op == N_REF) return doAssign(target->kids[0], val, line);
  Ref cell = evalRef(target, true);
  if (!cell) return Value();
  Value v = sepVal(val);
  storeVal(cell, std::move(v));
  Value r = sepVal(val);
  return r;
}

Value Interp::destructure(Node *list, const Value &val, int line) {
  Value arr = val;
  if (arr.k != VKArr) {
    if (arr.k == VKNull) {
      logError(E_WARNING, "Cannot unpack null into variables", line);
    } else {
      logError(E_WARNING, "Cannot unpack non-array value of type " + debugTypeStr(arr) + " into variables", line);
    }
    return val;
  }
  size_t idx = 0;
  for (Node *item : list->kids) {
    if (!item) continue;
    if (item->op == N_NOP) { idx++; continue; }
    if (item->op == N_SPREAD) {
      Value rest = arrayValue();
      Ref cell = evalRef(item->kids[0], true);
      for (size_t i = idx; i < arr.arr->e.size(); i++) {
        rest.arr->set(arr.arr->e[i].key, arr.arr->e[i].val);
      }
      if (cell) storeVal(cell, std::move(sepVal(rest)));
      idx = arr.arr->e.size();
      continue;
    }
    Value key;
    Node *tgt = item;
    if (item->op == N_KEYVAL) { key = evalExpr(item->kids[0]); tgt = item->kids[1]; }
    else key = Value((int64_t)(int64_t)idx);
    Ref c = arr.arr->get(normalizeKey(key, this, line));
    Value v = c ? *c : Value();
    if (!c && key.k == VKInt) logError(E_WARNING, "Undefined array key " + intToStr(key.i), line);
    else if (!c) logError(E_WARNING, "Undefined array key \"" + key.s + "\"", line);
    if (tgt) doAssign(tgt, v, line);
    idx++;
  }
  return val;
}

Value Interp::compoundAssign(int op, Node *target, const Value &rv, int line) {
  Ref cell = evalRef(target, true);
  if (!cell) return Value();
  Value lv = *cell;
  Value res;
  switch (op) {
    case N_ASSIGN_ADD: res = arith(N_ADD, lv, rv, line); break;
    case N_ASSIGN_SUB: res = arith(N_SUB, lv, rv, line); break;
    case N_ASSIGN_MUL: res = arith(N_MUL, lv, rv, line); break;
    case N_ASSIGN_DIV: res = arith(N_DIV, lv, rv, line); break;
    case N_ASSIGN_MOD: res = arith(N_MOD, lv, rv, line); break;
    case N_ASSIGN_POW: res = arith(N_POW, lv, rv, line); break;
    case N_ASSIGN_CONCAT: res = concat(lv, rv, line); break;
    case N_ASSIGN_SHL: res = Value(toInt(lv) << (toInt(rv) & 63)); break;
    case N_ASSIGN_SHR: res = Value(toInt(lv) >> (toInt(rv) & 63)); break;
    case N_ASSIGN_BAND: res = Value(toInt(lv) & toInt(rv)); break;
    case N_ASSIGN_BOR: res = Value(toInt(lv) | toInt(rv)); break;
    case N_ASSIGN_BXOR: res = Value(toInt(lv) ^ toInt(rv)); break;
    case N_ASSIGN_CO: {
      if (lv.k == VKNull) res = rv; else res = lv;
      break;
    }
