Value Interp::destructure(Node *list, const Value &val, int line) {
  Value arr = val;
  if (arr.k != VKArr) {
    if (arr.k == VKNull) {
      logError(E_WARNING, "Cannot unpack null into variables", line);
    } else {
      logError(E_WARNING, "Cannot unpack non-array value of type " + debugTypeStr(arr) + " into variables", line);
    }
    return val;
  }
  size_t idx = 0;
  for (Node *item : list->kids) {
    if (!item) continue;
    if (item->op == N_NOP) { idx++; continue; }
    if (item->op == N_SPREAD) {
      Value rest = arrayValue();
      Ref cell = evalRef(item->kids[0], true);
      for (size_t i = idx; i < arr.arr->e.size(); i++) {
        rest.arr->set(arr.arr->e[i].key, arr.arr->e[i].val);
      }
      if (cell) storeVal(cell, std::move(sepVal(rest)));
      idx = arr.arr->e.size();
      continue;
    }
    Value key;
    Node *tgt = item;
    if (item->op == N_KEYVAL) { key = evalExpr(item->kids[0]); tgt = item->kids[1]; }
    else key = Value((int64_t)(int64_t)idx);
    Ref c = arr.arr->get(normalizeKey(key, this, line));
    Value v = c ? *c : Value();
    if (!c && key.k == VKInt) logError(E_WARNING, "Undefined array key " + intToStr(key.i), line);
    else if (!c) logError(E_WARNING, "Undefined array key \"" + key.s + "\"", line);
    if (tgt) doAssign(tgt, v, line);
    idx++;
  }
  return val;
}

Value Interp::compoundAssign(int op, Node *target, const Value &rv, int line) {
  Ref cell = evalRef(target, true);
  if (!cell) return Value();
  Value lv = *cell;
  Value res;
  switch (op) {
    case N_ASSIGN_ADD: res = arith(N_ADD, lv, rv, line); break;
    case N_ASSIGN_SUB: res = arith(N_SUB, lv, rv, line); break;
    case N_ASSIGN_MUL: res = arith(N_MUL, lv, rv, line); break;
    case N_ASSIGN_DIV: res = arith(N_DIV, lv, rv, line); break;
    case N_ASSIGN_MOD: res = arith(N_MOD, lv, rv, line); break;
    case N_ASSIGN_POW: res = arith(N_POW, lv, rv, line); break;
    case N_ASSIGN_CONCAT: res = concat(lv, rv, line); break;
    case N_ASSIGN_SHL: res = Value(toInt(lv) << (toInt(rv) & 63)); break;
    case N_ASSIGN_SHR: res = Value(toInt(lv) >> (toInt(rv) & 63)); break;
    case N_ASSIGN_BAND: res = Value(toInt(lv) & toInt(rv)); break;
    case N_ASSIGN_BOR: res = Value(toInt(lv) | toInt(rv)); break;
    case N_ASSIGN_BXOR: res = Value(toInt(lv) ^ toInt(rv)); break;
    case N_ASSIGN_CO: {
      if (lv.k == VKNull) res = rv; else res = lv;
      break;
    }
    default: res = rv; break;
  }
  storeVal(cell, std::move(sepVal(res)));
  return res;
}
