  if (!n) return;
  if (n->op == N_VAR) {
    for (auto &s : out) if (s == n->name) return;
    out.push_back(n->name);
  }
  for (Node *k : n->kids) if (k) collectVarNames(k, out);
  for (auto &p : n->params) if (p.def) collectVarNames(p.def, out);
}
