Value Interp::evalQuiet(Node *n) {
  quiet++;
  Value r;
  try { r = evalExpr(n); } catch (...) { quiet--; throw; }
  quiet--;
  return r;
}

bool Interp::issetExpr(Node *n) {
  if (!n) return false;
  switch (n->op) {
    case N_VAR: {
      Ref c = findVar(n->name);
      return c && c->k != VKNull;
    }
    case N_DYNAMICNAME: {
      Value nm = evalExpr(n->kids[0]);
      Ref c = findVar(toStr(nm, this));
      return c && c->k != VKNull;
    }
    case N_INDEX: {
      Ref base = std::make_shared<Value>(evalQuiet(n->kids[0]));
      if (!base || base->k != VKArr) return false;
      Value key = evalExpr(n->kids[1]);
      Value k = normalizeKey(key, this, n->line);
      Ref c = base->arr->get(k);
      return c && c->k != VKNull;
    }
    case N_PROP: {
      Value objv = evalQuiet(n->kids[0]);
      if (objv.k != VKObj) return false;
      Ref cell = getPropCell(std::make_shared<Value>(std::move(objv)), n->kids[1]->name, n->line, false);
      if (cell) return cell->k != VKNull;
      return false;
    }
    case N_DYNAMICPROP: {
      Value objv = evalQuiet(n->kids[0]->kids[0]);
      if (objv.k != VKObj) return false;
      Value nm = evalExpr(n->kids[1]);
      Ref cell = getPropCell(std::make_shared<Value>(std::move(objv)), toStr(nm, this), n->line, false);
      if (cell) return cell->k != VKNull;
      return false;
    }
    case N_SPROP: {
      std::shared_ptr<ClassDef> c = resolveClassRef(n->kids[0]);
      if (!c) return false;
      auto &m = classStaticProps[lc(c->name)];
      auto it = m.find(n->kids[1]->name);
      return it != m.end() && it->second->k != VKNull;
    }
    case N_REF: return issetExpr(n->kids[0]);
  }
  return false;
}

void Interp::unsetExpr(Node *n) {
  if (!n) return;
  switch (n->op) {
    case N_VAR: {
      if (stack.size() <= 1) globals.erase(n->name);
      else stack.back().vars.erase(n->name);
      break;
    }
    case N_DYNAMICNAME: {
      Value nm = evalExpr(n->kids[0]);
      std::string s = toStr(nm, this);
      if (stack.size() <= 1) globals.erase(s);
      else stack.back().vars.erase(s);
      break;
    }
    case N_INDEX: {
      Ref base;
      if (n->kids[0] && (n->kids[0]->op == N_VAR || n->kids[0]->op == N_INDEX ||
                         n->kids[0]->op == N_PROP || n->kids[0]->op == N_DYNAMICNAME)) {
        base = evalRef(n->kids[0], false);
      } else return;
      if (!base || base->k != VKArr) return;
      Value key = evalExpr(n->kids[1]);
      base->arr->erase(normalizeKey(key, this, n->line));
      break;
    }
    case N_PROP: {
      Value objv = evalExpr(n->kids[0]);
      if (objv.k != VKObj) return;
      objv.obj->pidx.erase(n->kids[1]->name);
      for (size_t i = 0; i < objv.obj->props.size(); i++) {
        if (objv.obj->props[i].name == n->kids[1]->name) { objv.obj->props.erase(objv.obj->props.begin() + i); break; }
      }
      break;
    }
    case N_SPROP: {
      std::shared_ptr<ClassDef> c = resolveClassRef(n->kids[0]);
      if (!c) return;
      classStaticProps[lc(c->name)].erase(n->kids[1]->name);
      break;
    }
    case N_REF: unsetExpr(n->kids[0]); break;
  }
}

Value Interp::cloneObject(const Value &v, int line) {
  auto o = std::make_shared<ObjData>(*v.obj);
  o->handle = ++objCount;
  o->props = v.obj->props;
  o->pidx = v.obj->pidx;
  // deep copy prop cells
  o->props.clear();
  o->pidx.clear();
  for (auto &p : v.obj->props) {
    o->setProp(p.name, std::make_shared<Value>(sepVal(*p.val)));
  }
  Value r; r.k = VKObj; r.obj = o;
  auto m = o->cls ? findMethod(o->cls, "__clone") : nullptr;
  if (m) {
    Ref rv = std::make_shared<Value>(r);
    std::vector<Arg> args;
    try {
      runFuncDef(m, rv, args, line, o->clsName + "::__clone", false);
    } catch (PHPReturn &pr) { }
  }
  return r;
}

std::string matchCaseStr(const Value &v, Interp *I) {
  switch (v.k) {
    case VKNull: return "null";
    case VKBool: return v.b ? "true" : "false";
    case VKInt: return intToStr(v.i);
    case VKFloat: return varDumpFloat(v.d);
    case VKStr: return "\"" + v.s + "\"";
    default: return debugTypeStr(v);
  }
}

Value Interp::classConstGet(const std::shared_ptr<ClassDef> &c, const std::string &name, int line) {
  std::shared_ptr<ClassDef> p = c;
  while (p) {
    auto it = p->consts.find(name);
    if (it != p->consts.end()) return it->second.val;
    // enum case
    if (p->isEnum) {
      auto e = p->enumCases.find(name);
      if (e != p->enumCases.end()) return e->second;
    }
    p = p->parent;
  }
  fatal("Error", "Undefined class constant \"" + c->name + "::" + name + "\"", line);
  return Value();
}

Value Interp::includeFile(const std::string &path, int op, int line) {
  std::string fp = resolvePath(path);
  if (!fileExists(fp)) {
    if (op == N_REQUIRE || op == N_REQUIRE_ONCE) {
      fatal("Error", "Failed opening required '" + path + "'", line);
      return Value();
    }
    logError(E_WARNING, "Failed opening '" + path + "' for inclusion", line);
    return Value(false);
  }
  // read file
  std::ifstream f(fp, std::ios::binary);
  if (!f) return Value(false);
  std::stringstream ss;
  ss << f.rdbuf();
  std::string src = ss.str();
  for (auto &s : includedFiles) if (s == fp) {
    if (op == N_INCLUDE_ONCE || op == N_REQUIRE_ONCE) return Value(true);
    break;
  }
  includedFiles.push_back(fp);
  Program *prog = this->prog;
  Node *root = nullptr;
  std::string err; int errLine = 0;
  if (parseSource(src.c_str(), src.size(), fp, prog, &root, &err, &errLine)) {
    std::string buf = "\nParse error: " + err + " in " + fp + " on line " + std::to_string(errLine) + "\n";
    writeOut(buf);
    exit(255);
  }
  std::string savedFile = curFile;
  curFile = fp;
  int savedScriptDepth = scriptDepth;
  scriptDepth++;
  Value r;
  try {
    r = evalStmt(root);
  } catch (PHPReturn &pr) { r = pr.val; }
  catch (PHPBreak &pb) { }
  catch (PHPGoto &pg) { }
  scriptDepth = savedScriptDepth;
  curFile = savedFile;
  return r;
}
