// ---------- statements ----------
Value Interp::evalStmtList(Node *n) {
  if (!n) return Value();
  for (Node *s : n->kids) {
    if (!s) continue;
    if (s->op == N_LABEL) continue;
    evalStmt(s);
  }
  return Value();
}

Value Interp::evalStmt(Node *n) {
  if (!n) return Value();
  switch (n->op) {
    case N_STMTLIST: {
      // handle goto labels: find the label and execute from there
      if (g_labelTarget) {
        std::string lbl = g_labelTarget;
        g_labelTarget = nullptr;
        size_t i = 0;
        for (; i < n->kids.size(); i++) {
          Node *k = n->kids[i];
          if (k && k->op == N_LABEL && k->name == lbl) break;
        }
        if (i >= n->kids.size()) {
          fatal("Error", "Cannot jump to undefined label " + lbl + " in " + (stack.empty() ? curFile : stack.back().file), n->line);
        }
        for (; i < n->kids.size(); i++) {
          Node *k = n->kids[i];
          if (!k) continue;
          evalStmt(k);
        }
        return Value();
      }
      for (Node *s : n->kids) {
        if (!s) continue;
        evalStmt(s);
      }
      return Value();
    }
    case N_BLOCK: return evalStmtList(n->kids[0]);
    case N_NOP: return Value();
    case N_EXPR_STMT: {
      if (!n->kids[0]) return Value();
      return evalExpr(n->kids[0]);
    }
    case N_ECHO: {
      for (Node *k : n->kids) {
        if (!k) continue;
        Value v = evalExpr(k);
        echoOut(v);
      }
      return Value();
    }
    case N_PRINT: {
      Value v = evalExpr(n->kids[0]);
      echoOut(v);
      return Value((int64_t)1);
    }
    case N_IF: {
      Value c = evalExpr(n->kids[0]);
      if (toBool(c)) { evalStmt(n->kids[1]); return Value(); }
      for (size_t i = 2; i < n->kids.size(); i++) {
        Node *e = n->kids[i];
        if (e->op == N_IF) {
          Value c2 = evalExpr(e->kids[0]);
          if (toBool(c2)) { evalStmt(e->kids[1]); return Value(); }
          for (size_t j = 2; j < e->kids.size(); j++) { evalStmt(e->kids[j]); return Value(); }
        } else {
          evalStmt(e);
          return Value();
        }
      }
      return Value();
    }
    case N_WHILE: {
      for (;;) {
        if (!toBool(evalExpr(n->kids[0]))) break;
        try { evalStmt(n->kids[1]); }
        catch (PHPBreak &pb) {
          if (pb.isContinue) { if (pb.levels > 1) { pb.levels--; throw; } }
          else { if (pb.levels > 1) { pb.levels--; throw; } break; }
        }
      }
      return Value();
    }
    case N_DOWHILE: {
      for (;;) {
        try { evalStmt(n->kids[0]); }
        catch (PHPBreak &pb) {
          if (pb.isContinue) { if (pb.levels > 1) { pb.levels--; throw; } }
          else { if (pb.levels > 1) { pb.levels--; throw; } break; }
        }
        if (!toBool(evalExpr(n->kids[1]))) break;
      }
      return Value();
    }
    case N_FOR: {
      evalStmt(n->kids[0]);
      for (;;) {
        bool go = true;
        if (n->kids[1]->kids.size()) {
          go = false;
          for (Node *c : n->kids[1]->kids) { if (toBool(evalExpr(c))) go = true; }
        }
        if (!go) break;
        try { evalStmt(n->kids[3]); }
        catch (PHPBreak &pb) {
          if (pb.isContinue) { if (pb.levels > 1) { pb.levels--; throw; } }
          else { if (pb.levels > 1) { pb.levels--; throw; } break; }
        }
        evalStmt(n->kids[2]);
      }
      return Value();
    }
    case N_FOREACH: {
      Value arr = evalExpr(n->kids[0]);
      if (arr.k != VKArr) {
        if (arr.k == VKObj) {
          // iterate over object properties
          Node *tgt = n->kids[1];
          Node *valNode = (tgt->op == N_KEYVAL) ? tgt->kids[1] : tgt;
          for (auto &p : arr.obj->props) {
            if (tgt->op == N_KEYVAL) {
              doAssign(tgt->kids[0], Value(p.name), n->line);
              doAssign(tgt->kids[1], sepVal(*p.val), n->line);
            } else doAssign(tgt, sepVal(*p.val), n->line);
          }
          return Value();
        }
        logError(E_WARNING, "foreach() argument must be of type array|object, " + debugTypeStr(arr) + " given", n->line);
        return Value();
      }
      Node *tgt = n->kids[1];
      Node *valNode = tgt;
      bool byRefVal = false, withKey = false;
      if (tgt->op == N_KEYVAL) { withKey = true; valNode = tgt->kids[1]; byRefVal = (tgt->flags & 1) != 0; }
      else byRefVal = (n->flags & 2) != 0;
      std::vector<std::pair<Value, Ref>> items;
      for (auto &en : arr.arr->e) items.push_back({en.key, en.val});
      for (auto &it : items) {
        if (withKey) {
          Node *keyNode = tgt->kids[0];
          doAssign(keyNode, it.first, n->line);
        }
        if (byRefVal) {
          Ref cell = evalRef(valNode, true);
          if (cell) { *cell = *it.second; }
        } else {
          doAssign(valNode, sepVal(*it.second), n->line);
        }
        try { evalStmt(n->kids[2]); }
        catch (PHPBreak &pb) {
          if (pb.isContinue) { if (pb.levels > 1) { pb.levels--; throw; } }
          else { if (pb.levels > 1) { pb.levels--; throw; } break; }
        }
      }
      return Value();
    }
    case N_SWITCH: {
      Value subj = evalExpr(n->kids[0]);
      Node *cases = n->kids[1];
      size_t start = cases->kids.size();
      bool found = false;
      for (size_t i = 0; i < cases->kids.size(); i++) {
        Node *c = cases->kids[i];
        if (c->op == N_CASE) {
          Value cv = evalExpr(c->kids[0]);
          if (eqValues(subj, cv, this)) { start = i; found = true; break; }
        }
      }
      if (!found) {
        for (size_t i = 0; i < cases->kids.size(); i++) {
          if (cases->kids[i]->op == N_DEFAULTCASE) { start = i; break; }
        }
      }
      for (size_t i = start; i < cases->kids.size(); i++) {
        Node *c = cases->kids[i];
        for (size_t j = c->op == N_CASE || c->op == N_DEFAULTCASE ? 1 : 0; j < c->kids.size(); j++) {
          evalStmt(c->kids[j]);
        }
      }
      return Value();
    }
    case N_TRY: {
      try {
        evalStmt(n->kids[0]);
      } catch (PHPThrow &t) {
        // find matching catch
        bool handled = false;
        for (size_t i = 1; i < n->kids.size(); i++) {
          Node *c = n->kids[i];
          if (c->kids.size() < 3) continue;
          bool match = c->kids[0]->kids.empty();
          for (Node *tn : c->kids[0]->kids) {
            if (t.cls.size() && lc(tn->name) == lc(t.cls)) { match = true; break; }
            // inheritance
            if (objInstanceOfName(t.exc, tn->name)) { match = true; break; }
          }
          if (match) {
            handled = true;
            Ref cell = newVar(c->kids[1]->name);
            storeVal(cell, std::move(t.exc));
            evalStmt(c->kids[2]);
            break;
          }
        }
        if (!handled) throw;
      }
      // finally
      if (n->kids.size() >= 2 && n->kids.back() && n->kids.back()->op != N_STMTLIST) {
        evalStmt(n->kids.back());
      }
      return Value();
    }
    case N_THROW: {
      Value v = evalExpr(n->kids[0]);
      if (v.k != VKObj) fatal("Error", "Throw value must be an object", n->line);
      std::string cls = v.obj ? v.obj->clsName : std::string("");
      std::string msg;
      Ref m = v.obj ? v.obj->getProp("message") : nullptr;
      if (m) msg = toStr(*m, this);
      throwException(v, cls.c_str(), msg, n->line, &stack);
      return Value();
    }
    case N_RETURN: {
      Value v;
      if (!n->kids.empty()) v = evalExpr(n->kids[0]);
      throw PHPReturn(std::move(v));
    }
    case N_BREAK: throw PHPBreak((int)n->i, false);
    case N_CONTINUE: throw PHPBreak((int)n->i, true);
    case N_GOTO: {
      // search enclosing statement list for label
      throw PHPGoto(n->name);
    }
    case N_GLOBAL: {
      for (Node *k : n->kids) {
        if (!k) continue;
        Ref g = declareGlobal(k->name);
        if (stack.size() > 1) stack.back().vars[k->name] = g;
      }
      return Value();
    }
    case N_STATICVARS: {
      if (stack.size() <= 1) return Value();
      Frame &fr = stack.back();
      for (Node *item : n->kids) {
        if (!item || item->op != N_KEYVAL) continue;
        std::string nm = item->kids[0]->name;
        std::string key = (fr.fn ? fr.fn->name : "{main}") + "\x01" + nm;
        auto &st = funcStatics;
        auto it = st.find(key);
        if (it == st.end()) {
          Ref cell = std::make_shared<Value>();
          if (item->kids[1]) *cell = evalExpr(item->kids[1]);
          st[key] = cell;
          it = st.find(key);
        }
        fr.vars[nm] = it->second;
      }
      return Value();
