    case N_CONSTDEF: {
      if (n->flags == 2) return Value(); // handled by class decl
      for (Node *item : n->kids) {
        if (!item) continue;
        Value v = evalExpr(item->kids[1]);
        constSet(item->kids[0]->name, std::move(v), false);
      }
      return Value();
    }
    case N_CLASSDECL: {
      buildClass(n, nullptr, nullptr);
      return Value();
    }
