    case N_PROPDEF: return Value();
    case N_METHODDEF: return Value();
    case N_USE_TRAITS: return Value();
    case N_ENUMCASE: return Value();
    case N_LABEL: return Value();
    case N_NAMEDARG: case N_SPREAD: case N_YIELD: case N_CALLABLE_PAREN: case N_CLONE:
    case N_EXIT:
      return evalExpr(n);
