std::vector<Arg> Interp::collectArgs(Node *call, size_t start) {
  std::vector<Arg> out;
  for (size_t i = start; i < call->kids.size(); i++) {
    Node *a = call->kids[i];
    if (!a) continue;
    Arg x;
    if (a->op == N_NAMEDARG) {
      x.named = true;
      x.name = a->name;
      x.cell = std::make_shared<Value>(evalExpr(a->kids[0]));
    } else if (a->op == N_SPREAD) {
      x.spread = true;
      x.cell = std::make_shared<Value>(evalExpr(a->kids[0]));
    } else if (a->op == N_REF) {
      x.cell = evalRef(a->kids[0], false);
      if (!x.cell) x.cell = std::make_shared<Value>();
    } else {
      x.cell = std::make_shared<Value>(evalExpr(a));
    }
    out.push_back(x);
  }
  return out;
}

Value Interp::callFunc(const Ref &fnv, std::vector<Arg> &args, int line, const std::string &name) {
  if (!fnv) {
    std::string n = name.empty() ? "NULL" : name;
    fatal("Error", "Call to undefined function " + n + "()", line);
  }
  if (fnv->k == VKStr) {
    std::string s = fnv->s;
    // "Class::method"
    size_t p = s.rfind("::");
    if (p != std::string::npos) {
      std::string cls = s.substr(0, p), m = s.substr(p + 2);
      return callStatic(cls, m, args, line);
    }
    return callInternal(s, args, line);
  }
  if (fnv->k == VKArr) {
    if (fnv->arr->e.size() == 2) {
      Value a = *fnv->arr->e[0].val;
      Value b = *fnv->arr->e[1].val;
      if (a.k == VKObj) {
        std::string m = toStr(b, this);
        return callMethod(std::make_shared<Value>(std::move(a)), m, args, line, m);
      }
      if (a.k == VKStr) {
        std::string cls = a.s;
        std::string m = toStr(b, this);
        // instance method on string class? -> static
        return callStatic(cls, m, args, line);
      }
    }
    fatal("Error", "Array is not a valid callable", line);
  }
  if (fnv->k == VKObj) {
    return callObject(fnv, args, line);
  }
  fatal("Error", "Value of type " + debugTypeStr(*fnv) + " is not callable", line);
  return Value();
}

Value Interp::callInternal(const std::string &name, std::vector<Arg> &args, int line) {
  std::string ln = lc(name);
  // user functions shadow builtins
  auto it = funcs.find(ln);
  if (it != funcs.end()) {
    return runFuncDef(it->second, nullptr, args, line, it->second->displayName, false);
  }
  bool found = false;
  Value r = callBuiltin(ln, *this, args, line, &found);
  if (found) return r;
