Value Interp::callObject(const Ref &obj, std::vector<Arg> &args, int line) {
  if (obj->k != VKObj) fatal("Error", "Object is not callable", line);
  auto o = obj->obj;
  if (o->kind == 1) {
    // closure: invoke
    std::shared_ptr<FuncDef> fd = o->closureFn;
    if (!fd) fatal("Error", "Closure is not callable", line);
    return runFuncDef(fd, o->thisObj, args, line, "{closure}", false);
