std::vector<Arg> Interp::collectArgs(Node *call, size_t start) {
  std::vector<Arg> out;
  for (size_t i = start; i < call->kids.size(); i++) {
    Node *a = call->kids[i];
    if (!a) continue;
    Arg x;
    if (a->op == N_NAMEDARG) {
      x.named = true;
      x.name = a->name;
      x.cell = std::make_shared<Value>(evalExpr(a->kids[0]));
    } else if (a->op == N_SPREAD) {
      x.spread = true;
      x.cell = std::make_shared<Value>(evalExpr(a->kids[0]));
    } else if (a->op == N_REF) {
      x.cell = evalRef(a->kids[0], false);
      if (!x.cell) x.cell = std::make_shared<Value>();
    } else {
      x.cell = std::make_shared<Value>(evalExpr(a));
    }
    out.push_back(x);
  }
  return out;
}

Value Interp::callFunc(const Ref &fnv, std::vector<Arg> &args, int line, const std::string &name) {
  if (!fnv) {
    std::string n = name.empty() ? "NULL" : name;
    fatal("Error", "Call to undefined function " + n + "()", line);
  }
  if (fnv->k == VKStr) {
    std::string s = fnv->s;
    // "Class::method"
    size_t p = s.rfind("::");
    if (p != std::string::npos) {
      std::string cls = s.substr(0, p), m = s.substr(p + 2);
      return callStatic(cls, m, args, line);
    }
    return callInternal(s, args, line);
  }
  if (fnv->k == VKArr) {
    if (fnv->arr->e.size() == 2) {
      Value a = *fnv->arr->e[0].val;
      Value b = *fnv->arr->e[1].val;
