// ---------- object creation ----------
Value Interp::newObj(const char *clsName) {
  auto c = findClass(clsName);
  auto o = std::make_shared<ObjData>();
  o->cls = c;
  o->clsName = c ? c->name : std::string(clsName);
  o->handle = ++objCount;
  Value v; v.k = VKObj; v.obj = o;
  // initialize declared properties with defaults
  if (c) {
    std::vector<std::pair<std::string, Ref>> ordered;
    std::vector<std::shared_ptr<ClassDef>> chain;
    auto p = c;
    while (p) { chain.push_back(p); p = p->parent; }
    for (auto it = chain.rbegin(); it != chain.rend(); ++it) {
      for (auto &pd : (*it)->props) {
        if (pd.isStatic) continue;
        Ref cell = std::make_shared<Value>();
        if (pd.def) {
          Frame tmp;
          stack.push_back(std::move(tmp));
          stack.back().vars["__tmp__"] = cell;
          stack.back().file = curFile;
          stack.back().curLine = pd.line;
          stack.back().clsCtx = c;
          if (thisObjValue) stack.back().thisObj = thisObjValue;
          *cell = evalExpr(pd.def);
          stack.pop_back();
        }
        if (!o->pidx.count(pd.name)) o->setProp(pd.name, cell);
      }
    }
  }
  return v;
}

Value Interp::instantiate(const std::shared_ptr<ClassDef> &c, std::vector<Arg> &args, int line) {
  Ref thisObj = std::make_shared<Value>(newObj(c->name.c_str()));
  auto ctor = findMethod(c, "__construct");
  if (ctor) {
    runFuncDef(ctor, thisObj, args, line, c->name + "::__construct", false);
  } else {
    if (!args.empty()) {
      fatal("ArgumentCountError", "Too many arguments to function " + c->name + "::__construct()", line);
    }
  }
  return *thisObj;
}

Value Interp::evalNew(Node *n) {
  int line = n->line;
  Node *argsNode = n->kids[0];
  std::vector<Arg> args;
  if (argsNode) {
    for (size_t i = 0; i < argsNode->kids.size(); i++) {
      Node *a = argsNode->kids[i];
      if (!a) continue;
      Arg x;
      if (a->op == N_NAMEDARG) { x.named = true; x.name = a->name; x.cell = std::make_shared<Value>(evalExpr(a->kids[0])); }
      else if (a->op == N_SPREAD) { x.spread = true; x.cell = std::make_shared<Value>(evalExpr(a->kids[0])); }
      else if (a->op == N_REF) { x.cell = evalRef(a->kids[0], false); }
      else x.cell = std::make_shared<Value>(evalExpr(a));
      args.push_back(x);
    }
  }
  if (n->flags & 16) {
    // anonymous class
    Node *ext = n->kids[1];
    Node *impls = n->kids[2];
    Node *body = n->kids[3];
    std::shared_ptr<ClassDef> parent = ext ? resolveClassRef(ext) : nullptr;
    if (ext && !parent) fatal("Error", "Class not found", line);
    auto c = std::make_shared<ClassDef>();
    c->name = "class@anonymous\x000" ;
    static int anonCount = 0;
    c->name = "class@anonymous" + std::to_string(++anonCount);
    c->lname = lc(c->name);
    c->parent = parent;
    for (Node *k : impls->kids) {
      auto ic = resolveClassRef(k);
      if (ic) { c->interfaces.push_back(ic); c->ifaceNames.push_back(ic->name); }
    }
    buildClassBody(c, body, nullptr);
    classes[lc(c->name)] = c;
    return instantiate(c, args, line);
  }
  Node *clsNode = n->kids[1];
  std::shared_ptr<ClassDef> c = resolveClassRef(clsNode);
  if (!c) {
    std::string cn = clsNode->op == N_NAME ? clsNode->name : (clsNode->op == N_DYNAMICNAME ? "?" : "?");
    fatal("Error", "Class \"" + cn + "\" not found", line);
  }
  if (c->isInterface) fatal("Error", "Cannot instantiate abstract class " + c->name, line);
  return instantiate(c, args, line);
}
