int main(int argc, char **argv) {
  signal(SIGPIPE, SIG_IGN);
  Program prog;
  g_prog = &prog;
  Interp I;
  I.prog = &prog;
  I.curFile = "";
  I.mainFile = "";
  I.precision = 14;

  std::vector<std::string> args;
  std::string code, runCode, beginCode, endCode, fileArg, docroot, serverAddr, iniPath, iniArg;
  bool optR = false, optF = false, optL = false, optI = false, optS = false, optW = false, optHighlight = false;
  bool noIni = false, hideArgs = false, optRepeat = false;
  int repeatCount = 1;
  std::vector<std::string> iniDefs;
  std::string rfName, rcName, reName, rzName, riName;
  bool showIni = false, showIniDiff = false;
  bool interactive = false;
  const char *scriptFile = nullptr;

  int i = 1;
  bool noMoreOpts = false;
  for (; i < argc; i++) {
    const char *a = argv[i];
    if (noMoreOpts || a[0] != '-' || a[1] == 0) { break; }
    if (strcmp(a, "--") == 0) { noMoreOpts = true; i++; break; }
    if (a[1] == '-') {
      std::string opt = a + 2;
      if (opt == "ini") { showIni = true; continue; }
      if (opt == "ini=diff") { showIniDiff = true; continue; }
      if (opt.rfind("rf=", 0) == 0 || opt.rfind("rc=", 0) == 0 || opt.rfind("re=", 0) == 0 ||
          opt.rfind("rz=", 0) == 0 || opt.rfind("ri=", 0) == 0 || opt.rfind("repeat=", 0) == 0) {
        std::string key = opt.substr(0, opt.find('='));
        std::string val = opt.substr(opt.find('=') + 1);
        if (key == "rf") rfName = val;
        else if (key == "rc") rcName = val;
        else if (key == "re") reName = val;
        else if (key == "rz") rzName = val;
        else if (key == "ri") riName = val;
        else if (key == "repeat") { repeatCount = atoi(val.c_str()); optRepeat = true; }
        continue;
      }
      if (i + 1 < argc) {
        std::string nx = argv[i+1];
        if (opt == "rf") { rfName = nx; i++; continue; }
        if (opt == "rc") { rcName = nx; i++; continue; }
        if (opt == "re") { reName = nx; i++; continue; }
        if (opt == "rz") { rzName = nx; i++; continue; }
        if (opt == "ri") { riName = nx; i++; continue; }
        if (opt == "repeat") { repeatCount = atoi(nx.c_str()); optRepeat = true; i++; continue; }
        if (opt == "ini") { showIni = true; continue; }
      }
      continue;
    }
    char c = a[1];
    const char *val = strlen(a) > 2 ? a + 2 : (i + 1 < argc ? argv[++i] : nullptr);
    switch (c) {
      case 'a': interactive = true; break;
      case 'c': iniPath = val ? val : ""; break;
      case 'n': noIni = true; break;
      case 'd': if (val) iniDefs.push_back(val); break;
      case 'e': break;
      case 'f': if (val) { fileArg = val; optF = true; } break;
      case 'h': usage(); return 0;
      case 'i': optI = true; break;
      case 'l': optL = true; break;
      case 'm': showModules(); return 0;
      case 'r': if (val) { code = val; optR = true; } break;
      case 'B': if (val) beginCode = val; break;
      case 'R': if (val) runCode = val; break;
      case 'F': if (val) { fileArg = val; } break;
      case 'E': if (val) endCode = val; break;
      case 'H': hideArgs = true; break;
      case 'S': if (val) { serverAddr = val; optS = true; } break;
      case 't': if (val) docroot = val; break;
      case 's': optHighlight = true; break;
      case 'v': showVersion(); return 0;
      case 'w': optW = true; break;
      default: break;
    }
  }
  for (; i < argc; i++) args.push_back(argv[i]);

  if (interactive) {
    printf("Interactive shell (-a) requires the readline extension.\n");
    return 0;
  }
  if (showIni) {
    printf("Configuration File (php.ini) Path: \"/usr/local/lib\"\n");
    printf("Loaded Configuration File:         (none)\n");
    printf("Scan for additional .ini files in: (none)\n");
    printf("Additional .ini files parsed:      (none)\n");
    return 0;
  }
  if (showIniDiff) {
    printf("Non-default INI settings:\n");
    printf("html_errors: \"1\" -> \"0\"\n");
    printf("implicit_flush: \"0\" -> \"1\"\n");
    printf("max_execution_time: \"30\" -> \"0\"\n");
    return 0;
  }

  // register builtins and native classes
  registerNativeClasses(I);
  I.setupGlobals(args, fileArg.empty() ? (optR ? "Standard input code" : "") : fileArg);

  if (rfName.size() || rcName.size() || reName.size() || rzName.size() || riName.size()) {
    return reflectionInfo(I, rfName, rcName, reName, rzName, riName);
  }

  if (optI) { phpInfoOutput(I, fileArg); return 0; }

  if (optS) {
    // highlight
    std::string src;
    if (!fileArg.empty()) {
      std::ifstream f(fileArg, std::ios::binary);
      std::stringstream ss; ss << f.rdbuf(); src = ss.str();
    } else {
      std::stringstream ss; ss << std::cin.rdbuf(); src = ss.str();
    }
    printf("%s", highlightSource(src).c_str());
    return 0;
  }
  if (optW) {
    std::string src;
    if (!fileArg.empty()) {
      std::ifstream f(fileArg, std::ios::binary);
      std::stringstream ss; ss << f.rdbuf(); src = ss.str();
    } else {
      std::stringstream ss; ss << std::cin.rdbuf(); src = ss.str();
    }
    printf("%s", stripWhitespace(src).c_str());
    return 0;
  }

  if (optL) {
    std::string src;
    const char *fn = fileArg.empty() ? nullptr : fileArg.c_str();
    if (!fn) { /* read from stdin */ 
      std::stringstream ss; ss << std::cin.rdbuf(); src = ss.str();
      fn = "Standard input code";
    } else {
      std::ifstream f(fn, std::ios::binary);
      std::stringstream ss; ss << f.rdbuf(); src = ss.str();
    }
    Node *root = nullptr; std::string err; int errLine = 0;
    if (parseSource(src.c_str(), src.size(), fn, &prog, &root, &err, &errLine)) {
      printf("\nParse error: %s in %s on line %d\n", err.c_str(), fn, errLine);
      printf("Errors parsing %s\n", fn);
      return 255;
    }
    printf("No syntax errors detected in %s\n", fn);
    return 0;
  }

  if (hideArgs) {
    // observed: output suppressed entirely
    return 0;
  }

  // execute
  std::string src;
  const char *fname = nullptr;
  if (optR) {
    src = code;
    fname = "Command line code";
  } else if (optF || !fileArg.empty()) {
    std::ifstream f(fileArg, std::ios::binary);
    if (!f) {
      printf("Could not open input file: %s\n", fileArg.c_str());
      return 1;
    }
    std::stringstream ss; ss << f.rdbuf(); src = ss.str();
    fname = fileArg.c_str();
  } else if (serverAddr.size()) {
    return runWebServer(I, serverAddr, docroot, args);
  } else {
    std::stringstream ss; ss << std::cin.rdbuf(); src = ss.str();
    fname = "Standard input code";
  }

  I.mainFile = fname;
  I.curFile = fname;
  I.scriptName = fname;

  Node *root = nullptr;
  std::string err; int errLine = 0;
  if (parseSource(src.c_str(), src.size(), fname, &prog, &root, &err, &errLine)) {
    printf("\nParse error: %s in %s on line %d\n", err.c_str(), fname, errLine);
    return 255;
  }

  int rc = 0;
  for (int rep = 0; rep < repeatCount; rep++) {
    if (optRepeat) {
      if (rep == 0) printf("Executing for the first time...\n");
      else printf("Finished execution, repeating...\n");
    }
    try {
      if (!beginCode.empty()) {
        Node *bn = nullptr; std::string berr; int bl = 0;
        if (parseSource(beginCode.c_str(), beginCode.size(), "Command line begin code", &prog, &bn, &berr, &bl) == 0) {
          I.runCode(bn);
        } else {
          printf("\nParse error: %s in Command line begin code on line %d\n", berr.c_str(), bl);
          return 255;
        }
      }
      if (runCode.size() || !fileArg.empty()) {
        // read lines from stdin
        std::string line;
        bool beginDone = beginCode.empty();
        Node *rn = nullptr; std::string rerr; int rl = 0;
        Node *fn = nullptr;
        if (runCode.size()) {
          if (parseSource(runCode.c_str(), runCode.size(), "Command line run code", &prog, &rn, &rerr, &rl)) {
            printf("\nParse error: %s in Command line run code on line %d\n", rerr.c_str(), rl);
            return 255;
          }
        } else {
          std::ifstream f(fileArg, std::ios::binary);
          std::stringstream ss2; ss2 << f.rdbuf();
          std::string fsrc = ss2.str();
          if (parseSource(fsrc.c_str(), fsrc.size(), fileArg.c_str(), &prog, &fn, &rerr, &rl)) {
            printf("\nParse error: %s in %s on line %d\n", rerr.c_str(), fileArg.c_str(), rl);
            return 255;
          }
        }
        while (std::getline(std::cin, line)) {
          if (runCode.size()) {
            I.globals["arg"] = std::make_shared<Value>(line);
          }
          I.runCode(runCode.size() ? rn : fn);
        }
        if (!endCode.empty()) {
          Node *en = nullptr; std::string eerr; int el = 0;
          if (parseSource(endCode.c_str(), endCode.size(), "Command line end code", &prog, &en, &eerr, &el) == 0) {
            I.runCode(en);
          }
        }
      } else {
        I.runCode(root);
      }
    } catch (PHPExit &pe) {
      rc = pe.code;
      goto done;
    } catch (PHPThrow &t) {
      printUncaught(I, t);
      rc = 255;
      goto done;
    } catch (std::exception &e) {
      printf("\nFatal error: %s\n", e.what());
      rc = 255;
      goto done;
    }
  }
done:
  I.runShutdown();
  fflush(stdout);
  return rc;
}
EOF
echo ok"}

