static std::string sub_str(const std::string &s, int64_t start, int64_t len, bool hasLen) {
  size_t L = s.size();
  int64_t st = start;
  if (st < 0) st = (int64_t)L + st;
  if (st < 0) st = 0;
  if ((size_t)st > L) return std::string();
  int64_t cnt;
  if (!hasLen) cnt = (int64_t)L - st;
  else if (len < 0) cnt = (int64_t)L + len - st;
  else cnt = len;
  if (cnt < 0) return std::string();
  if ((size_t)st + cnt > L) cnt = (int64_t)L - st;
