#include "b_impl.h"
#include "interp.h"
#include <cmath>

// ---------- JSON ----------
static const int J_HEX_TAG=1, J_HEX_AMP=2, J_HEX_APOS=4, J_HEX_QUOT=8, J_FORCE_OBJECT=16,
  J_NUMERIC_CHECK=32, J_UNESCAPED_SLASHES=64, J_PRETTY_PRINT=128, J_UNESCAPED_UNICODE=256,
  J_PARTIAL_OUTPUT_ON_ERROR=512, J_PRESERVE_ZERO_FRACTION=1024, J_UNESCAPED_LINE_TERMINATORS=2048,
  J_OBJECT_AS_ARRAY=1, J_BIGINT_AS_STRING=2, J_INVALID_UTF8_IGNORE=1048576, J_INVALID_UTF8_SUBSTITUTE=2097152,
  J_THROW_ON_ERROR=4194304;

static std::string jsonEscapeStr(const std::string &s, int flags) {
  std::string out = "\"";
  static const char *hex = "0123456789abcdef";
  for (size_t i = 0; i < s.size(); i++) {
    unsigned char c = s[i];
    switch (c) {
      case '"': out += "\\\""; continue;
      case '\\': out += "\\\\"; continue;
      case '/': out += (flags & J_UNESCAPED_SLASHES) ? "/" : "\\/"; continue;
      case '\b': out += "\\b"; continue;
      case '\f': out += "\\f"; continue;
      case '\n': out += (flags & J_UNESCAPED_LINE_TERMINATORS) ? "\n" : "\\n"; continue;
      case '\r': out += (flags & J_UNESCAPED_LINE_TERMINATORS) ? "\r" : "\\r"; continue;
      case '\t': out += "\\t"; continue;
      default: break;
    }
    if (c < 0x20) {
      out += "\\u00";
      out += hex[(c >> 4) & 15];
      out += hex[c & 15];
      continue;
    }
    if ((flags & J_HEX_TAG) && c == '<') { out += "\\u003C"; continue; }
    if ((flags & J_HEX_TAG) && c == '>') { out += "\\u003E"; continue; }
    if ((flags & J_HEX_AMP) && c == '&') { out += "\\u0026"; continue; }
    if ((flags & J_HEX_APOS) && c == '\'') { out += "\\u0027"; continue; }
    if ((flags & J_HEX_QUOT) && c == '"') { out += "\\u0022"; continue; }
    if (c < 0x80) { out += (char)c; continue; }
    if ((c & 0xE0) == 0xC0) { out += s.substr(i, 2); i += 1; continue; }
    if ((c & 0xF0) == 0xE0) { out += s.substr(i, 3); i += 2; continue; }
    if ((c & 0xF8) == 0xF0) { out += s.substr(i, 4); i += 3; continue; }
    // invalid utf8
    out += "\\ufffd";
  }
  out += "\"";
  return out;
}

static std::string jsonEncode(Interp &I, const Value &v, int flags, int depth, bool *failed);

static std::string jsonIndent(int depth, int flags) {
  if (!(flags & J_PRETTY_PRINT)) return "";
  return std::string((size_t)depth * 4, ' ');
}

static bool isSeqArray(const Value &v) {
  int64_t i = 0;
  for (auto &en : v.arr->e) {
    if (en.key.k != VKInt || en.key.i != i) return false;
    i++;
  }
  return true;
}

static std::string jsonEncode(Interp &I, const Value &v, int flags, int depth, bool *failed) {
  switch (v.k) {
    case VKNull: return "null";
    case VKBool: return v.b ? "true" : "false";
    case VKInt: return intToStr(v.i);
    case VKFloat: {
      if (std::isnan(v.d) || std::isinf(v.d)) {
        if (flags & J_PARTIAL_OUTPUT_ON_ERROR) return "null";
        *failed = true;
        return "";
      }
      if ((flags & J_PRESERVE_ZERO_FRACTION) && v.d == (double)(int64_t)v.d) {
        char b[64];
        snprintf(b, sizeof b, "%d.0", (int)v.d);
        return b;
      }
      return jsonFloat(v.d);
    }
    case VKStr: {
      if (flags & J_NUMERIC_CHECK) {
        int64_t iv; double dv;
        if (isNumericStr(v.s, &iv, &dv)) {
          bool f = v.s.find('.') != std::string::npos || v.s.find('e') != std::string::npos || v.s.find('E') != std::string::npos;
          if (f) return jsonFloat(dv);
          return intToStr(iv);
        }
      }
      return jsonEscapeStr(v.s, flags);
    }
    case VKArr: {
      bool isObj = false;
      if (!(flags & J_FORCE_OBJECT) && depth == 0 && (flags & J_FORCE_OBJECT)) isObj = true;
      if ((flags & J_FORCE_OBJECT)) isObj = true;
      if (!isObj && !isSeqArray(v)) isObj = true;
      if (!isObj) {
        std::string out = "[";
        bool first = true;
        for (auto &en : v.arr->e) {
          if (!first) out += ",";
          if (flags & J_PRETTY_PRINT) out += "\n" + jsonIndent(depth + 1, flags);
          out += jsonEncode(I, *en.val, flags, depth + 1, failed);
          first = false;
        }
        if (!first && (flags & J_PRETTY_PRINT)) out += "\n" + jsonIndent(depth, flags);
        out += "]";
        return out;
      }
      std::string out = "{";
      bool first = true;
      for (auto &en : v.arr->e) {
        if (!first) out += ",";
        if (flags & J_PRETTY_PRINT) out += "\n" + jsonIndent(depth + 1, flags);
        std::string key = en.key.k == VKInt ? intToStr(en.key.i) : en.key.s;
        out += jsonEscapeStr(key, flags) + ":";
        if (flags & J_PRETTY_PRINT) out += " ";
        out += jsonEncode(I, *en.val, flags, depth + 1, failed);
        first = false;
      }
      if (!first && (flags & J_PRETTY_PRINT)) out += "\n" + jsonIndent(depth, flags);
      out += "}";
      return out;
    }
    case VKObj: {
      if (v.obj->kind == 1) return "{}";
      if (v.obj->cls && v.obj->cls->isEnum) {
        // enum
      }
      std::string out = "{";
      bool first = true;
      for (auto &p : v.obj->props) {
        if (!first) out += ",";
        if (flags & J_PRETTY_PRINT) out += "\n" + jsonIndent(depth + 1, flags);
        out += jsonEscapeStr(p.name, flags) + ":";
        if (flags & J_PRETTY_PRINT) out += " ";
        out += jsonEncode(I, *p.val, flags, depth + 1, failed);
        first = false;
      }
      if (!first && (flags & J_PRETTY_PRINT)) out += "\n" + jsonIndent(depth, flags);
      out += "}";
      return out;
    }
    case VKRes: return "null";
  }
  return "null";
}

Value b_json_encode(BArgs &a) {
  a.need(1);
  int flags = (int)a.num(1, 0);
  int depth = (int)a.num(2, 512);
  bool failed = false;
  std::string s = jsonEncode(a.I, *a[0].cell, flags, 0, &failed);
  if (failed) {
    a.I.lastError = std::make_shared<Value>("Inf and NaN not supported in JSON");
    if (flags & J_THROW_ON_ERROR) {
      a.I.fatal("JsonException", "Inf and NaN not supported in JSON", a.line);
    }
    return Value(false);
  }
  a.I.lastError = nullptr;
  return Value(s);
}

struct JsonParser {
  const char *p, *end;
  Interp *I;
  int line;
  std::string errMsg;
  bool fail = false;
  JsonParser(const char *s, size_t n, Interp *I_, int l) : p(s), end(s+n), I(I_), line(l) {}
  void skip() { while (p < end && (*p==' '||*p=='\t'||*p=='\n'||*p=='\r')) p++; }
  bool atEnd() { skip(); return p >= end; }
  [[noreturn]] void err(const std::string &m) { fail = true; errMsg = m; throw std::runtime_error(m); }
  Value parseValue(int depth);
};

Value JsonParser::parseValue(int depth) {
  skip();
  if (p >= end) err("Unexpected end of input");
  if (depth > 512) err("Maximum nesting level of 512 reached");
  char c = *p;
  if (c == '{') {
    p++;
    skip();
    if (p < end && *p == '}') { p++; return I ? I->arrayValue() : Value(); }
    Value r = I->arrayValue();
    for (;;) {
      skip();
      if (p >= end || *p != '"') err("Expecting property name");
      std::string key = parseValue(0).s;
      skip();
      if (p >= end || *p != ':') err("Expecting colon");
      p++;
      Value v = parseValue(depth + 1);
      r.arr->set(Value(key), std::make_shared<Value>(std::move(v)));
      skip();
      if (p < end && *p == ',') { p++; continue; }
      if (p < end && *p == '}') { p++; return r; }
      err("Expecting , or }");
    }
  }
  if (c == '[') {
    p++;
    skip();
    if (p < end && *p == ']') { p++; return I->arrayValue(); }
    Value r = I->arrayValue();
    for (;;) {
      Value v = parseValue(depth + 1);
      r.arr->pushBack(std::make_shared<Value>(std::move(v)));
      skip();
      if (p < end && *p == ',') { p++; continue; }
      if (p < end && *p == ']') { p++; return r; }
      err("Expecting , or ]");
    }
  }
  if (c == '"') {
    p++;
    std::string out;
    for (;;) {
      if (p >= end) err("Unterminated string");
      char ch = *p;
      if (ch == '"') { p++; return Value(out); }
      if (ch == '\\') {
        p++;
        if (p >= end) err("Unterminated string");
        char e = *p++;
        switch (e) {
          case '"': out += '"'; break;
          case '\\': out += '\\'; break;
          case '/': out += '/'; break;
          case 'b': out += '\b'; break;
          case 'f': out += '\f'; break;
          case 'n': out += '\n'; break;
          case 'r': out += '\r'; break;
          case 't': out += '\t'; break;
          case 'u': {
            unsigned v = 0;
            for (int i = 0; i < 4; i++) {
              if (p >= end) err("Unterminated string");
              int hv = hexval(*p++);
              if (hv < 0) err("Invalid unicode escape");
              v = v * 16 + hv;
            }
            if (v >= 0xD800 && v <= 0xDBFF && p + 6 <= end && p[0] == '\\' && p[1] == 'u') {
              unsigned v2 = 0;
              const char *q = p + 2;
              bool ok = true;
              for (int i = 0; i < 4; i++) { int hv = hexval(q[i]); if (hv < 0) { ok = false; break; } v2 = v2*16 + hv; }
              if (ok && v2 >= 0xDC00 && v2 <= 0xDFFF) {
                v = 0x10000 + ((v - 0xD800) << 10) + (v2 - 0xDC00);
                p += 6;
              }
            }
            if (v < 0x80) out += (char)v;
            else if (v < 0x800) { out += (char)(0xC0|(v>>6)); out += (char)(0x80|(v&0x3F)); }
            else if (v < 0x10000) { out += (char)(0xE0|(v>>12)); out += (char)(0x80|((v>>6)&0x3F)); out += (char)(0x80|(v&0x3F)); }
            else { out += (char)(0xF0|(v>>18)); out += (char)(0x80|((v>>12)&0x3F)); out += (char)(0x80|((v>>6)&0x3F)); out += (char)(0x80|(v&0x3F)); }
            break;
          }
          default: err("Invalid escape sequence"); break;
        }
        continue;
      }
      out += ch;
      p++;
    }
  }
  if (c == 't') { if (end - p >= 4 && strncmp(p, "true", 4) == 0) { p += 4; return Value(true); } err("Invalid literal"); }
  if (c == 'f') { if (end - p >= 5 && strncmp(p, "false", 5) == 0) { p += 5; return Value(false); } err("Invalid literal"); }
  if (c == 'n') { if (end - p >= 4 && strncmp(p, "null", 4) == 0) { p += 4; return Value(); } err("Invalid literal"); }
  // number
  {
    const char *start = p;
    if (*p == '-' || *p == '+') p++;
    bool isFloat = false;
    bool gotDigit = false;
    while (p < end && isdigit((unsigned char)*p)) { p++; gotDigit = true; }
    if (p < end && *p == '.') { isFloat = true; p++; while (p < end && isdigit((unsigned char)*p)) p++; }
