    if (!gotDigit) err("Invalid number");
    std::string num(start, p - start);
    if (isFloat) return Value(strtod(num.c_str(), nullptr));
    errno = 0;
    long long v = strtoll(num.c_str(), nullptr, 10);
    return Value((int64_t)v);
  }
}

Value b_json_decode(BArgs &a) {
