// ---------- JSON ----------
static const int J_HEX_TAG=1, J_HEX_AMP=2, J_HEX_APOS=4, J_HEX_QUOT=8, J_FORCE_OBJECT=16,
  J_NUMERIC_CHECK=32, J_UNESCAPED_SLASHES=64, J_PRETTY_PRINT=128, J_UNESCAPED_UNICODE=256,
  J_PARTIAL_OUTPUT_ON_ERROR=512, J_PRESERVE_ZERO_FRACTION=1024, J_UNESCAPED_LINE_TERMINATORS=2048,
  J_OBJECT_AS_ARRAY=1, J_BIGINT_AS_STRING=2, J_INVALID_UTF8_IGNORE=1048576, J_INVALID_UTF8_SUBSTITUTE=2097152,
  J_THROW_ON_ERROR=4194304;

static std::string jsonEscapeStr(const std::string &s, int flags) {
  std::string out = "\"";
  static const char *hex = "0123456789abcdef";
  for (size_t i = 0; i < s.size(); i++) {
    unsigned char c = s[i];
    switch (c) {
      case '"': out += "\\\""; continue;
      case '\\': out += "\\\\"; continue;
      case '/': out += (flags & J_UNESCAPED_SLASHES) ? "/" : "\\/"; continue;
      case '\b': out += "\\b"; continue;
      case '\f': out += "\\f"; continue;
      case '\n': out += (flags & J_UNESCAPED_LINE_TERMINATORS) ? "\n" : "\\n"; continue;
      case '\r': out += (flags & J_UNESCAPED_LINE_TERMINATORS) ? "\r" : "\\r"; continue;
      case '\t': out += "\\t"; continue;
      default: break;
    }
    if (c < 0x20) {
      out += "\\u00";
      out += hex[(c >> 4) & 15];
      out += hex[c & 15];
      continue;
    }
    if ((flags & J_HEX_TAG) && c == '<') { out += "\\u003C"; continue; }
    if ((flags & J_HEX_TAG) && c == '>') { out += "\\u003E"; continue; }
    if ((flags & J_HEX_AMP) && c == '&') { out += "\\u0026"; continue; }
    if ((flags & J_HEX_APOS) && c == '\'') { out += "\\u0027"; continue; }
    if ((flags & J_HEX_QUOT) && c == '"') { out += "\\u0022"; continue; }
    if (c < 0x80) { out += (char)c; continue; }
    if ((c & 0xE0) == 0xC0) { out += s.substr(i, 2); i += 1; continue; }
    if ((c & 0xF0) == 0xE0) { out += s.substr(i, 3); i += 2; continue; }
    if ((c & 0xF8) == 0xF0) { out += s.substr(i, 4); i += 3; continue; }
    // invalid utf8
    out += "\\ufffd";
  }
  out += "\"";
  return out;
}

static std::string jsonEncode(Interp &I, const Value &v, int flags, int depth, bool *failed);

static std::string jsonIndent(int depth, int flags) {
  if (!(flags & J_PRETTY_PRINT)) return "";
  return std::string((size_t)depth * 4, ' ');
}

static bool isSeqArray(const Value &v) {
  int64_t i = 0;
  for (auto &en : v.arr->e) {
    if (en.key.k != VKInt || en.key.i != i) return false;
    i++;
  }
  return true;
}

static std::string jsonEncode(Interp &I, const Value &v, int flags, int depth, bool *failed) {
  switch (v.k) {
    case VKNull: return "null";
    case VKBool: return v.b ? "true" : "false";
    case VKInt: return intToStr(v.i);
    case VKFloat: {
      if (std::isnan(v.d) || std::isinf(v.d)) {
        if (flags & J_PARTIAL_OUTPUT_ON_ERROR) return "null";
        *failed = true;
        return "";
      }
      if ((flags & J_PRESERVE_ZERO_FRACTION) && v.d == (double)(int64_t)v.d) {
        char b[64];
        snprintf(b, sizeof b, "%d.0", (int)v.d);
        return b;
      }
      return jsonFloat(v.d);
    }
    case VKStr: {
      if (flags & J_NUMERIC_CHECK) {
        int64_t iv; double dv;
        if (isNumericStr(v.s, &iv, &dv)) {
          bool f = v.s.find('.') != std::string::npos || v.s.find('e') != std::string::npos || v.s.find('E') != std::string::npos;
          if (f) return jsonFloat(dv);
          return intToStr(iv);
        }
      }
      return jsonEscapeStr(v.s, flags);
    }
    case VKArr: {
      bool isObj = false;
      if (!(flags & J_FORCE_OBJECT) && depth == 0 && (flags & J_FORCE_OBJECT)) isObj = true;
      if ((flags & J_FORCE_OBJECT)) isObj = true;
      if (!isObj && !isSeqArray(v)) isObj = true;
      if (!isObj) {
        std::string out = "[";
        bool first = true;
        for (auto &en : v.arr->e) {
          if (!first) out += ",";
          if (flags & J_PRETTY_PRINT) out += "\n" + jsonIndent(depth + 1, flags);
          out += jsonEncode(I, *en.val, flags, depth + 1, failed);
          first = false;
        }
        if (!first && (flags & J_PRETTY_PRINT)) out += "\n" + jsonIndent(depth, flags);
        out += "]";
        return out;
      }
      std::string out = "{";
      bool first = true;
      for (auto &en : v.arr->e) {
        if (!first) out += ",";
        if (flags & J_PRETTY_PRINT) out += "\n" + jsonIndent(depth + 1, flags);
        std::string key = en.key.k == VKInt ? intToStr(en.key.i) : en.key.s;
        out += jsonEscapeStr(key, flags) + ":";
        if (flags & J_PRETTY_PRINT) out += " ";
        out += jsonEncode(I, *en.val, flags, depth + 1, failed);
        first = false;
      }
      if (!first && (flags & J_PRETTY_PRINT)) out += "\n" + jsonIndent(depth, flags);
      out += "}";
      return out;
    }
    case VKObj: {
      if (v.obj->kind == 1) return "{}";
      if (v.obj->cls && v.obj->cls->isEnum) {
        // enum
      }
      std::string out = "{";
      bool first = true;
      for (auto &p : v.obj->props) {
        if (!first) out += ",";
        if (flags & J_PRETTY_PRINT) out += "\n" + jsonIndent(depth + 1, flags);
        out += jsonEscapeStr(p.name, flags) + ":";
        if (flags & J_PRETTY_PRINT) out += " ";
        out += jsonEncode(I, *p.val, flags, depth + 1, failed);
        first = false;
      }
      if (!first && (flags & J_PRETTY_PRINT)) out += "\n" + jsonIndent(depth, flags);
      out += "}";
      return out;
    }
    case VKRes: return "null";
  }
  return "null";
}

