  while (b < e && isspace((unsigned char)str[b])) b++;
  while (e > b && isspace((unsigned char)str[e-1])) e--;
  str = str.substr(b, e - b);
  if (str.empty()) { if (ok) *ok = false; return 0; }
  if (str == "now") return base;
  // parse relative
  if (str.size() && (str[0] == '+' || str[0] == '-')) {
    int64_t total = 0;
    bool neg = str[0] == '-';
    std::string body = str.substr(1);
    std::vector<std::pair<int64_t,int>> units;
    // simple: parse "Nd" etc
