    // tokenize
    size_t i = 0;
    int64_t sum = 0;
    while (i < body.size()) {
      while (i < body.size() && !isdigit((unsigned char)body[i])) i++;
      if (i >= body.size()) break;
      int64_t n = 0;
      while (i < body.size() && isdigit((unsigned char)body[i])) { n = n*10 + (body[i]-'0'); i++; }
      while (i < body.size() && !isalpha((unsigned char)body[i])) i++;
      std::string unit;
      while (i < body.size() && isalpha((unsigned char)body[i])) { unit += tolower(body[i]); i++; }
      if (unit.size() > 3 && unit.substr(unit.size()-1) == "s") unit = unit.substr(0, unit.size()-1);
      int64_t secs = 0;
      if (unit == "sec" || unit == "second") secs = 1;
      else if (unit == "min" || unit == "minute") secs = 60;
      else if (unit == "hour") secs = 3600;
      else if (unit == "day") secs = 86400;
      else if (unit == "week") secs = 604800;
      else if (unit == "month") secs = 2592000;
      else if (unit == "year") secs = 31536000;
      else { if (ok) *ok = false; return 0; }
      sum += n * secs;
    }
    return base + (neg ? -sum : sum);
  }
  // ISO date "YYYY-MM-DD[ HH[:MM[:SS]]]"
  struct tm tmv;
  memset(&tmv, 0, sizeof tmv);
  const char *p = str.c_str();
  int y, mo, d, h = 0, mi = 0, sec = 0;
  int n = 0;
  if (sscanf(p, "%d-%d-%d%n", &y, &mo, &d, &n) == 3) {
    p += n;
    if (*p == ' ' || *p == 'T') {
      p++;
      if (sscanf(p, "%d:%d:%d", &h, &mi, &sec) >= 1) {
      }
    } else if (*p != 0) {
      // invalid
      if (ok) *ok = false;
      return 0;
    }
    tmv.tm_year = y - 1900; tmv.tm_mon = mo - 1; tmv.tm_mday = d;
    tmv.tm_hour = h; tmv.tm_min = mi; tmv.tm_sec = sec;
    time_t t = timegm(&tmv);
    return (int64_t)t;
  }
  // "MM/DD/YYYY"
  if (sscanf(p, "%d/%d/%d%n", &mo, &d, &y, &n) == 3) {
    tmv.tm_year = y < 100 ? y + (y < 70 ? 2000 : 1900) - 1900 : y - 1900;
    tmv.tm_mon = mo - 1; tmv.tm_mday = d;
    time_t t = timegm(&tmv);
    return (int64_t)t;
  }
  if (ok) *ok = false;
  return 0;
}

