#define PCRE2_CODE_UNIT_WIDTH 8
#include "b_impl.h"
#include "interp.h"
#include <pcre2.h>
#include <cstring>
#include <string>
#include <vector>

struct PcreCtx {
  pcre2_code *code;
  uint32_t options;
  std::string pattern;
};

static PcreCtx compilePattern(Interp &I, const std::string &patIn, int line, uint32_t extraOpts = 0) {
  std::string pat = patIn;
  uint32_t opts = 0;
  std::string body = pat;
  // extract flags from delimiters
  if (pat.size() >= 2) {
    char d = pat[0];
    size_t end = std::string::npos;
    char endc = d;
    if (d == '(') endc = ')';
    else if (d == '{') endc = '}';
    else if (d == '[') endc = ']';
    else if (d == '<') endc = '>';
    for (size_t i = 1; i < pat.size(); i++) {
      if (pat[i] == '\\' && i + 1 < pat.size()) { i++; continue; }
      if (pat[i] == endc) { end = i; break; }
    }
    if (end == std::string::npos) {
      I.fatal("PcreException", "Missing ending delimiter", line);
    }
    body = pat.substr(1, end - 1);
    std::string flags = pat.substr(end + 1);
    for (char f : flags) {
      switch (f) {
        case 'i': opts |= PCRE2_CASELESS; break;
        case 'm': opts |= PCRE2_MULTILINE; break;
        case 's': opts |= PCRE2_DOTALL; break;
        case 'x': opts |= PCRE2_EXTENDED; break;
        case 'u': opts |= PCRE2_UTF; break;
        case 'A': opts |= PCRE2_ANCHORED; break;
        case 'D': opts |= PCRE2_DOLLAR_ENDONLY; break;
        case 'S': break;
        case 'U': opts |= PCRE2_UNGREEDY; break;
        case 'X': opts |= PCRE2_EXTRA_ALT_VERBS; break;
        case 'J': opts |= PCRE2_DUPNAMES; break;
        case 'n': opts |= PCRE2_NO_AUTO_CAPTURE; break;
        default: break;
      }
    }
  }
  opts |= extraOpts;
  int errcode;
  PCRE2_SIZE erroffset;
  pcre2_code *code = pcre2_compile((PCRE2_SPTR)body.c_str(), body.size(), opts, &errcode, &erroffset, nullptr);
  if (!code) {
    PCRE2_UCHAR msg[256];
    pcre2_get_error_message(errcode, msg, sizeof msg);
    I.fatal("PcreException", std::string("Compilation failed: ") + (char*)msg, line);
  }
  PcreCtx c;
  c.code = code;
  c.options = opts;
  c.pattern = pat;
  return c;
}

Value b_preg_match(BArgs &a) {
  a.need(2);
  PcreCtx pc = compilePattern(a.I, a.str(0), a.line);
  std::string subj = a.str(1);
  pcre2_match_data *md = pcre2_match_data_create_from_pattern(pc.code, nullptr);
  int rc = pcre2_match(pc.code, (PCRE2_SPTR)subj.c_str(), subj.size(), 0, 0, md, nullptr);
  int64_t result = 0;
  if (rc >= 0) {
    result = rc;
    if (a.has(2) && a.cell(2)) {
      Value arr = a.I.arrayValue();
      uint32_t count = pcre2_get_ovector_count(md);
      for (uint32_t i = 0; i < count; i++) {
        PCRE2_SIZE *ov = pcre2_get_ovector_pointer(md);
        if (ov[i*2] == PCRE2_UNSET) { arr.arr->pushBack(std::make_shared<Value>(std::string(""))); continue; }
        arr.arr->pushBack(std::make_shared<Value>(subj.substr(ov[i*2], ov[i*2+1] - ov[i*2])));
      }
      storeVal(a.cell(2), sepVal(arr));
    }
  } else if (rc == PCRE2_ERROR_NOMATCH) {
    result = 0;
    if (a.has(2) && a.cell(2)) storeVal(a.cell(2), sepVal(a.I.arrayValue()));
  }
  pcre2_match_data_free(md);
  pcre2_code_free(pc.code);
  if (rc < 0 && rc != PCRE2_ERROR_NOMATCH) {
    a.I.fatal("PcreException", "Match failed", a.line);
  }
  return Value(result);
}

Value b_preg_match_all(BArgs &a) {
  a.need(2);
  PcreCtx pc = compilePattern(a.I, a.str(0), a.line);
  std::string subj = a.str(1);
  int flags = (int)a.num(3, 0);
  pcre2_match_data *md = pcre2_match_data_create_from_pattern(pc.code, nullptr);
  uint32_t count = pcre2_get_ovector_count(md);
  std::vector<std::vector<std::string>> results;
  size_t pos = 0;
  int rc;
  while ((rc = pcre2_match(pc.code, (PCRE2_SPTR)subj.c_str(), subj.size(), pos, 0, md, nullptr)) >= 0) {
    PCRE2_SIZE *ov = pcre2_get_ovector_pointer(md);
    std::vector<std::string> m;
    for (uint32_t i = 0; i < count; i++) {
      if (ov[i*2] == PCRE2_UNSET) m.push_back("");
      else m.push_back(subj.substr(ov[i*2], ov[i*2+1] - ov[i*2]));
    }
    results.push_back(m);
    size_t newpos = ov[1];
    if (newpos == pos) newpos = pos + 1;
    if (newpos > subj.size()) break;
    pos = newpos;
    if (rc == 0) break;
  }
  pcre2_match_data_free(md);
  pcre2_code_free(pc.code);
  if (rc < 0 && rc != PCRE2_ERROR_NOMATCH) a.I.fatal("PcreException", "Match failed", a.line);
  if (a.has(2) && a.cell(2)) {
    if (flags & 1) {
      // PREG_PATTERN_ORDER is the default
      Value arr = a.I.arrayValue();
      for (uint32_t i = 0; i < count; i++) {
        Value sub = a.I.arrayValue();
        for (auto &r : results) sub.arr->pushBack(std::make_shared<Value>(r[i]));
        arr.arr->pushBack(std::make_shared<Value>(sepVal(sub)));
      }
      storeVal(a.cell(2), sepVal(arr));
    } else {
      Value arr = a.I.arrayValue();
      for (auto &r : results) {
        Value sub = a.I.arrayValue();
        for (auto &s : r) sub.arr->pushBack(std::make_shared<Value>(s));
        arr.arr->pushBack(std::make_shared<Value>(sepVal(sub)));
      }
      storeVal(a.cell(2), sepVal(arr));
    }
  }
