  for (size_t i = 0; i < rep.size(); i++) {
    char c = rep[i];
    if (c != '\\' && c != '$') { out += c; continue; }
    if (i + 1 >= rep.size()) { out += c; continue; }
    char n = rep[i+1];
    if (n == '0' || (n >= '1' && n <= '9')) {
      size_t j = i + 1;
      int num = 0;
      while (j < rep.size() && isdigit((unsigned char)rep[j])) { num = num*10 + (rep[j]-'0'); j++; }
      (void)j;
      if (num == 0) out += subj.substr(ov[0], ov[1]-ov[0]);
      else if (num > 0 && (uint32_t)num < pcre2_get_ovector_count(md) && ov[num*2] != PCRE2_UNSET)
