  if (lm == "valid") { *handled = true; if (arr && arr->k == VKArr) return Value(p < arr->arr->e.size()); return Value(false); }
  if (lm == "current") { *handled = true; if (arr && arr->k == VKArr && p < arr->arr->e.size()) return sepVal(*arr->arr->e[p].val); return Value(); }
  if (lm == "key") { *handled = true; if (arr && arr->k == VKArr && p < arr->arr->e.size()) return arr->arr->e[p].key; return Value(); }
  if (lm == "next") { *handled = true; obj->obj->setProp("__pos", std::make_shared<Value>((int64_t)(p + 1))); return Value(); }
  if (lm == "prev") { *handled = true; obj->obj->setProp("__pos", std::make_shared<Value>((int64_t)(p > 0 ? p - 1 : 0))); return Value(); }
