std::shared_ptr<ClassDef> ensureBuiltinClass(const std::string &name) {
  if (!g_interp) return nullptr;
  std::string ln = lc(name);
  auto it = g_interp->classes.find(ln);
  if (it != g_interp->classes.end()) return it->second;
  for (auto &nc : nativeClassList) {
    if (lc(nc.name) == ln) {
      auto c = std::make_shared<ClassDef>();
      c->name = nc.name;
      c->lname = ln;
      c->isInterface = nc.iface;
      if (nc.parent) {
        c->parent = ensureBuiltinClass(nc.parent);
      }
      g_interp->classes[ln] = c;
      return c;
    }
  }
  return nullptr;
}

static bool nativeClassExists(const std::string &name) {
  std::string ln = lc(name);
  for (auto &nc : nativeClassList) if (lc(nc.name) == ln) return true;
  return false;
}

