    Ref newThis;
    std::vector<Arg> a2;
    if (args.size()) newThis = args[0].cell;
    if (args.size() > 1) {
      const Value &arr = *args[1].cell;
      if (arr.k == VKArr) for (auto &en : arr.arr->e) { Arg x; x.cell = en.val; a2.push_back(x); }
