bool nativeHasMethodImpl(const std::shared_ptr<ClassDef> &cls, const std::string &m) {
  if (!cls) return false;
  std::string ln = lc(cls->name);
  auto handle = [&](const std::string &cl) -> bool {
    if (cl == "stdclass") return false;
    if (cl == "closure") {
      static const char *cms[] = {"__invoke","call","apply","getclosure","bindto", nullptr};
      for (auto c = cms; *c; c++) if (*c == m) return true;
      return false;
    }
    if (cl == "spldoublylinkedlist" || cl == "splstack" || cl == "splqueue") {
      static const char *cms[] = {"push","pop","shift","unshift","add","top","bottom","count","isempty","offsetget","offsetset","offsetexists","offsetunset","getiterator","__construct", nullptr};
      for (auto c = cms; *c; c++) if (*c == m) return true;
      return false;
    }
    if (cl == "arrayiterator" || cl == "arrayobject" || cl == "recursivearrayiterator") {
      static const char *cms[] = {"rewind","valid","current","key","next","prev","seek","count","offsetget","offsetset","offsetexists","offsetunset","getarraycopy","__construct","current","toarray", nullptr};
      for (auto c = cms; *c; c++) if (*c == m) return true;
      return false;
    }
    if (cl == "datetime" || cl == "datetimeimmutable" || cl == "datetimeinterface") {
      static const char *cms[] = {"format","gettimestamp","getoffset","gettimezone","getlasterrors","modify","add","sub","settime","setdate","setisodate","settimestamp","settimezone","diff","__wakeup","__tostring","__construct", nullptr};
      for (auto c = cms; *c; c++) if (*c == m) return true;
      return false;
    }
    if (cl == "datetimezone") {
      static const char *cms[] = {"getname","getoffset","gettransitions","getlocation","__tostring","__construct", nullptr};
      for (auto c = cms; *c; c++) if (*c == m) return true;
      return false;
    }
    if (cl == "dateinterval") {
      static const char *cms[] = {"format", nullptr};
      for (auto c = cms; *c; c++) if (*c == m) return true;
      return false;
    }
    if (cl == "reflectionclass" || cl == "reflectionfunction" || cl == "reflectionmethod" ||
        cl == "reflectionobject" || cl == "reflectionproperty" || cl == "reflectionparameter" ||
        cl == "reflectiontype" || cl == "reflectionnamedtype" || cl == "reflectionfunctionabstract" ||
        cl == "reflectionclassconstant" || cl == "reflectionextension" || cl == "reflectionenum" ||
        cl == "reflectionattribute") {
      static const char *cms[] = {"getname","tostring","__tostring","__construct", nullptr};
      for (auto c = cms; *c; c++) if (*c == m) return true;
      return false;
    }
    return false;
  };
  std::shared_ptr<ClassDef> c = cls;
  while (c) {
    if (handle(lc(c->name))) return true;
    if (nativeClassExists(c->name) && nativeHasMethodImpl(c->parent, m)) return true;
    c = c->parent;
  }
  return false;
}

