Value b_version_compare(BArgs &a) {
  a.need(2);
  std::string v1 = a.str(0), v2 = a.str(1);
  // simple numeric compare of first tokens
  auto parse = [](const std::string &s) {
    std::vector<int64_t> parts;
    size_t i = 0;
    while (i < s.size()) {
      int64_t num = 0;
      bool got = false;
      while (i < s.size() && isdigit((unsigned char)s[i])) { num = num*10 + (s[i]-'0'); i++; got = true; }
      if (got) parts.push_back(num);
      else i++;
    }
    return parts;
  };
  auto p1 = parse(v1), p2 = parse(v2);
  int r = 0;
  for (size_t i = 0; i < std::max(p1.size(), p2.size()); i++) {
    int64_t x = i < p1.size() ? p1[i] : 0, y = i < p2.size() ? p2[i] : 0;
    if (x != y) { r = x < y ? -1 : 1; break; }
  }
  std::string op = a.has(2) ? a.str(2) : std::string();
  if (op.empty()) return Value((int64_t)r);
  bool res;
  if (op == "<" || op == "lt") res = r < 0;
  else if (op == "<=" || op == "le") res = r <= 0;
  else if (op == ">" || op == "gt") res = r > 0;
  else if (op == ">=" || op == "ge") res = r >= 0;
  else if (op == "==" || op == "=" || op == "eq") res = r == 0;
  else if (op == "!=" || op == "<>" || op == "ne") res = r != 0;
  else res = r == 0;
  return Value(res);
}
