cat >> /workspace/src/interp.cpp <<'EOF'

void Interp::setupGlobals(const std::vector<std::string> &args, const std::string &scriptName) {
  // argc/argv
  Value argvArr = arrayValue();
  std::string sn = scriptName.empty() ? "Standard input code" : scriptName;
  argvArr.arr->pushBack(std::make_shared<Value>(sn));
  for (auto &a : args) argvArr.arr->pushBack(std::make_shared<Value>(a));
  globals["argv"] = std::make_shared<Value>(sepVal(argvArr));
  globals["argc"] = std::make_shared<Value>((int64_t)(1 + args.size()));
  // $_SERVER
  Value server = arrayValue();
  for (char **e = environ; *e; e++) {
    std::string s(*e);
    size_t p = s.find('=');
    if (p == std::string::npos) continue;
    server.arr->set(Value(s.substr(0, p)), std::make_shared<Value>(s.substr(p + 1)));
  }
  server.arr->set(Value(std::string("PHP_SELF")), std::make_shared<Value>(sn));
  server.arr->set(Value(std::string("SCRIPT_NAME")), std::make_shared<Value>(sn));
  server.arr->set(Value(std::string("SCRIPT_FILENAME")), std::make_shared<Value>(sn));
  server.arr->set(Value(std::string("PATH_TRANSLATED")), std::make_shared<Value>(sn));
  server.arr->set(Value(std::string("DOCUMENT_ROOT")), std::make_shared<Value>(std::string("")));
  struct timeval tv;
  gettimeofday(&tv, nullptr);
  server.arr->set(Value(std::string("REQUEST_TIME_FLOAT")), std::make_shared<Value>((double)tv.tv_sec + tv.tv_usec/1e6));
  server.arr->set(Value(std::string("REQUEST_TIME")), std::make_shared<Value>((int64_t)tv.tv_sec));
  globals["_SERVER"] = std::make_shared<Value>(sepVal(server));
  globals["_GET"] = std::make_shared<Value>(sepVal(arrayValue()));
  globals["_POST"] = std::make_shared<Value>(sepVal(arrayValue()));
  globals["_COOKIE"] = std::make_shared<Value>(sepVal(arrayValue()));
  globals["_FILES"] = std::make_shared<Value>(sepVal(arrayValue()));
  globals["_ENV"] = std::make_shared<Value>(sepVal(server));
  globals["_REQUEST"] = std::make_shared<Value>(sepVal(arrayValue()));
  globals["GLOBALS"] = nullptr; // special handled in findVar
  // remove GLOBALS from globals (handled specially)
  globals.erase("GLOBALS");
}

void Interp::runCode(Node *n) {
  bool pushed = false;
  if (stack.empty()) {
    Frame f;
    f.callName = "{main}";
    f.file = curFile;
    f.line = 1;
    f.curLine = 1;
    stack.push_back(std::move(f));
    pushed = true;
  }
  try {
    evalStmt(n);
  } catch (...) {
    if (pushed && stack.size() == 1) stack.pop_back();
    throw;
  }
  if (pushed && stack.size() == 1) stack.pop_back();
}

void Interp::runShutdown() {
  if (ranShutdown) return;
  ranShutdown = true;
  for (auto it = shutdownFuncs.rbegin(); it != shutdownFuncs.rend(); ++it) {
    std::vector<Arg> args;
    try {
      callFunc(it->first, args, 0, "");
    } catch (...) {
    }
  }
}
