static std::string httpDate() {
  char buf[128];
  time_t t = time(nullptr);
  struct tm g;
  gmtime_r(&t, &g);
  strftime(buf, sizeof buf, "%a, %d %b %Y %H:%M:%S GMT", &g);
  return buf;
}

int runWebServer(Interp &I, const std::string &addrPort, const std::string &docrootIn, const std::vector<std::string> &args) {
  std::string host = "127.0.0.1";
  int port = 8080;
  size_t p = addrPort.rfind(':');
  if (p != std::string::npos) {
    host = addrPort.substr(0, p);
    port = atoi(addrPort.substr(p + 1).c_str());
  }
  std::string docroot = docrootIn.empty() ? "." : docrootIn;
  std::string router = args.empty() ? std::string() : args[0];
  int srv = socket(AF_INET, SOCK_STREAM, 0);
  if (srv < 0) return 1;
  int one = 1;
  setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);
  sockaddr_in sa;
  memset(&sa, 0, sizeof sa);
  sa.sin_family = AF_INET;
  inet_pton(AF_INET, host.c_str(), &sa.sin_addr);
  sa.sin_port = htons(port);
  if (bind(srv, (sockaddr*)&sa, sizeof sa) < 0) {
    printf("%s: Failed to bind to '%s' for server '127.0.0.1': Address already in use\n", "sh", addrPort.c_str());
    close(srv);
    return 1;
  }
  listen(srv, 16);
  char tbuf[128];
  time_t now = time(nullptr);
  struct tm l;
  localtime_r(&now, &l);
  strftime(tbuf, sizeof tbuf, "[%a %b %d %H:%M:%S %Y]", &l);
  printf("%s PHP 8.6.0-dev Development Server (http://%s:%d) started\n", tbuf, host.c_str(), port);
  fflush(stdout);
  std::vector<int> clients;
  for (;;) {
    pollfd pf;
    pf.fd = srv;
    pf.events = POLLIN;
    if (poll(&pf, 1, -1) <= 0) continue;
    sockaddr_in ca;
    socklen_t cl = sizeof ca;
    int c = accept(srv, (sockaddr*)&ca, &cl);
    if (c < 0) continue;
    char ip[64];
    inet_ntop(AF_INET, &ca.sin_addr, ip, sizeof ip);
    int cport = ntohs(ca.sin_port);
    now = time(nullptr);
    localtime_r(&now, &l);
    strftime(tbuf, sizeof tbuf, "[%a %b %d %H:%M:%S %Y]", &l);
    printf("%s %s:%d Accepted\n", tbuf, ip, cport);
    fflush(stdout);
    // read request
    std::string req;
    char buf[4096];
    for (;;) {
      ssize_t r = read(c, buf, sizeof buf);
      if (r <= 0) break;
      req.append(buf, r);
      if (req.find("\r\n\r\n") != std::string::npos) break;
    }
    std::string method = "GET", uri = "/", ver = "HTTP/1.1";
    {
      size_t s1 = req.find(' ');
      if (s1 != std::string::npos) { method = req.substr(0, s1); size_t s2 = req.find(' ', s1 + 1); if (s2 != std::string::npos) { uri = req.substr(s1 + 1, s2 - s1 - 1); size_t s3 = req.find("\r\n", s2); if (s3 != std::string::npos) ver = req.substr(s2 + 1, s3 - s2 - 1); } }
    }
    std::string path = uri;
    std::string query;
    size_t q = path.find('?');
    if (q != std::string::npos) { query = path.substr(q + 1); path = path.substr(0, q); }
    std::string file = docroot + path;
    // resolve index
    struct stat st;
    std::string resp;
    if (stat(file.c_str(), &st) == 0 && S_ISDIR(st.st_mode)) {
      std::string idx = file + "/index.php";
      if (stat(idx.c_str(), &st) == 0) file = idx;
    }
    bool ok = false;
