// ---------- syntax highlighting ----------
static std::string htmlEsc(const std::string &s) {
  std::string out;
  for (char c : s) {
    if (c == '<') out += "&lt;";
    else if (c == '>') out += "&gt;";
    else if (c == '&') out += "&amp;";
    else if (c == '"') out += "&quot;";
    else out += c;
  }
  return out;
}

std::string highlightSource(const std::string &src) {
  std::string out = "<pre><code style=\"color: #000000\">";
  // walk through with a mini-lexer
  size_t i = 0;
  bool inPhp = false;
  std::string colorDefault = "<span style=\"color: #0000BB\">";
  std::string colorKeyword = "<span style=\"color: #007700\">";
  std::string colorString = "<span style=\"color: #DD0000\">";
  std::string colorComment = "<span style=\"color: #FF8000\">";
  std::string spanEnd = "</span>";
  auto isKw = [](const std::string &w) {
    static const char *kws[] = {"function","if","else","elseif","while","for","foreach","switch","case","default","break","continue","return","echo","print","class","interface","trait","extends","implements","new","clone","try","catch","finally","throw","unset","isset","empty","exit","die","global","static","const","as","and","or","xor","not","list","array","do","require","include","require_once","include_once","namespace","use","goto","fn","match","enum","yield","instanceof","true","false","null",nullptr};
    for (auto k = kws; *k; k++) if (lc(std::string(*k)) == lc(w)) return true;
    return false;
  };
  std::string cur;   // pending default-color text
  std::string tag;   // current html tag text
  auto flush = [&](const std::string &txt, const std::string &color) {
    if (txt.empty()) return;
    out += color;
    out += htmlEsc(txt);
    out += spanEnd;
  };
  while (i < src.size()) {
    if (!inPhp) {
      if (src.compare(i, 5, "<?php") == 0) { inPhp = true; flush(cur, colorDefault); cur.clear(); out += colorDefault + htmlEsc("&lt;?php") + spanEnd + "\n"; i += 5; continue; }
      if (src.compare(i, 3, "<?=") == 0) { inPhp = true; flush(cur, colorDefault); cur.clear(); out += colorDefault + htmlEsc("&lt;?=") + spanEnd + "\n"; i += 3; continue; }
      if (src.compare(i, 2, "<?") == 0) { inPhp = true; flush(cur, colorDefault); cur.clear(); out += colorDefault + htmlEsc("&lt;?") + spanEnd + "\n"; i += 2; continue; }
      cur += src[i];
      i++;
      continue;
    }
    // in php
    if (src[i] == '?' && i+1 < src.size() && src[i+1] == '>') {
      flush(cur, colorDefault); cur.clear();
      out += colorDefault + htmlEsc("?&gt;") + spanEnd + "\n";
      inPhp = false;
      i += 2;
      continue;
    }
    if (src[i] == '/' && i+1 < src.size() && (src[i+1]=='/' || src[i+1]=='*')) {
      flush(cur, colorDefault); cur.clear();
      size_t start = i;
      if (src[i+1] == '/') { while (i < src.size() && src[i] != '\n') i++; }
      else { i += 2; while (i+1 < src.size() && !(src[i]=='*' && src[i+1]=='/')) i++; i = i + 2 <= src.size() ? i + 2 : i; }
      flush(src.substr(start, i - start), colorComment);
      continue;
    }
    if (src[i] == '\'' || src[i] == '"') {
      flush(cur, colorDefault); cur.clear();
      char q = src[i];
      size_t start = i;
      i++;
      while (i < src.size() && src[i] != q) { if (src[i] == '\\' && i+1 < src.size()) i++; i++; }
      if (i < src.size()) i++;
      flush(src.substr(start, i - start), colorString);
      continue;
    }
    if (isalpha((unsigned char)src[i]) || src[i] == '_') {
      size_t start = i;
      while (i < src.size() && (isalnum((unsigned char)src[i]) || src[i]=='_' || (unsigned char)src[i] >= 0x80)) i++;
      std::string w = src.substr(start, i - start);
      if (isKw(w)) { flush(cur, colorDefault); cur.clear(); flush(w, colorKeyword); }
      else { cur += w; }
      continue;
    }
    if (isdigit((unsigned char)src[i])) {
      size_t start = i;
      while (i < src.size() && (isdigit((unsigned char)src[i]) || src[i]=='.' || src[i]=='x' || src[i]=='b' || src[i]=='_' || (src[i]>='a'&&src[i]<='f'))) i++;
      cur += src.substr(start, i - start);
      continue;
    }
    cur += src[i];
    i++;
  }
  flush(cur, colorDefault);
  out += "</code></pre>";
  return out;
}

std::string stripWhitespace(const std::string &src) {
  std::string out;
  size_t i = 0;
  bool inPhp = false;
  std::string buf;
  auto emit = [&](const std::string &s) { out += s; };
  std::string cur;
  auto flush = [&]() {
    if (cur.empty()) return;
    // trim whitespace between tokens
    std::string trimmed = cur;
    size_t b = 0, e = trimmed.size();
    while (b < e && isspace((unsigned char)trimmed[b])) b++;
    while (e > b && isspace((unsigned char)trimmed[e-1])) e--;
    std::string core = trimmed.substr(b, e - b);
    if (core.empty()) { cur.clear(); return; }
    if (!out.empty() && out.back() != '\n' && !cur.empty() && b > 0) out += " ";
    out += core;
    cur.clear();
  };
  while (i < src.size()) {
    if (!inPhp) {
      if (src.compare(i, 5, "<?php") == 0) { flush(); emit("<?php\n"); inPhp = true; i += 5; continue; }
      if (src.compare(i, 3, "<?=") == 0) { flush(); emit("<?=\n"); inPhp = true; i += 3; continue; }
      if (src.compare(i, 2, "<?") == 0) { flush(); emit("<?\n"); inPhp = true; i += 2; continue; }
      emit(std::string(1, src[i]));
      i++;
      continue;
    }
    if (src[i] == '?' && i+1 < src.size() && src[i+1]=='>') {
      flush();
      emit("?>\n");
      inPhp = false;
      i += 2;
      continue;
    }
    if (src[i] == '/' && i+1 < src.size() && (src[i+1]=='/' || src[i+1]=='*')) {
      flush();
      if (src[i+1] == '/') { while (i < src.size() && src[i] != '\n') i++; }
      else { i += 2; while (i+1 < src.size() && !(src[i]=='*' && src[i+1]=='/')) i++; i = i + 2 <= src.size() ? i + 2 : i; }
      continue;
    }
    if (src[i] == '\'' || src[i] == '"') {
      flush();
      char q = src[i];
      size_t start = i;
      i++;
      while (i < src.size() && src[i] != q) { if (src[i] == '\\' && i+1 < src.size()) i++; i++; }
      if (i < src.size()) i++;
      emit(src.substr(start, i - start));
      continue;
    }
    if (src[i] == '\n') { cur += ' '; i++; continue; }
    cur += src[i];
    i++;
  }
  flush();
  return out;
}

