        if (item->op == N_KEYVAL) {
          Value key = evalExpr(item->kids[0]);
          Value val = evalExpr(item->kids[1]);
          bool depr = false;
          Value k = normalizeKey(key, this, n->line, &depr);
          r.arr->set(k, std::make_shared<Value>(std::move(val)));
        } else {
          Value val = evalExpr(item);
          r.arr->set(Value(r.arr->next), std::make_shared<Value>(std::move(val)));
        }
      }
      return sepVal(r);
    }
    case N_ENCAPSTR: {
      std::string out;
      for (Node *k : n->kids) {
        if (!k) continue;
        Value v = evalExpr(k);
        out += toStr(v, this);
      }
      return Value(out);
    }
    case N_BACKTICK: {
      std::string cmd;
      for (Node *k : n->kids) { if (!k) continue; cmd += toStr(evalExpr(k), this); }
      std::string result;
      FILE *f = popen(cmd.c_str(), "r");
      if (f) {
        char buf[4096];
        size_t r;
        while ((r = fread(buf, 1, sizeof buf, f)) > 0) result.append(buf, r);
        pclose(f);
      }
      while (!result.empty() && result.back() == '\n') result.pop_back();
      return Value(result);
    }
    case N_ADD: case N_SUB: case N_MUL: case N_DIV: case N_MOD: case N_POW: {
      Value l = evalExpr(n->kids[0]);
      Value r = evalExpr(n->kids[1]);
      return arith(n->op, l, r, n->line);
    }
    case N_CONCAT: {
      Value l = evalExpr(n->kids[0]);
      Value r = evalExpr(n->kids[1]);
      return concat(l, r, n->line);
    }
    case N_SHL: {
      Value l = evalExpr(n->kids[0]), r = evalExpr(n->kids[1]);
      int64_t x = toInt(l), y = toInt(r);
      if (y < 0) { logError(E_WARNING, "Bit shift by negative number", n->line); y = 0; }
      if (y >= 64) return Value((int64_t)0);
      return Value((int64_t)((uint64_t)x << y));
    }
    case N_SHR: {
      Value l = evalExpr(n->kids[0]), r = evalExpr(n->kids[1]);
      int64_t x = toInt(l), y = toInt(r);
      if (y < 0) { logError(E_WARNING, "Bit shift by negative number", n->line); y = 0; }
      if (y >= 64) return Value(x < 0 ? (int64_t)-1 : (int64_t)0);
      return Value(x >> y);
    }
    case N_BAND: { Value l = evalExpr(n->kids[0]), r = evalExpr(n->kids[1]); return Value(toInt(l) & toInt(r)); }
    case N_BOR: { Value l = evalExpr(n->kids[0]), r = evalExpr(n->kids[1]); return Value(toInt(l) | toInt(r)); }
    case N_BXOR: { Value l = evalExpr(n->kids[0]), r = evalExpr(n->kids[1]); return Value(toInt(l) ^ toInt(r)); }
    case N_AND: { return Value(toBool(evalExpr(n->kids[0])) && toBool(evalExpr(n->kids[1]))); }
    case N_OR: { return Value(toBool(evalExpr(n->kids[0])) || toBool(evalExpr(n->kids[1]))); }
    case N_NOT: return Value(!toBool(evalExpr(n->kids[0])));
    case N_BNOT: return Value(~toInt(evalExpr(n->kids[0])));
    case N_NEG: {
      Value v = evalExpr(n->kids[0]);
      Value nv = numOperand(v, this, n->line, "-", debugTypeStr(v).c_str());
      if (nv.k == VKFloat) return Value(-nv.d);
      return Value(-nv.i);
    }
    case N_POS: {
      Value v = evalExpr(n->kids[0]);
      return numOperand(v, this, n->line, "+", debugTypeStr(v).c_str());
    }
    case N_EQ: case N_NE: case N_SEQ: case N_SNE: case N_LT: case N_LE: case N_GT: case N_GE: case N_SPACESHIP: {
      Value l = evalExpr(n->kids[0]);
      Value r = evalExpr(n->kids[1]);
      if (n->op == N_SEQ) return Value(identValues(l, r));
      if (n->op == N_SNE) return Value(!identValues(l, r));
      int c = cmpValues(l, r, this);
      switch (n->op) {
        case N_EQ: return Value(c == 0);
        case N_NE: return Value(c != 0);
        case N_LT: return Value(c < 0);
        case N_LE: return Value(c <= 0);
        case N_GT: return Value(c > 0);
        case N_GE: return Value(c >= 0);
        case N_SPACESHIP: return Value((int64_t)(c < 0 ? -1 : c > 0 ? 1 : 0));
      }
      return Value();
    }
    case N_INC: return incdec(n, true, true);
    case N_DEC: return incdec(n, false, true);
    case N_PREINC: return incdec(n, true, false);
    case N_PREDEC: return incdec(n, false, false);
    case N_ASSIGN: {
      Value r = evalExpr(n->kids[1]);
      return doAssign(n->kids[0], r, n->line);
    }
    case N_ASSIGN_ADD: case N_ASSIGN_SUB: case N_ASSIGN_MUL: case N_ASSIGN_DIV:
    case N_ASSIGN_MOD: case N_ASSIGN_POW: case N_ASSIGN_CONCAT: case N_ASSIGN_SHL:
    case N_ASSIGN_SHR: case N_ASSIGN_BAND: case N_ASSIGN_BOR: case N_ASSIGN_BXOR:
    case N_ASSIGN_CO: {
      Value r = evalExpr(n->kids[1]);
      return compoundAssign(n->op, n->kids[0], r, n->line);
    }
    case N_NULLCO: {
      Value lv = evalQuiet(n->kids[0]);
      if (lv.k != VKNull) return lv;
      return evalExpr(n->kids[1]);
    }
    case N_COND: {
      Value c = evalExpr(n->kids[0]);
      if (toBool(c)) return evalExpr(n->kids[1]);
      return evalExpr(n->kids[2]);
    }
    case N_INSTANCEOF: {
      Ref lv = std::make_shared<Value>(evalExpr(n->kids[0]));
      Node *r = n->kids[1];
      if (r->op == N_NAME) return Value(objInstanceOfName(lv, r->name));
      if (r->op == N_DYNAMICNAME) {
        Value nm = evalExpr(r->kids[0]);
        return Value(objInstanceOfName(lv, toStr(nm, this)));
      }
      if (r->op == N_STATIC || r->op == N_SELF || r->op == N_PARENT) {
        auto c = resolveClassRef(r);
        return Value(c && objInstanceOf(lv, c));
      }
      return Value(false);
    }
    case N_CAST: {
      Value v = evalExpr(n->kids[0]);
      std::string t = n->text;
      if (t == "int" || t == "integer" || t == "long") return Value(toInt(v));
      if (t == "float" || t == "double" || t == "real") return Value(toFloat(v));
      if (t == "string" || t == "binary") {
        bool isnan = false;
        std::string s = toStr(v, this, &isnan);
        if (isnan) logError(E_WARNING, "unexpected NAN value was coerced to string", n->line);
        return Value(s);
      }
      if (t == "bool" || t == "boolean") return Value(toBool(v));
      if (t == "array") {
        if (v.k == VKArr) return sepVal(v);
        Value a = arrayValue();
        if (v.k != VKNull) a.arr->set(Value((int64_t)0), std::make_shared<Value>(sepVal(v)));
        return sepVal(a);
      }
      if (t == "object") {
        if (v.k == VKObj) return v;
        Value o = newObj("stdClass");
        if (v.k != VKNull) o.obj->setProp("scalar", std::make_shared<Value>(sepVal(v)));
        return o;
      }
      if (t == "unset") return Value();
      return v;
    }
    case N_ISSET: {
      for (Node *k : n->kids) {
        if (!issetExpr(k)) return Value(false);
      }
      return Value(true);
    }
    case N_EMPTY: {
      if (n->kids.empty()) return Value(true);
      Value v = evalQuiet(n->kids[0]);
      return Value(!toBool(v));
    }
    case N_UNSET: {
      for (Node *k : n->kids) unsetExpr(k);
      return Value();
    }
    case N_EXIT: {
      int code = 0;
      if (!n->kids.empty()) {
        Value v = evalExpr(n->kids[0]);
        if (v.k == VKInt) code = (int)v.i;
        else if (v.k == VKStr) code = v.s.empty() ? 0 : 1;
        else if (v.k == VKBool) code = v.b ? 0 : 254;
        else if (v.k == VKFloat) code = (int)v.d;
      }
      throw PHPExit(code);
    }
    case N_RETURN: case N_THROW: case N_ECHO: case N_PRINT: case N_BREAK: case N_CONTINUE:
      return evalStmt(n);
    case N_GOTO: throw PHPGoto(n->name);
    case N_CALL: return evalCall(n);
    case N_NEW: return evalNew(n);
    case N_FUNC: case N_CLOSURE: case N_ARROW: return evalClosureNode(n);
    case N_CALLABLE_PAREN: {
      Value v = evalExpr(n->kids[0]);
      return v;
    }
    case N_CLONE: {
      Value v = evalExpr(n->kids[0]);
      if (v.k != VKObj) return v;
      return cloneObject(v, n->line);
    }
    case N_MATCH: {
      Value subj = evalExpr(n->kids[0]);
      for (Node *arm : n->kids[1]->kids) {
        if (arm->flags & 1) continue;
        for (Node *c : arm->kids) {
          if (!c || c == arm->kids.back()) continue;
          Value cv = evalExpr(c);
          if (identValues(subj, cv)) return evalExpr(arm->kids.back());
        }
      }
      for (Node *arm : n->kids[1]->kids) {
        if (arm->flags & 1) return evalExpr(arm->kids.back());
      }
      fatal("UnhandledMatchError", "Unhandled match case " + matchCaseStr(subj, this), n->line);
      return Value();
    }
    case N_YIELD: {
      fatal("Error", "Cannot use yield outside of a generator function", n->line);
      return Value();
    }
    case N_INCLUDE: case N_INCLUDE_ONCE: case N_REQUIRE: case N_REQUIRE_ONCE: {
      Value v = evalExpr(n->kids[0]);
      std::string path = toStr(v, this);
      return includeFile(path, n->op, n->line);
    }
    case N_REF: {
      Ref cell = evalRef(n->kids[0], false);
      if (!cell) return Value();
      return *cell;
    }
    case N_NAMEDARG: return evalExpr(n->kids[0]);
    case N_SPREAD: return evalExpr(n->kids[0]);
    case N_NAME: {
      std::string nm = n->name;
      if (lc(nm) == "true") return Value(true);
      if (lc(nm) == "false") return Value(false);
      if (lc(nm) == "null") return Value();
      bool found = false;
      Ref c = constGet(nm, &found);
      if (found) return *c;
      if (nm == "__LINE__") return Value((int64_t)n->line);
      if (nm == "__FILE__") return Value(stack.empty() ? curFile : stack.back().file);
      if (nm == "__DIR__") {
        std::string f = stack.empty() ? curFile : stack.back().file;
        size_t p = f.find_last_of('/');
        return Value(p == std::string::npos ? std::string(".") : f.substr(0, p));
      }
      if (nm == "__FUNCTION__") {
        return Value(stack.size() > 1 && stack.back().fn ? stack.back().fn->name : std::string("{main}"));
      }
      if (nm == "__CLASS__") {
        return Value(stack.size() > 1 && stack.back().clsCtx ? stack.back().clsCtx->name : std::string(""));
      }
      if (nm == "__METHOD__") {
        if (stack.size() > 1 && stack.back().clsCtx && stack.back().fn)
          return Value(stack.back().clsCtx->name + "::" + stack.back().fn->name);
        if (stack.size() > 1 && stack.back().fn) return Value(stack.back().fn->name);
        return Value("{main}");
      }
      if (nm == "__NAMESPACE__") return Value(std::string(""));
      if (lc(nm) == "self" || lc(nm) == "parent" || lc(nm) == "static") return Value(std::string(nm));
      fatal("Error", "Undefined constant \"" + nm + "\"", n->line);
      return Value();
    }
    case N_NSNAME: return Value(std::string(""));
    case N_DYNAMICPROP: {
      Ref o2 = std::make_shared<Value>(evalExpr(n->kids[0]->kids[0]));
      Value nm = evalExpr(n->kids[1]);
      return propRead(o2, toStr(nm, this), n->line, false);
    }
    case N_PROP: {
      Ref o2 = std::make_shared<Value>(evalExpr(n->kids[0]));
      return propRead(o2, n->kids[1]->name, n->line, false);
    }
    case N_MCALL: {
      Ref o2 = std::make_shared<Value>(evalExpr(n->kids[0]));
      return propRead(o2, n->kids[1]->name, n->line, (n->flags & 1) != 0);
    }
    case N_SCALL: {
      Node *clsNode = n->kids[0];
      Node *propNode = n->kids[1];
      std::shared_ptr<ClassDef> c = resolveClassRef(clsNode);
      if (!c) {
        std::string cn = clsNode->op == N_NAME ? clsNode->name : std::string("");
        fatal("Error", "Class \"" + cn + "\" not found", n->line);
      }
      if (propNode->op == N_VAR) return staticPropGet(c, propNode->name, n->line);
      if (propNode->op == N_NAME) return classConstGet(c, propNode->name, n->line);
      if (propNode->op == N_DYNAMICPROP) {
        Value nm = evalExpr(propNode->kids[0]);
        if (lc(toStr(nm, this)) == "class") return Value(c->name);
        return classConstGet(c, toStr(nm, this), n->line);
      }
      if (lc(propNode->name) == "class") return Value(c->name);
      return Value();
    }
    case N_INDEX: {
      Ref base;
      if (n->kids[0] && (n->kids[0]->op == N_VAR || n->kids[0]->op == N_DYNAMICNAME ||
                         n->kids[0]->op == N_INDEX || n->kids[0]->op == N_PROP ||
                         n->kids[0]->op == N_DYNAMICPROP || n->kids[0]->op == N_SPROP)) {
        base = evalRef(n->kids[0], false);
      } else {
        base = std::make_shared<Value>(evalExpr(n->kids[0]));
      }
      Value key = evalExpr(n->kids[1]);
      return indexRead(base, key, n->line, (n->flags & 4) != 0);
    }
    case N_SPROP: {
      std::shared_ptr<ClassDef> c = resolveClassRef(n->kids[0]);
      if (!c) fatal("Error", "Class not found", n->line);
      return staticPropGet(c, n->kids[1]->name, n->line);
    }
    case N_SELF: case N_PARENT: case N_STATIC:
      return Value(std::string(""));
    case N_DECLARE: return Value(true);
    case N_LIST_EXPR: return Value();
    default:
      fatal("Error", "Unknown expression", n->line);
      return Value();
  }
}
