Value Interp::evalClosureNode(Node *n) {
  auto fd = std::make_shared<FuncDef>();
  fd->name = "{closure}";
  fd->lname = "{closure}";
  fd->displayName = "{closure}";
  fd->line = n->line;
  fd->isClosure = true;
  fd->isArrow = n->op == N_ARROW;
  fd->byRef = (n->flags & 1) != 0;
  fd->isStatic = (n->flags & 2) != 0;
  if (n->kids.size() > 1) fd->body = n->kids[1];
  fd->params = n->params;
  auto o = std::make_shared<ObjData>();
  o->kind = 1;
  o->clsName = "Closure";
  o->cls = findClass("Closure");
  o->handle = ++objCount;
  o->closureFn = fd;
  // $this capture
  if (!fd->isStatic && !stack.empty() && stack.back().thisObj) {
    o->thisObj = stack.back().thisObj;
  }
  // use list
  if (n->kids.size() > 0 && n->kids[0]) {
    for (Node *u : n->kids[0]->kids) {
      if (!u) continue;
      if (u->op != N_VAR) continue;
      Ref srcCell = findVar(u->name);
      if (!srcCell) srcCell = newVar(u->name);
      Ref cap;
      if (u->i != 0) cap = srcCell;
      else cap = std::make_shared<Value>(sepVal(*srcCell));
      o->useVars.push_back({cap, u->i != 0});
      o->argNames.push_back(u->name);
    }
  }
  // arrow functions: auto capture by value
  if (fd->isArrow) {
    std::vector<std::string> names;
    collectVarNames(n->kids[1], names);
    for (auto &nm : names) {
      bool isParam = false;
      for (auto &p : fd->params) if (p.name == nm) isParam = true;
      if (isParam) continue;
      bool already = false;
      for (auto &uv : o->argNames) if (uv == nm) already = true;
      if (already) continue;
      if (nm == "this") continue;
      Ref srcCell = findVar(nm);
      if (!srcCell) continue;
      o->useVars.push_back({std::make_shared<Value>(sepVal(*srcCell)), false});
      o->argNames.push_back(nm);
    }
  }
  Value v; v.k = VKObj; v.obj = o;
  return v;
}
