  Lexer L(s, e - s, "t");
  for (int i = 0; i < 12; i++) {
    Token t = L.next();
    if (t.type == TK_EOF) { printf("EOF\n"); break; }
    printf("tok type=%d text=[%s] line=%d\n", t.type, t.text.c_str(), t.line);
  }
}
static void dumpNode(Node *n, int d) {
  if (!n) { printf("%*s(null)\n", d*2, ""); return; }
  printf("%*sop=%d line=%d name=%s kids=%zu\n", d*2, "", n->op, n->line, n->name.c_str(), n->kids.size());
  for (auto k : n->kids) dumpNode(k, d+1);
}
int main(int argc, char **argv) {
  Program prog; g_prog = &prog;
  FILE *f = fopen(argv[1], "rb");
  std::string src;
  char buf[4096]; size_t r;
  while ((r = fread(buf,1,sizeof buf,f))>0) src.append(buf,r);
  fclose(f);
  if (argc > 2 && strcmp(argv[2], "tok") == 0) { dumpTok(src.data(), src.data()+src.size()); return 0; }
