// ---------- sorting ----------
static bool cmpForSort(const Value &a, const Value &b, Interp *I) { return cmpValues(a, b, I) < 0; }
static Value sortStable(std::vector<std::pair<Value, Ref>> &items, Interp *I, int flags) {
  std::stable_sort(items.begin(), items.end(), [I, flags](const std::pair<Value, Ref> &x, const std::pair<Value, Ref> &y) {
    if (flags == 1) { // numeric
      double a = toFloat(*x.second), b = toFloat(*y.second);
      if (a == b) return false;
      return a < b;
    } else if (flags == 2) { // string
      int c = x.second->s.compare(y.second->s);
      if (c == 0) return false;
      return c < 0;
    } else if (flags == 6) { // natural
      // approximate natural compare
      const std::string &a = toStr(*x.second, I), &b = toStr(*y.second, I);
      size_t i = 0, j = 0;
      while (i < a.size() && j < b.size()) {
        if (isdigit((unsigned char)a[i]) && isdigit((unsigned char)b[j])) {
          size_t i2 = i, j2 = j;
          while (i2 < a.size() && isdigit((unsigned char)a[i2])) i2++;
          while (j2 < b.size() && isdigit((unsigned char)b[j2])) j2++;
          std::string na = a.substr(i, i2 - i), nb = b.substr(j, j2 - j);
          size_t k = 0;
          while (k < na.size() && na[k] == '0') k++;
          size_t m = 0;
          while (m < nb.size() && nb[m] == '0') m++;
          std::string a1 = na.substr(k), b1 = nb.substr(m);
          if (a1.size() != b1.size()) return a1.size() < b1.size();
          int c = a1.compare(b1);
          if (c) return c < 0;
          i = i2; j = j2;
          continue;
        }
        if (tolower((unsigned char)a[i]) != tolower((unsigned char)b[j]))
          return (int)tolower((unsigned char)a[i]) < (int)tolower((unsigned char)b[j]);
        i++; j++;
      }
      return false;
    }
    return cmpValues(*x.second, *y.second, I) < 0;
  });
  return Value();
}

