#include "b_impl.h"
#include "interp.h"
#include "b_date.h"
#include <ctime>
#include <cstring>
#include <cmath>

static time_t tsOf(const Ref &obj) {
  Ref ts = obj->obj ? obj->obj->getProp("__ts") : nullptr;
  return ts ? (time_t)toInt(*ts) : time(nullptr);
}

static Value newDateTime(Interp &I, time_t t, const char *cls = "DateTime") {
  Value o = I.newObj(cls);
  o.obj->setProp("__ts", std::make_shared<Value>((int64_t)t));
  return o;
}

static int64_t parseDateTimeStr(const std::string &s, int line, Interp &I) {
  std::string str = s;
  size_t b = 0;
  while (b < str.size() && isspace((unsigned char)str[b])) b++;
  str = str.substr(b);
  if (str.empty() || lc(str) == "now") return (int64_t)time(nullptr);
  if (lc(str) == "today") {
    time_t t = time(nullptr);
    struct tm l; localtime_r(&t, &l);
    l.tm_hour = 0; l.tm_min = 0; l.tm_sec = 0;
    return (int64_t)timelocal(&l);
  }
  bool ok = false;
  int64_t r = phpStrtotime(str, (int64_t)time(nullptr), &ok);
  if (!ok) {
    I.fatal("DateMalformedStringException", "Failed to parse time string (" + s + ")", line);
  }
  return r;
}

Value b_date_create(BArgs &a) {
  time_t t = a.has(0) ? (time_t)parseDateTimeStr(a.str(0), a.line, a.I) : time(nullptr);
  return newDateTime(a.I, t);
}
Value b_date_create_immutable(BArgs &a) {
  time_t t = a.has(0) ? (time_t)parseDateTimeStr(a.str(0), a.line, a.I) : time(nullptr);
  return newDateTime(a.I, t, "DateTimeImmutable");
}
Value b_date_create_immutable_from_format(BArgs &a) { return b_date_create_immutable(a); }
Value b_date_create_from_format(BArgs &a) {
  a.need(2);
  std::string fmt = a.str(0), str = a.str(1);
  // extract date components from the format
  int y = -1, mo = 1, d = 1, h = 0, mi = 0, sec = 0;
  size_t si = 0;
  for (size_t i = 0; i < fmt.size(); i++) {
    char c = fmt[i];
    if (c == '\\') { i++; continue; }
    if (si >= str.size()) break;
    if (c == 'Y') {
