// ---------- unserialize ----------
struct Unser {
  const char *p, *end;
  Interp *I;
  int line;
  Unser(const char *s, size_t n, Interp *I_, int l) : p(s), end(s+n), I(I_), line(l) {}
  void skip() { while (p < end && (*p==' '||*p=='\r'||*p=='\n')) p++; }
  bool fail = false;
  Value readValue();
  int64_t readInt() {
    skip();
    int64_t v = 0;
    bool neg = false;
    if (p < end && *p == '-') { neg = true; p++; }
    while (p < end && isdigit((unsigned char)*p)) { v = v*10 + (*p - '0'); p++; }
    return neg ? -v : v;
  }
  std::string readStr(int64_t len) {
    skip();
    if (p >= end || *p != '"') { fail = true; return ""; }
    p++;
    std::string out;
    for (int64_t i = 0; i < len && p < end; i++) out += *p++;
    if (p < end && *p == '"') p++;
    return out;
  }
};

Value Unser::readValue() {
  skip();
  if (p >= end) { fail = true; return Value(); }
  char c = *p;
  if (c == 'N') { p++; if (p < end && *p == ';') p++; return Value(); }
  if (c == 'b') { p++; if (p < end && *p == ':') p++; int64_t v = readInt(); if (p < end && *p == ';') p++; return Value(v != 0); }
  if (c == 'i') { p++; if (p < end && *p == ':') p++; int64_t v = readInt(); if (p < end && *p == ';') p++; return Value(v); }
  if (c == 'd') {
    p++;
    if (p < end && *p == ':') p++;
    std::string num;
    while (p < end && (isdigit((unsigned char)*p) || *p=='-'||*p=='+'||*p=='.'||*p=='e'||*p=='E'||*p=='N'||*p=='A'||*p=='I')) { num += *p; p++; }
    if (p < end && *p == ';') p++;
    if (num == "INF") return Value(HUGE_VAL);
    if (num == "-INF") return Value(-HUGE_VAL);
    if (num == "NAN") return Value(NAN);
    return Value(strtod(num.c_str(), nullptr));
  }
  if (c == 's') {
    p++;
    if (p < end && *p == ':') p++;
    int64_t len = readInt();
    if (p < end && *p == ':') p++;
    std::string s = readStr(len);
    if (p < end && *p == ';') p++;
    return Value(s);
  }
  if (c == 'a') {
    p++;
    if (p < end && *p == ':') p++;
    int64_t n = readInt();
    if (p < end && *p == ':') p++;
    if (p < end && *p == '{') p++;
    Value r = I->arrayValue();
    for (int64_t i = 0; i < n && !fail; i++) {
      Value k = readValue();
      Value v = readValue();
      r.arr->set(normalizeKey(k, I, line), std::make_shared<Value>(sepVal(v)));
    }
    if (p < end && *p == '}') p++;
    return sepVal(r);
  }
  if (c == 'O') {
    p++;
    if (p < end && *p == ':') p++;
    int64_t len = readInt();
    if (p < end && *p == ':') p++;
    std::string cls = readStr(len);
    if (p < end && *p == ':') p++;
    int64_t n = readInt();
    if (p < end && *p == ':') p++;
    if (p < end && *p == '{') p++;
    Value o;
    if (lc(cls) == "stdclass") o = I->newObj("stdClass");
    else if (I->classes.count(lc(cls))) o = I.newObj(cls.c_str());
    else o = I.newObj("__PHP_Incomplete_Class");
    for (int64_t i = 0; i < n && !fail; i++) {
      Value k = readValue();
      Value v = readValue();
      std::string name = toStr(k, I);
      o.obj->setProp(name, std::make_shared<Value>(sepVal(v)));
    }
    if (p < end && *p == '}') p++;
    return o;
  }
  if (c == 'R' || c == 'r') {
    p++;
    if (p < end && *p == ':') p++;
    readInt();
    if (p < end && *p == ';') p++;
    return Value();
  }
  fail = true;
  return Value();
}

Value b_unserialize(BArgs &a) {
  a.need(1);
  std::string s = a.str(0);
  Unser u(s.c_str(), s.size(), &a.I, a.line);
  Value r;
  try {
    r = u.readValue();
  } catch (...) {
    u.fail = true;
  }
  if (u.fail) {
    a.I.logError(E_NOTICE, "unserialize(): Error at offset 0", a.line);
    return Value(false);
  }
  return sepVal(r);
}
