// ---------- unserialize ----------
struct Unser {
  const char *p, *end;
  Interp *I;
  int line;
  Unser(const char *s, size_t n, Interp *I_, int l) : p(s), end(s+n), I(I_), line(l) {}
  void skip() { while (p < end && (*p==' '||*p=='\r'||*p=='\n')) p++; }
  bool fail = false;
  Value readValue();
  int64_t readInt() {
    skip();
    int64_t v = 0;
    bool neg = false;
    if (p < end && *p == '-') { neg = true; p++; }
    while (p < end && isdigit((unsigned char)*p)) { v = v*10 + (*p - '0'); p++; }
    return neg ? -v : v;
  }
  std::string readStr(int64_t len) {
    skip();
    if (p >= end || *p != '"') { fail = true; return ""; }
    p++;
    std::string out;
    for (int64_t i = 0; i < len && p < end; i++) out += *p++;
    if (p < end && *p == '"') p++;
    return out;
  }
};

Value Unser::readValue() {
  skip();
  if (p >= end) { fail = true; return Value(); }
  char c = *p;
  if (c == 'N') { p++; if (p < end && *p == ';') p++; return Value(); }
  if (c == 'b') { p++; if (p < end && *p == ':') p++; int64_t v = readInt(); if (p < end && *p == ';') p++; return Value(v != 0); }
  if (c == 'i') { p++; if (p < end && *p == ':') p++; int64_t v = readInt(); if (p < end && *p == ';') p++; return Value(v); }
  if (c == 'd') {
    p++;
    if (p < end && *p == ':') p++;
    std::string num;
    while (p < end && (isdigit((unsigned char)*p) || *p=='-'||*p=='+'||*p=='.'||*p=='e'||*p=='E'||*p=='N'||*p=='A'||*p=='I')) { num += *p; p++; }
    if (p < end && *p == ';') p++;
    if (num == "INF") return Value(HUGE_VAL);
    if (num == "-INF") return Value(-HUGE_VAL);
    if (num == "NAN") return Value(NAN);
    return Value(strtod(num.c_str(), nullptr));
