    return sepVal(r);
  }
  if (c == 'O') {
    p++;
    if (p < end && *p == ':') p++;
    int64_t len = readInt();
    if (p < end && *p == ':') p++;
    std::string cls = readStr(len);
    if (p < end && *p == ':') p++;
    int64_t n = readInt();
    if (p < end && *p == ':') p++;
    if (p < end && *p == '{') p++;
    Value o;
