std::string escapeHtmlStr(const std::string &s, int quoteStyle, bool doubleEncode, const std::string &charset) {
  std::string out;
  for (unsigned char c : s) {
    switch (c) {
      case '<': out += "&lt;"; continue;
      case '>': out += "&gt;"; continue;
      case '&': out += "&amp;"; continue;
      case '"': if (quoteStyle == 1 || quoteStyle == 3) out += doubleEncode ? "&amp;quot;" : "&quot;"; else out += "\""; continue;
      case '\'': if (quoteStyle == 3) out += doubleEncode ? "&amp;#039;" : "&#039;"; else if (quoteStyle == 1) out += doubleEncode ? "&amp;&#039;" : "&#039;"; else out += "'"; continue;
      default: out += (char)c; continue;
    }
  }
  return out;
}

Value b_htmlspecialchars(BArgs &a) {
  a.need(1);
  std::string s = a.str(0);
  int qs = (int)a.num(1, 3);
  if (a.has(2) && toBool(a[2])) {
    // double encode
    s = escapeHtmlStr(s, qs, false, "UTF-8");
    return Value(escapeHtmlStr(s, qs, true, "UTF-8"));
