Value b_preg_replace_callback(BArgs &a) {
  a.need(3);
  PcreCtx pc = compilePattern(a.I, a.str(0), a.line);
  const Value &sv = a[2];
  auto doOne = [&](const std::string &subj) -> std::string {
    std::string out;
    size_t pos = 0;
    pcre2_match_data *md = pcre2_match_data_create_from_pattern(pc.code, nullptr);
    uint32_t count = pcre2_get_ovector_count(md);
    for (;;) {
      int rc = pcre2_match(pc.code, (PCRE2_SPTR)subj.c_str(), subj.size(), pos, 0, md, nullptr);
      if (rc == PCRE2_ERROR_NOMATCH || rc < 0) { out += subj.substr(pos); break; }
      PCRE2_SIZE *ov = pcre2_get_ovector_pointer(md);
      out += subj.substr(pos, ov[0] - pos);
      Value arr = a.I.arrayValue();
      for (uint32_t i = 0; i < count; i++) {
        if (ov[i*2] == PCRE2_UNSET) arr.arr->pushBack(std::make_shared<Value>(std::string("")));
        else arr.arr->pushBack(std::make_shared<Value>(subj.substr(ov[i*2], ov[i*2+1] - ov[i*2])));
      }
      std::vector<Arg> cargs;
      Arg x; x.cell = std::make_shared<Value>(sepVal(arr));
      cargs.push_back(x);
      Value rep = a.I.callFunc(a.cell(1), cargs, a.line, "callback");
      out += toStr(rep, &a.I);
      pos = ov[1];
      if (ov[1] == ov[0]) { if (pos < subj.size()) out += subj[pos]; pos++; }
      if (pos > subj.size()) break;
    }
    pcre2_match_data_free(md);
    return out;
  };
  if (sv.k == VKArr) {
    Value r = a.I.arrayValue();
    for (auto &en : sv.arr->e) r.arr->set(en.key, std::make_shared<Value>(doOne(toStr(*en.val, &a.I))));
    pcre2_code_free(pc.code);
    return sepVal(r);
  }
  std::string out = doOne(sv.s);
  pcre2_code_free(pc.code);
  return Value(out);
}
EOF
